INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.KUSIKI.T1_MATAMSHI_BORA.MATAMSHI', 'KISW.G4.KUSIKI.T1_MATAMSHI_BORA', 'kiswahili', 4, 'Tofautisha sauti p/b, t/d, k/g na ch/j katika silabi, maneno na vitanzandimi', ARRAY['KISW.G4.KUSIKI.T1_MATAMSHI_BORA.a', 'KISW.G4.KUSIKI.T1_MATAMSHI_BORA.b', 'KISW.G4.KUSIKI.T1_MATAMSHI_BORA.c', 'KISW.G4.KUSIKI.T1_MATAMSHI_BORA.d']::text[], 'Hears, says and writes the right sound in syllables and words with p/b, t/d, k/g na ch/j (tamu and damu, koti and goti), picks the word that matches the meaning, and tells a real kitanzandimi from an ordinary sentence, in 8 of 10 new items.', '["chagua neno ulilosikia","chagua maana ya neno","jaza pengo kwa neno sahihi","tambua kitanzandimi"]'::jsonb, '["recall","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.MSAMIATI', 'KISW.G4.KUSOMA.T1_KUSOMA_KWA_UFAHAMU', 'kiswahili', 4, 'Elewa na tumia msamiati wa kifungu', ARRAY['KISW.G4.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.a', 'KISW.G4.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.b']::text[], 'Gives the meaning of a word from the sentence it is in and picks the word that fits a gap in a sentence, without choosing a look-alike, a nearby or an opposite word, in 8 of 10 new items.', '["choose the meaning","fill the gap","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.UFAHAMU_HADITHI', 'KISW.G4.KUSOMA.T1_KUSOMA_KWA_UFAHAMU', 'kiswahili', 4, 'Elewa ujumbe wa kifungu cha hadithi', ARRAY['KISW.G4.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.c']::text[], 'Answers who, what and which questions from a short story, puts four events in order, and gives the main message, without choosing a detail for the message or an answer from outside the story, in 8 of 10 new questions.', '["choose from a passage","type a short answer","put events in order"]'::jsonb, '["recall","inference"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.KUANDI.T1_INSHA_YA_WASIFU.AINA_ZA_INSHA', 'KISW.G4.KUANDI.T1_INSHA_YA_WASIFU', 'kiswahili', 4, 'Tambua insha ya wasifu, masimulizi na maelezo na sehemu za insha', ARRAY['KISW.G4.KUANDI.T1_INSHA_YA_WASIFU.a', 'KISW.G4.KUANDI.T6_INSHA_YA_WASIFU.a', 'KISW.G4.KUANDI.T2_INSHA_YA_MASIMULIZI.a', 'KISW.G4.KUANDI.T8_INSHA_YA_MASIMULIZI.a', 'KISW.G4.KUANDI.T10_INSHA_YA_MASIMULIZI.a', 'KISW.G4.KUANDI.T5_INSHA_YA_MAELEZO.a', 'KISW.G4.KUANDI.T7_INSHA_YA_MAELEZO.a', 'KISW.G4.KUANDI.T9_INSHA_YA_MAELEZO.a']::text[], 'Names the kind of insha from a short text (wasifu describes a person or thing, masimulizi tells what happened in order, maelezo explains) and the part of an insha (utangulizi, kiini, hitimisho), in 8 of 10 new items.', '["choose the kind","fill the gap","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.KUANDI.T1_INSHA_YA_WASIFU.INSHA_WASIFU', 'KISW.G4.KUANDI.T1_INSHA_YA_WASIFU', 'kiswahili', 4, 'Tambua na andika insha ya wasifu', ARRAY['KISW.G4.KUANDI.T1_INSHA_YA_WASIFU.b']::text[], 'Tells insha ya wasifu from other kinds of writing and its parts, and writes a description of a person, place or thing with describing words that agree with their nouns and no story of events; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.SARUFI.T1_NOMINO.NOMINO', 'KISW.G4.SARUFI.T1_NOMINO', 'kiswahili', 4, 'Tambua na tumia nomino', ARRAY['KISW.G4.SARUFI.T1_NOMINO.a', 'KISW.G4.SARUFI.T1_NOMINO.b', 'KISW.G4.SARUFI.T1_NOMINO.c']::text[], 'Picks the noun (the name of a person, animal, place or thing) from a group of words and a sentence, and fills a gap with a noun, without choosing a verb, an adjective or an adverb, in 8 of 10 new items.', '["choose the noun","fill the gap","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.SARUFI.T1_VITENZI.VITENZI', 'KISW.G4.SARUFI.T1_VITENZI', 'kiswahili', 4, 'Tambua na tumia vitenzi', ARRAY['KISW.G4.SARUFI.T1_VITENZI.a', 'KISW.G4.SARUFI.T1_VITENZI.b', 'KISW.G4.SARUFI.T1_VITENZI.c']::text[], 'Picks the verb (the word for what someone or something does) from a group of words and a sentence, and fills a gap with a verb, without choosing a noun, an adjective or an adverb, in 8 of 10 new items.', '["choose the verb","fill the gap","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.SARUFI.T1_VIVUMISHI.VIVUMISHI', 'KISW.G4.SARUFI.T1_VIVUMISHI', 'kiswahili', 4, 'Tambua na tumia vivumishi', ARRAY['KISW.G4.SARUFI.T1_VIVUMISHI.a', 'KISW.G4.SARUFI.T1_VIVUMISHI.b', 'KISW.G4.SARUFI.T1_VIVUMISHI.c']::text[], 'Picks the adjective (the word that tells more about a noun) and uses the form that agrees with the noun (mtoto mdogo, watoto wadogo, kiti kikubwa), without choosing a noun or a verb, in 8 of 10 new items.', '["choose the adjective","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.KUSIKI.T2_MAAMKUZI_NA_MAAGANO.MAAMKUZI', 'KISW.G4.KUSIKI.T2_MAAMKUZI_NA_MAAGANO', 'kiswahili', 4, 'Tambua maamkuzi na maagano katika miktadha mbalimbali', ARRAY['KISW.G4.KUSIKI.T2_MAAMKUZI_NA_MAAGANO.a', 'KISW.G4.KUSIKI.T2_MAAMKUZI_NA_MAAGANO.b', 'KISW.G4.KUSIKI.T2_MAAMKUZI_NA_MAAGANO.c']::text[], 'Picks the greeting or farewell that fits the person and the time (hujambo-sijambo, shikamoo-marahaba, habari za asubuhi, kwaheri, usiku mwema), without giving the greeting back as the reply, in 8 of 10 new situations. Using them aloud is a teacher''s check.', '["choose the greeting","fill the gap","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.KUSOMA.T2_KUSOMA_KWA_KINA.KAMUSI', 'KISW.G4.KUSOMA.T2_KUSOMA_KWA_KINA', 'kiswahili', 4, 'Tumia kamusi: mpangilio wa maneno na maana', ARRAY['KISW.G4.KUSOMA.T2_KUSOMA_KWA_KINA.a', 'KISW.G4.KUSOMA.T2_KUSOMA_KWA_KINA.b']::text[], 'Puts words in the order of the alphabet (using the second and third letters when the first match) and says what a dictionary is for, in 8 of 10 new items.', '["choose the first word","fill the gap","spot the mistake"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.KUANDI.T2_INSHA_YA_MASIMULIZI.INSHA_MASIMULIZI', 'KISW.G4.KUANDI.T2_INSHA_YA_MASIMULIZI', 'kiswahili', 4, 'Tambua na andika insha ya masimulizi', ARRAY['KISW.G4.KUANDI.T2_INSHA_YA_MASIMULIZI.a', 'KISW.G4.KUANDI.T2_INSHA_YA_MASIMULIZI.b']::text[], 'Tells insha ya masimulizi from other kinds of writing and its parts, and writes a story of events in the past tense, in order, with a title, an opening, a middle and a closing that gives the lesson; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.SARUFI.T2_VIWAKILISHI.VIWAKILISHI', 'KISW.G4.SARUFI.T2_VIWAKILISHI', 'kiswahili', 4, 'Tambua na tumia viwakilishi', ARRAY['KISW.G4.SARUFI.T2_VIWAKILISHI.a', 'KISW.G4.SARUFI.T2_VIWAKILISHI.b', 'KISW.G4.SARUFI.T2_VIWAKILISHI.c']::text[], 'Picks the pronoun (the word that stands in place of a noun: yeye, wao, sisi, huyu, hawa, yule, wale) that fits the person, number and nearness, without repeating the noun or choosing another word, in 8 of 10 new items.', '["choose the pronoun","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.SARUFI.T2_VIELEZI.VIELEZI', 'KISW.G4.SARUFI.T2_VIELEZI', 'kiswahili', 4, 'Tambua na tumia vielezi', ARRAY['KISW.G4.SARUFI.T2_VIELEZI.a', 'KISW.G4.SARUFI.T2_VIELEZI.b', 'KISW.G4.SARUFI.T2_VIELEZI.c']::text[], 'Picks the adverb (the word that tells how, when or where something is done: polepole, jana, shuleni) and says which of the three it tells, without choosing an adjective or a noun, in 8 of 10 new items.', '["choose the adverb","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.KUSIKI.T3_VITENDAWILI.VITENDAWILI', 'KISW.G4.KUSIKI.T3_VITENDAWILI', 'kiswahili', 4, 'Tambua vitendawili', ARRAY['KISW.G4.KUSIKI.T3_VITENDAWILI.a', 'KISW.G4.KUSIKI.T3_VITENDAWILI.b']::text[], 'Tells a kitendawili from a methali, a nahau and an ordinary sentence, gives the opening words of riddling (Kitendawili! Tega!), and the answer to a known riddle, in 8 of 10 new items. Telling and guessing aloud is a teacher''s check.', '["choose the riddle","fill the gap","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.KUSOMA.T3_KUSOMA_KWA_UFASAHA.UFASAHA_VIPENGELE', 'KISW.G4.KUSOMA.T3_KUSOMA_KWA_UFASAHA', 'kiswahili', 4, 'Tambua vipengele vya kusoma kwa ufasaha', ARRAY['KISW.G4.KUSOMA.T3_KUSOMA_KWA_UFASAHA.a', 'KISW.G4.KUSOMA.T11_KUSOMA_KWA_UFASAHA.a']::text[], 'Names what a fluent reader does (good pronunciation, a fitting voice, a fitting speed, a rest at the marks, signs that fit), without taking fast or loud for good, in 8 of 10 new items. Reading aloud itself is for a teacher to hear.', '["choose what a good reader does","choose the sentence","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.KUSOMA.T3_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'KISW.G4.KUSOMA.T3_KUSOMA_KWA_UFASAHA', 'kiswahili', 4, 'Soma kifungu kwa sauti kwa matamshi bora, kasi ifaayo, sauti ifaayo na ishara', ARRAY['KISW.G4.KUSOMA.T3_KUSOMA_KWA_UFASAHA.b', 'KISW.G4.KUSOMA.T3_KUSOMA_KWA_UFASAHA.c', 'KISW.G4.KUSOMA.T3_KUSOMA_KWA_UFASAHA.d', 'KISW.G4.KUSOMA.T3_KUSOMA_KWA_UFASAHA.e']::text[], 'Reads a short passage aloud at a speaking pace, pauses at the koma and the kikomo, raises the voice for a question and shows feeling for an exclamation, says every sound clearly (no l for r), and uses a matching gesture, judged by the teacher with the KICD rubric; in the app picks the better reading of a line in 8 of 10 new items.', '["chagua usomaji bora","tambua kosa la usomaji","kusoma kwa sauti (mwalimu anasikiliza)"]'::jsonb, '["application","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.KUANDI.T3_KUANDIKA_KWA_TARAKIL.SEHEMU_TARAKILISHI', 'KISW.G4.KUANDI.T3_KUANDIKA_KWA_TARAKIL', 'kiswahili', 4, 'Tambua sehemu za tarakilishi zinazotumika kupigia chapa', ARRAY['KISW.G4.KUANDI.T3_KUANDIKA_KWA_TARAKIL.a']::text[], 'Names the part of a computer for typing and showing (kibodi, kipanya, skrini, kichapishi, the space key) and what each one does, in 8 of 10 new items. Using the computer is a practical task.', '["choose the part","fill the gap","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.KUANDI.T3_KUANDIKA_KWA_TARAKIL.UAKIFISHI', 'KISW.G4.KUANDI.T3_KUANDIKA_KWA_TARAKIL', 'kiswahili', 4, 'Hariri sentensi: herufi kubwa, kikomo, kiulizi, koma na alama ya hisi', ARRAY['KISW.G4.KUANDI.T3_KUANDIKA_KWA_TARAKIL.d']::text[], 'Chooses the sentence with the right capital letter, kikomo (full stop), kiulizi (question mark), koma and alama ya hisi (!), and finds the one mistake in a short note, in 8 of 10 new sentences.', '["choose the correct sentence","fill the gap","spot the mistake"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.KUANDI.T3_KUANDIKA_KWA_TARAKIL.KAZI_TARAKILISHI', 'KISW.G4.KUANDI.T3_KUANDIKA_KWA_TARAKIL', 'kiswahili', 4, 'Fungua tarakilishi, andika kazi na uihifadhi', ARRAY['KISW.G4.KUANDI.T3_KUANDIKA_KWA_TARAKIL.b', 'KISW.G4.KUANDI.T3_KUANDIKA_KWA_TARAKIL.c', 'KISW.G4.KUANDI.T3_KUANDIKA_KWA_TARAKIL.e']::text[], 'Switches the computer on and off in the right way, opens a word processor, types a short text on the theme with spaces and capital letters, and saves it with a clear file name where he can find it again, in 8 of 10 new items or tasks.', '["panga hatua","chagua kitufe sahihi","tambua kosa","kazi ya vitendo (mwalimu anaangalia)"]'::jsonb, '["procedure"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.SARUFI.T3_VIUNGANISHI.VIUNGANISHI', 'KISW.G4.SARUFI.T3_VIUNGANISHI', 'kiswahili', 4, 'Tambua na tumia viunganishi', ARRAY['KISW.G4.SARUFI.T3_VIUNGANISHI.a', 'KISW.G4.SARUFI.T3_VIUNGANISHI.b', 'KISW.G4.SARUFI.T3_VIUNGANISHI.c']::text[], 'Picks the joining word (na, pia, kwa sababu, lakini, ili, au) that fits the meaning of two parts of a sentence, without choosing a noun or a verb or a joining word of another meaning, in 8 of 10 new items.', '["choose the joining word","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.SARUFI.T3_VIHUSISHI.VIHUSISHI', 'KISW.G4.SARUFI.T3_VIHUSISHI', 'kiswahili', 4, 'Tambua na tumia vihusishi', ARRAY['KISW.G4.SARUFI.T3_VIHUSISHI.a', 'KISW.G4.SARUFI.T3_VIHUSISHI.b', 'KISW.G4.SARUFI.T3_VIHUSISHI.c']::text[], 'Picks the relating word (juu ya, chini ya, ndani ya, nje ya, karibu na, mbali na, kwa, kuliko) in a sentence, and chooses the -a of agreement (cha, vya, wa, ya, la) that matches the noun, in 8 of 10 new items.', '["choose the relating word","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.SARUFI.T3_VIHISISHI.VIHISISHI', 'KISW.G4.SARUFI.T3_VIHISISHI', 'kiswahili', 4, 'Tambua na tumia vihisishi', ARRAY['KISW.G4.SARUFI.T3_VIHISISHI.a', 'KISW.G4.SARUFI.T3_VIHISISHI.b', 'KISW.G4.SARUFI.T3_VIHISISHI.c', 'KISW.G4.SARUFI.T3_VIHISISHI.d']::text[], 'Picks the exclamation that fits the feeling in the situation (pole, hongera, samahani, karibu, lo) and picks the exclamation from a sentence, with the exclamation mark, without choosing a noun or a verb, in 8 of 10 new items.', '["choose the exclamation","fill the gap","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.KUSIKI.T4_MANENO_YA_UPOLE.UPOLE', 'KISW.G4.KUSIKI.T4_MANENO_YA_UPOLE', 'kiswahili', 4, 'Tambua na tumia maneno ya upole', ARRAY['KISW.G4.KUSIKI.T4_MANENO_YA_UPOLE.a', 'KISW.G4.KUSIKI.T4_MANENO_YA_UPOLE.b']::text[], 'Picks the polite word or sentence (tafadhali, samahani, asante, pole, naomba) for the situation, and does not choose a command, in 8 of 10 new items. Using them aloud is a teacher''s check.', '["choose the polite sentence","fill the gap","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.KUSOMA.T4_KUSOMA_KWA_MAPANA.USALAMA_DIJITALI', 'KISW.G4.KUSOMA.T4_KUSOMA_KWA_MAPANA', 'kiswahili', 4, 'Zingatia hatua za kiusalama unapotumia kifaa cha kidijitali', ARRAY['KISW.G4.KUSOMA.T4_KUSOMA_KWA_MAPANA.b', 'KISW.G4.KUSOMA.T10_KUSOMA_KIDIJITALI.a']::text[], 'Picks the safe step for a phone, tablet or computer (keep the password secret, show an adult an unknown link, give no home address to a stranger, log out, use a safe site) and not the risky one, in 8 of 10 new situations.', '["choose the safe step","choose the safe sentence","spot the mistake"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.KUSOMA.T4_KUSOMA_KWA_MAPANA.KUSOMA_KIDIJITALI', 'KISW.G4.KUSOMA.T4_KUSOMA_KWA_MAPANA', 'kiswahili', 4, 'Fungua faili, sakura kwenye tovuti salama na usome matini ya kidijitali', ARRAY['KISW.G4.KUSOMA.T4_KUSOMA_KWA_MAPANA.a', 'KISW.G4.KUSOMA.T4_KUSOMA_KWA_MAPANA.c', 'KISW.G4.KUSOMA.T4_KUSOMA_KWA_MAPANA.d']::text[], 'Opens a saved file with the passage (finds the folder, double-clicks the file), searches a safe site with two or three key words, ignores pop-ups and adverts, and reads the passage for its message, in 8 of 10 new items or tasks.', '["chagua hatua sahihi","panga hatua","chagua maneno ya kutafutia","tambua kosa"]'::jsonb, '["procedure","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.KUANDI.T4_BARUA_YA_KIRAFIKI.BARUA', 'KISW.G4.KUANDI.T4_BARUA_YA_KIRAFIKI', 'kiswahili', 4, 'Tambua sehemu za barua ya kirafiki', ARRAY['KISW.G4.KUANDI.T4_BARUA_YA_KIRAFIKI.a', 'KISW.G4.KUANDI.T11_BARUA_YA_KIRAFIKI.a']::text[], 'Names the parts of a friendly letter in their order (anwani ya mwandishi, tarehe, salamu, mwili, hitimisho, jina) and what each holds, in 8 of 10 new items. Writing the letter is composition marking.', '["choose the part","fill the gap","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.KUANDI.T4_BARUA_YA_KIRAFIKI.KUANDIKA_BARUA', 'KISW.G4.KUANDI.T4_BARUA_YA_KIRAFIKI', 'kiswahili', 4, 'Andika barua ya kirafiki kwa muundo na lugha ifaayo', ARRAY['KISW.G4.KUANDI.T4_BARUA_YA_KIRAFIKI.b', 'KISW.G4.KUANDI.T4_BARUA_YA_KIRAFIKI.c']::text[], 'Tells barua ya kirafiki from other kinds of writing and its parts, and writes a friendly letter with the address, date, greeting, asking after the friend, the news, and a friendly closing; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.SARUFI.T4_NGELI_YA_A_WA.A_WA', 'KISW.G4.SARUFI.T4_NGELI_YA_A_WA', 'kiswahili', 4, 'Tumia ngeli ya A-WA kwa upatanisho wa kisarufi', ARRAY['KISW.G4.SARUFI.T4_NGELI_YA_A_WA.a', 'KISW.G4.SARUFI.T4_NGELI_YA_A_WA.b', 'KISW.G4.SARUFI.T4_NGELI_YA_A_WA.c']::text[], 'Knows that people and animals are in A-WA, gives a- for one and wa- for many (mtoto anacheza, watoto wanacheza), and makes the plural noun (mwalimu-walimu), in 8 of 10 new items.', '["choose the prefix","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.KUSIKI.T5_METHALI.METHALI', 'KISW.G4.KUSIKI.T5_METHALI', 'kiswahili', 4, 'Tambua na eleza maana ya methali za malezi', ARRAY['KISW.G4.KUSIKI.T5_METHALI.a', 'KISW.G4.KUSIKI.T5_METHALI.b', 'KISW.G4.KUSIKI.T5_METHALI.c']::text[], 'Tells a methali about upbringing from other sayings, gives what it means, and completes it, without taking it word for word or giving the meaning of another methali, in 8 of 10 new items. Using it aloud is a teacher''s check.', '["choose the methali","choose the meaning","fill the gap"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.SHAIRI', 'KISW.G4.KUSOMA.T5_KUSOMA_KWA_UFAHAMU', 'kiswahili', 4, 'Tambua shairi, ubeti na mshororo', ARRAY['KISW.G4.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.a', 'KISW.G4.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.c', 'KISW.G4.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.d', 'KISW.G4.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.b']::text[], 'Says what a shairi, an ubeti and a mshororo are, counts the beti and the mishororo in a short poem, and tells a poem from a paragraph by its shape, in 8 of 10 new items.', '["choose the word","fill the gap","count in a poem"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.KUANDI.T5_INSHA_YA_MAELEZO.INSHA_MAELEZO', 'KISW.G4.KUANDI.T5_INSHA_YA_MAELEZO', 'kiswahili', 4, 'Tambua na andika insha ya maelezo', ARRAY['KISW.G4.KUANDI.T5_INSHA_YA_MAELEZO.a', 'KISW.G4.KUANDI.T5_INSHA_YA_MAELEZO.b']::text[], 'Tells insha ya maelezo from other kinds of writing and its parts, and writes an explanation or description on the topic, in order, with detail that makes a picture and no point off the topic; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.SARUFI.T5_NGELI_YA_U_I.U_I', 'KISW.G4.SARUFI.T5_NGELI_YA_U_I', 'kiswahili', 4, 'Tumia ngeli ya U-I kwa upatanisho wa kisarufi', ARRAY['KISW.G4.SARUFI.T5_NGELI_YA_U_I.a', 'KISW.G4.SARUFI.T5_NGELI_YA_U_I.b', 'KISW.G4.SARUFI.T5_NGELI_YA_U_I.c']::text[], 'Knows nouns that belong to U-I (mti, mlango, mkono, mkoba, mguu), gives u- for one and i- for many, and makes the plural noun (mti-miti), without using the prefix of people, in 8 of 10 new items.', '["choose the prefix","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.KUSIKI.T6_SHAIRI.SHAIRI_MSAMIATI', 'KISW.G4.KUSIKI.T6_SHAIRI', 'kiswahili', 4, 'Elewa msamiati wa shairi la taifa', ARRAY['KISW.G4.KUSIKI.T6_SHAIRI.b', 'KISW.G4.KUSIKI.T6_SHAIRI.c', 'KISW.G4.KUSIKI.T6_SHAIRI.a', 'KISW.G4.KUSIKI.T6_SHAIRI.d']::text[], 'Gives the meaning of the words of a poem about the nation (bendera, taifa, uhuru, shujaa, mshikamano, amani) and uses them in a sentence, without choosing a look-alike or an opposite word, in 8 of 10 new items. Reciting is a teacher''s check.', '["choose the meaning","fill the gap","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.KUSOMA.T6_KUSOMA_KWA_KINA.MAKALA', 'KISW.G4.KUSOMA.T6_KUSOMA_KWA_KINA', 'kiswahili', 4, 'Elewa ujumbe wa makala', ARRAY['KISW.G4.KUSOMA.T6_KUSOMA_KWA_KINA.a', 'KISW.G4.KUSOMA.T6_KUSOMA_KWA_KINA.b']::text[], 'Answers questions about a short article (makala) from what it says, and gives its main message, without choosing a detail for the message or an answer from outside the article, in 8 of 10 new questions.', '["choose from an article","type a short answer","choose the message"]'::jsonb, '["recall","inference"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.KUANDI.T6_INSHA_YA_WASIFU.INSHA_WASIFU', 'KISW.G4.KUANDI.T6_INSHA_YA_WASIFU', 'kiswahili', 4, 'Tambua na andika insha ya wasifu', ARRAY['KISW.G4.KUANDI.T6_INSHA_YA_WASIFU.a', 'KISW.G4.KUANDI.T6_INSHA_YA_WASIFU.b']::text[], 'Tells insha ya wasifu from other kinds of writing and its parts, and writes a description of a person, place or thing with describing words that agree with their nouns and no story of events; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.SARUFI.T6_NGELI_YA_LI_YA.LI_YA', 'KISW.G4.SARUFI.T6_NGELI_YA_LI_YA', 'kiswahili', 4, 'Tumia ngeli ya LI-YA kwa upatanisho wa kisarufi', ARRAY['KISW.G4.SARUFI.T6_NGELI_YA_LI_YA.a', 'KISW.G4.SARUFI.T6_NGELI_YA_LI_YA.b', 'KISW.G4.SARUFI.T6_NGELI_YA_LI_YA.c']::text[], 'Knows nouns that belong to LI-YA (jiwe, jicho, tunda, embe, dirisha, jina), gives li- for one and ya- for many, and makes the plural noun with ma- (jiwe-mawe, tunda-matunda), in 8 of 10 new items.', '["choose the prefix","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.KUSIKI.T7_NAHAU.NAHAU', 'KISW.G4.KUSIKI.T7_NAHAU', 'kiswahili', 4, 'Tambua na eleza maana ya nahau za maadili na uraia', ARRAY['KISW.G4.KUSIKI.T7_NAHAU.a', 'KISW.G4.KUSIKI.T7_NAHAU.b', 'KISW.G4.KUSIKI.T7_NAHAU.c']::text[], 'Tells a nahau from other sayings and gives what it means (kupiga moyo konde, kujikaza kisabuni, kula kiapo, kukata tamaa), without taking it word for word, in 8 of 10 new items. Using it aloud is a teacher''s check.', '["choose the nahau","choose the meaning","fill the gap"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.KUSOMA.T7_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'KISW.G4.KUSOMA.T7_KUSOMA_KWA_MAPANA', 'kiswahili', 4, 'Chagua matini ya kusoma na ueleze ujumbe wake', ARRAY['KISW.G4.KUSOMA.T7_KUSOMA_KWA_MAPANA.a', 'KISW.G4.KUSOMA.T7_KUSOMA_KWA_MAPANA.b']::text[], 'Chooses a text that suits his reading level and interest from its title, blurb and first page (not from the cover alone), tells the kind of text (hadithi, shairi, makala, gazeti), says its message in one sentence, and works out a new word from the sentence around it, in 8 of 10 new items.', '["chagua matini ifaayo","chagua ujumbe","tambua aina ya matini","eleza maana ya neno"]'::jsonb, '["evaluation","inference"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.KUANDI.T7_INSHA_YA_MAELEZO.INSHA_MAELEZO', 'KISW.G4.KUANDI.T7_INSHA_YA_MAELEZO', 'kiswahili', 4, 'Tambua na andika insha ya maelezo', ARRAY['KISW.G4.KUANDI.T7_INSHA_YA_MAELEZO.a', 'KISW.G4.KUANDI.T7_INSHA_YA_MAELEZO.b']::text[], 'Tells insha ya maelezo from other kinds of writing and its parts, and writes an explanation or description on the topic, in order, with detail that makes a picture and no point off the topic; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.SARUFI.T7_NGELI_YA_KI_VI.KI_VI', 'KISW.G4.SARUFI.T7_NGELI_YA_KI_VI', 'kiswahili', 4, 'Tumia ngeli ya KI-VI kwa upatanisho wa kisarufi', ARRAY['KISW.G4.SARUFI.T7_NGELI_YA_KI_VI.a', 'KISW.G4.SARUFI.T7_NGELI_YA_KI_VI.b', 'KISW.G4.SARUFI.T7_NGELI_YA_KI_VI.c']::text[], 'Knows nouns that belong to KI-VI (kitabu, kiti, kikombe, kisu, kiatu), gives ki- for one and vi- for many, and makes the plural noun (kitabu-vitabu, kiatu-viatu), in 8 of 10 new items.', '["choose the prefix","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.SARUFI.T7_NGELI_YA_LI_LI.LI_LI', 'KISW.G4.SARUFI.T7_NGELI_YA_LI_LI', 'kiswahili', 4, 'Tumia ngeli ya LI-LI kwa upatanisho wa kisarufi', ARRAY['KISW.G4.SARUFI.T7_NGELI_YA_LI_LI.a', 'KISW.G4.SARUFI.T7_NGELI_YA_LI_LI.b', 'KISW.G4.SARUFI.T7_NGELI_YA_LI_LI.c']::text[], 'Knows the nouns the design gives for LI-LI (jua, giza), whose noun has the same form for one and for many, and uses li- with them (jua limetoka, giza limeingia), without using the prefix of another class, in 8 of 10 new items.', '["choose the prefix","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.KUSIKI.T8_VISAWE.VISAWE', 'KISW.G4.KUSIKI.T8_VISAWE', 'kiswahili', 4, 'Tambua visawe', ARRAY['KISW.G4.KUSIKI.T8_VISAWE.a', 'KISW.G4.KUSIKI.T8_VISAWE.b', 'KISW.G4.KUSIKI.T8_VISAWE.c']::text[], 'Picks the word with the same meaning (haraka-upesi, shida-taabu, furaha-raha) and does not choose a look-alike, an opposite or a related word, in 8 of 10 new items. Using visawe aloud is a teacher''s check.', '["choose the synonym","fill the gap","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.KUSOMA.T8_KUSOMA_KWA_UFAHAMU.IGIZO', 'KISW.G4.KUSOMA.T8_KUSOMA_KWA_UFAHAMU', 'kiswahili', 4, 'Tambua mchezo wa kuigiza, mhusika na maelekezo', ARRAY['KISW.G4.KUSOMA.T8_KUSOMA_KWA_UFAHAMU.a', 'KISW.G4.KUSOMA.T8_KUSOMA_KWA_UFAHAMU.b', 'KISW.G4.KUSOMA.T8_KUSOMA_KWA_UFAHAMU.c', 'KISW.G4.KUSOMA.T8_KUSOMA_KWA_UFAHAMU.d']::text[], 'Tells a short play (igizo) from a story by its shape (the name of the speaker, a colon, the words said), names the speaker of a line, and finds the stage direction in brackets, in 8 of 10 new items.', '["choose the form","choose from the play","type a short answer"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.KUANDI.T8_INSHA_YA_MASIMULIZI.INSHA_MASIMULIZI', 'KISW.G4.KUANDI.T8_INSHA_YA_MASIMULIZI', 'kiswahili', 4, 'Tambua na andika insha ya masimulizi', ARRAY['KISW.G4.KUANDI.T8_INSHA_YA_MASIMULIZI.a', 'KISW.G4.KUANDI.T8_INSHA_YA_MASIMULIZI.b']::text[], 'Tells insha ya masimulizi from other kinds of writing and its parts, and writes a story of events in the past tense, in order, with a title, an opening, a middle and a closing that gives the lesson; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.SARUFI.T8_MNYAMBULIKO_WA_VITEN.MNYAMBULIKO', 'KISW.G4.SARUFI.T8_MNYAMBULIKO_WA_VITEN', 'kiswahili', 4, 'Tambua na tumia kauli za kutenda, kutendea na kutendwa', ARRAY['KISW.G4.SARUFI.T8_MNYAMBULIKO_WA_VITEN.a', 'KISW.G4.SARUFI.T8_MNYAMBULIKO_WA_VITEN.b', 'KISW.G4.SARUFI.T8_MNYAMBULIKO_WA_VITEN.c', 'KISW.G4.SARUFI.T8_MNYAMBULIKO_WA_VITEN.d']::text[], 'Tells the three verb forms apart (kutenda: andika, kutendea: andikia, done for someone, kutendwa: andikwa, done to the thing) and picks the one a sentence needs, in 8 of 10 new items.', '["choose the verb form","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.KUSIKI.T9_MAZUNGUMZO_YA_KIMUKT.MAZUNGUMZO', 'KISW.G4.KUSIKI.T9_MAZUNGUMZO_YA_KIMUKT', 'kiswahili', 4, 'Tambua miktadha isiyo rasmi na lugha yake', ARRAY['KISW.G4.KUSIKI.T9_MAZUNGUMZO_YA_KIMUKT.a', 'KISW.G4.KUSIKI.T9_MAZUNGUMZO_YA_KIMUKT.b']::text[], 'Tells an informal setting (with a friend, at play, at home) from a formal one (a speech, an interview, a meeting) and picks the words that fit it, in 8 of 10 new items. Using them aloud is a teacher''s check.', '["choose the setting","choose the words","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.KUSOMA.T9_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'KISW.G4.KUSOMA.T9_KUSOMA_KWA_MAPANA', 'kiswahili', 4, 'Chagua matini ya kusoma na ueleze ujumbe wake', ARRAY['KISW.G4.KUSOMA.T9_KUSOMA_KWA_MAPANA.a', 'KISW.G4.KUSOMA.T9_KUSOMA_KWA_MAPANA.b']::text[], 'Chooses a text that suits his reading level and interest from its title, blurb and first page (not from the cover alone), tells the kind of text (hadithi, shairi, makala, gazeti), says its message in one sentence, and works out a new word from the sentence around it, in 8 of 10 new items.', '["chagua matini ifaayo","chagua ujumbe","tambua aina ya matini","eleza maana ya neno"]'::jsonb, '["evaluation","inference"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.KUANDI.T9_INSHA_YA_MAELEZO.INSHA_MAELEZO', 'KISW.G4.KUANDI.T9_INSHA_YA_MAELEZO', 'kiswahili', 4, 'Tambua na andika insha ya maelezo', ARRAY['KISW.G4.KUANDI.T9_INSHA_YA_MAELEZO.a', 'KISW.G4.KUANDI.T9_INSHA_YA_MAELEZO.b']::text[], 'Tells insha ya maelezo from other kinds of writing and its parts, and writes an explanation or description on the topic, in order, with detail that makes a picture and no point off the topic; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.SARUFI.T9_VINYUME_VYA_NOMINO.VINYUME_NOMINO', 'KISW.G4.SARUFI.T9_VINYUME_VYA_NOMINO', 'kiswahili', 4, 'Tambua na tumia vinyume vya nomino', ARRAY['KISW.G4.SARUFI.T9_VINYUME_VYA_NOMINO.a', 'KISW.G4.SARUFI.T9_VINYUME_VYA_NOMINO.b', 'KISW.G4.SARUFI.T9_VINYUME_VYA_NOMINO.c']::text[], 'Gives the true opposite of a noun (usiku-mchana, rafiki-adui, furaha-huzuni, tajiri-maskini) and does not choose a related word or a word of the same meaning, in 8 of 10 new items.', '["choose the opposite","fill the gap","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.KUSIKI.T10_TASHBIHI.TASHBIHI', 'KISW.G4.KUSIKI.T10_TASHBIHI', 'kiswahili', 4, 'Tambua na tumia tashbihi za kimo na umbo', ARRAY['KISW.G4.KUSIKI.T10_TASHBIHI.a', 'KISW.G4.KUSIKI.T10_TASHBIHI.b', 'KISW.G4.KUSIKI.T10_TASHBIHI.c']::text[], 'Gives the usual comparison for height, size and shape (mrefu kama twiga, mnene kama kiboko, mkubwa kama ndovu) and says it is a simile because of kama, without taking it word for word, in 8 of 10 new items. Using it aloud is a teacher''s check.', '["choose the simile","fill the gap","choose the meaning"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.KUSOMA.T10_KUSOMA_KIDIJITALI.KUSOMA_KIDIJITALI', 'KISW.G4.KUSOMA.T10_KUSOMA_KIDIJITALI', 'kiswahili', 4, 'Fungua faili, sakura kwenye tovuti salama na usome matini ya kidijitali', ARRAY['KISW.G4.KUSOMA.T10_KUSOMA_KIDIJITALI.b', 'KISW.G4.KUSOMA.T10_KUSOMA_KIDIJITALI.c', 'KISW.G4.KUSOMA.T10_KUSOMA_KIDIJITALI.d']::text[], 'Opens a saved file with the passage (finds the folder, double-clicks the file), searches a safe site with two or three key words, ignores pop-ups and adverts, and reads the passage for its message, in 8 of 10 new items or tasks.', '["chagua hatua sahihi","panga hatua","chagua maneno ya kutafutia","tambua kosa"]'::jsonb, '["procedure","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.KUANDI.T10_INSHA_YA_MASIMULIZI.INSHA_MASIMULIZI', 'KISW.G4.KUANDI.T10_INSHA_YA_MASIMULIZI', 'kiswahili', 4, 'Tambua na andika insha ya masimulizi', ARRAY['KISW.G4.KUANDI.T10_INSHA_YA_MASIMULIZI.a', 'KISW.G4.KUANDI.T10_INSHA_YA_MASIMULIZI.b']::text[], 'Tells insha ya masimulizi from other kinds of writing and its parts, and writes a story of events in the past tense, in order, with a title, an opening, a middle and a closing that gives the lesson; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.SARUFI.T10_NYAKATI_NA_HALI.NYAKATI', 'KISW.G4.SARUFI.T10_NYAKATI_NA_HALI', 'kiswahili', 4, 'Tambua na tumia nyakati: -li-, -na- na -ta-', ARRAY['KISW.G4.SARUFI.T10_NYAKATI_NA_HALI.a', 'KISW.G4.SARUFI.T10_NYAKATI_NA_HALI.b', 'KISW.G4.SARUFI.T10_NYAKATI_NA_HALI.c']::text[], 'Uses -li- for what happened before (jana alisoma), -na- for now (anasoma) and -ta- for what will happen (atasoma), following the time word, and gives the right person prefix, in 8 of 10 new items.', '["choose the verb","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.KUSIKI.T11_MASIMULIZI.MASIMULIZI', 'KISW.G4.KUSIKI.T11_MASIMULIZI', 'kiswahili', 4, 'Sikiliza masimulizi kwa ujumbe na usimulie kwa ishara zifaazo', ARRAY['KISW.G4.KUSIKI.T11_MASIMULIZI.a', 'KISW.G4.KUSIKI.T11_MASIMULIZI.b', 'KISW.G4.KUSIKI.T11_MASIMULIZI.c']::text[], 'Listens to a short narration and gives its message (not a detail), retells it in order, and tells his own story on the topic in Kiswahili sanifu with gestures that match the words; the teacher scores the telling with the KICD rubric, and in the app the child picks the message, order or gesture in 8 of 10 new items.', '["chagua ujumbe","panga matukio uliyosikia","chagua ishara ifaayo","kusimulia (mwalimu anasikiliza)"]'::jsonb, '["listening","application"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.KUSOMA.T11_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'KISW.G4.KUSOMA.T11_KUSOMA_KWA_UFASAHA', 'kiswahili', 4, 'Soma kifungu kwa sauti kwa matamshi bora, kasi ifaayo, sauti ifaayo na ishara', ARRAY['KISW.G4.KUSOMA.T11_KUSOMA_KWA_UFASAHA.b', 'KISW.G4.KUSOMA.T11_KUSOMA_KWA_UFASAHA.c', 'KISW.G4.KUSOMA.T11_KUSOMA_KWA_UFASAHA.d', 'KISW.G4.KUSOMA.T11_KUSOMA_KWA_UFASAHA.e']::text[], 'Reads a short passage aloud at a speaking pace, pauses at the koma and the kikomo, raises the voice for a question and shows feeling for an exclamation, says every sound clearly (no l for r), and uses a matching gesture, judged by the teacher with the KICD rubric; in the app picks the better reading of a line in 8 of 10 new items.', '["chagua usomaji bora","tambua kosa la usomaji","kusoma kwa sauti (mwalimu anasikiliza)"]'::jsonb, '["application","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.KUANDI.T11_BARUA_YA_KIRAFIKI.KUANDIKA_BARUA', 'KISW.G4.KUANDI.T11_BARUA_YA_KIRAFIKI', 'kiswahili', 4, 'Andika barua ya kirafiki kwa muundo na lugha ifaayo', ARRAY['KISW.G4.KUANDI.T11_BARUA_YA_KIRAFIKI.b']::text[], 'Tells barua ya kirafiki from other kinds of writing and its parts, and writes a friendly letter with the address, date, greeting, asking after the friend, the news, and a friendly closing; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.SARUFI.T11_UKANUSHAJI.UKANUSHAJI', 'KISW.G4.SARUFI.T11_UKANUSHAJI', 'kiswahili', 4, 'Kanusha sentensi kwa nafsi na wakati', ARRAY['KISW.G4.SARUFI.T11_UKANUSHAJI.a', 'KISW.G4.SARUFI.T11_UKANUSHAJI.b', 'KISW.G4.SARUFI.T11_UKANUSHAJI.c', 'KISW.G4.SARUFI.T11_UKANUSHAJI.d']::text[], 'Makes the negative of a verb in the past (hakusoma), present (hasomi) and future (hatasoma) for the person, and tells a negative from a positive verb, without only adding ha- or keeping the tense marker, in 8 of 10 new items.', '["choose the negative","fill the gap","spot the mistake"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.SARUFI.T11_UKUBWA_WA_NOMINO.UKUBWA', 'KISW.G4.SARUFI.T11_UKUBWA_WA_NOMINO', 'kiswahili', 4, 'Badilisha nomino za m- kuwa katika hali ya ukubwa', ARRAY['KISW.G4.SARUFI.T11_UKUBWA_WA_NOMINO.a', 'KISW.G4.SARUFI.T11_UKUBWA_WA_NOMINO.b', 'KISW.G4.SARUFI.T11_UKUBWA_WA_NOMINO.c', 'KISW.G4.SARUFI.T11_UKUBWA_WA_NOMINO.d', 'KISW.G4.SARUFI.T11_UKUBWA_WA_NOMINO.e']::text[], 'Gives the big form (ji-) of the m- nouns with a one-syllable root (mti-jiti, mto-jito, mji-jiji, mtu-jitu) for one and for many (majiti), and does not keep the noun, use ki-, or give one for many, in 8 of 10 new items.', '["choose the form","fill the gap","spot the mistake"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G4.SARUFI.T11_UDOGO_WA_NOMINO.UDOGO', 'KISW.G4.SARUFI.T11_UDOGO_WA_NOMINO', 'kiswahili', 4, 'Badilisha nomino za m- kuwa katika hali ya udogo', ARRAY['KISW.G4.SARUFI.T11_UDOGO_WA_NOMINO.a', 'KISW.G4.SARUFI.T11_UDOGO_WA_NOMINO.b', 'KISW.G4.SARUFI.T11_UDOGO_WA_NOMINO.c', 'KISW.G4.SARUFI.T11_UDOGO_WA_NOMINO.d', 'KISW.G4.SARUFI.T11_UDOGO_WA_NOMINO.e']::text[], 'Gives the small form (ki-) of the m- nouns with a one-syllable root (mti-kijiti, mto-kijito, mji-kijiji, mtu-kijitu) for one and for many (vijiti), and does not keep the noun, use ji-, or give one for many, in 8 of 10 new items.', '["choose the form","fill the gap","spot the mistake"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('KISW.G4.KUSIKI.T1_MATAMSHI_BORA.MATAMSHI', 'KISW.G3.KUSIKI.T4_MATAMSHI_BORA.MATAMSHI', 'skill', 'essential', 'Hearing the syllables of a target sound in Grade 3 is the base for telling two close sounds apart.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('KISW.G4.KUSIKI.T1_MATAMSHI_BORA.MATAMSHI', 'KISW.G3.KUSIKI.T2_MATAMSHI_BORA_VOKALI.VOKALI_KONSONANTI', 'skill', 'essential', 'Every Kiswahili syllable ends in one of the five vowels; the child must know them to split words.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('KISW.G4.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.MSAMIATI', 'KISW.G3.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.a', 'outcome', 'essential', 'Proposed: this skill builds on it. To confirm by a native Kiswahili teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('KISW.G4.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.MSAMIATI', 'KISW.G4.SARUFI.T1_NOMINO.NOMINO', 'skill', 'helpful', 'Most theme vocabulary is nouns of the home.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('KISW.G4.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.UFAHAMU_HADITHI', 'KISW.G4.SARUFI.T1_NOMINO.NOMINO', 'skill', 'essential', 'Proposed: this skill builds on it. To confirm by a native Kiswahili teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('KISW.G4.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.UFAHAMU_HADITHI', 'KISW.G3.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.b', 'outcome', 'essential', 'Proposed: this skill builds on it. To confirm by a native Kiswahili teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('KISW.G4.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.UFAHAMU_HADITHI', 'KISW.G3.KUSOMA.T3_KUSOMA_KWA_UFAHAMU.b', 'outcome', 'essential', 'Proposed: this skill builds on it. To confirm by a native Kiswahili teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
