INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSIKI.T1_MATAMSHI_BORA.MATAMSHI.M4_MAT_SWAP_T1', 'KISW.G4.KUSIKI.T1_MATAMSHI_BORA.MATAMSHI', 'Hears or says /d/ for /t/, so tamu (sweet) becomes damu (blood).', '{"question":"Mwalimu anasema: \"tamu\". Umesikia neno lipi?","wrong_answer":"damu","correct_answer":"tamu"}'::jsonb, 'p/b, t/d, k/g and ch/j are made at the same place in the mouth and differ only in voice; Kalenjin languages, for example, do not separate them, so the child hears one sound and writes either letter.', 'The question "Mwalimu anasema: "tamu". Umesikia neno lipi?" with "damu" among the options.', 'Say the pair slowly with a hand on the throat (or watching the lips); the child says which word was heard before writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSIKI.T1_MATAMSHI_BORA.MATAMSHI.M4_MAT_SPELL_T1', 'KISW.G4.KUSIKI.T1_MATAMSHI_BORA.MATAMSHI', 'Writes the word with the letter of the other sound (goti where koti is meant).', '{"question":"Jaza pengo: ___ maana yake ni \"a coat\".","wrong_answer":"goti","correct_answer":"koti"}'::jsonb, 'The child spells as he speaks; if the two sounds are one sound in his speech, the letter is a guess.', 'The question "Jaza pengo: ___ maana yake ni "a coat"." with "goti" among the options.', 'Pair each spelling with its meaning on a card; the child sorts the cards by meaning, then by letter.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSIKI.T1_MATAMSHI_BORA.MATAMSHI.M4_MAT_SAME_T1', 'KISW.G4.KUSIKI.T1_MATAMSHI_BORA.MATAMSHI', 'Thinks the two words are one word said in two ways, with one meaning.', '{"question":"\"koti\" na \"goti\" ni maneno yenye maana moja?","wrong_answer":"ndiyo","correct_answer":"hapana"}'::jsonb, 'The child has heard both said by different people for the same thing and takes the difference for an accent.', 'The question ""koti" na "goti" ni maneno yenye maana moja?" with "ndiyo" among the options.', 'Use both words in two sentences that cannot swap: the child says which sentence breaks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSIKI.T1_MATAMSHI_BORA.MATAMSHI.M4_MAT_TWISTER_T1', 'KISW.G4.KUSIKI.T1_MATAMSHI_BORA.MATAMSHI', 'Takes any long sentence for a kitanzandimi, though it does not repeat the target sounds.', '{"question":"Ni kipi ni kitanzandimi?","wrong_answer":"Mama amerudi nyumbani jioni.","correct_answer":"Baba na bibi wanapika pilau na pombe ya bibi bila pilipili."}'::jsonb, 'The child thinks a kitanzandimi is any sentence that is hard to say, not one built by repeating close sounds.', 'The question "Ni kipi ni kitanzandimi?" with "Mama amerudi nyumbani jioni." among the options.', 'Underline the target sounds in the real kitanzandimi; count them; the ordinary sentence has few or none.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSIKI.T1_MATAMSHI_BORA.MATAMSHI.M4_MAT_SYLL_T1', 'KISW.G4.KUSIKI.T1_MATAMSHI_BORA.MATAMSHI', 'Breaks the word into syllables at the wrong place, so the target sound is lost (ta-mu read as two wrong parts).', '{"question":"Neno \"tamu\" lina silabi zipi?","wrong_answer":"t-amu","correct_answer":"ta-mu"}'::jsonb, 'In Kiswahili every syllable ends in a vowel, and a nasal with its consonant (nd, mb, nj, ng) starts one syllable; the child splits by letters, not by sound.', 'The question "Neno "tamu" lina silabi zipi?" with "t-amu" among the options.', 'Clap the word: one clap per vowel; the nasal goes with the consonant after it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.MSAMIATI.M4_MSA_LOOKALIKE', 'KISW.G4.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.MSAMIATI', 'Picks a word that looks or sounds like the word.', '{"question":"Katika kifungu, neno \"mche\" lina maana gani?","wrong_answer":"mchele","correct_answer":"mmea mchanga wa kupanda"}'::jsonb, 'The child goes by the first letters.', 'A look-alike word as an option.', 'Say what each word means.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.MSAMIATI.M4_MSA_NEARBY', 'KISW.G4.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.MSAMIATI', 'Picks a word from the same sentence, not the word asked.', '{"question":"Katika kifungu, neno \"kuchemsha\" lina maana gani?","wrong_answer":"kumimina uji vikombeni","correct_answer":"kupasha maji moto hadi yatokote"}'::jsonb, 'The child picks the meaning of a nearby action.', 'The meaning of the word next to it as an option.', 'Put each meaning in place of the word. Which one fits?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.MSAMIATI.M4_MSA_OPPOSITE', 'KISW.G4.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.MSAMIATI', 'Picks the opposite of the word.', '{"question":"Katika kifungu, neno \"madonge\" lina maana gani?","wrong_answer":"unga laini","correct_answer":"vipande vya unga vilivyoshikana"}'::jsonb, 'The child knows what the word is about but not which way it points.', 'The opposite meaning as an option.', 'Read the sentence again: does it say the thing is there or not?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.UFAHAMU_HADITHI.M4_UFA_WRONG_PERSON', 'KISW.G4.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.UFAHAMU_HADITHI', 'Names the wrong person from the story.', '{"question":"Nani alimwita Achieng sokoni?","wrong_answer":"mama yake","correct_answer":"mjomba wake"}'::jsonb, 'The child goes by the name that comes first in the passage.', 'A question about who, with other people in the story.', 'Find the sentence that names the person who did it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.UFAHAMU_HADITHI.M4_UFA_OUTSIDE', 'KISW.G4.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.UFAHAMU_HADITHI', 'Gives an answer from what the child knows, not from the passage.', '{"question":"Achieng alinunua nini sokoni?","wrong_answer":"maziwa","correct_answer":"nyanya"}'::jsonb, 'The child answers from life and does not look in the text.', 'A likely answer that the story does not give.', 'Point to the sentence in the passage that says it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.UFAHAMU_HADITHI.M4_UFA_DETAIL_MIX', 'KISW.G4.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.UFAHAMU_HADITHI', 'Picks another detail from the story.', '{"question":"Mvua ilinyesha lini?","wrong_answer":"asubuhi","correct_answer":"jioni"}'::jsonb, 'The child picks a detail from the right place but not the one asked.', 'Several details from one sentence.', 'Read the question word again: who, when, where, what?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.UFAHAMU_HADITHI.M4_UFA_DETAIL_AS_MAIN', 'KISW.G4.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.UFAHAMU_HADITHI', 'Gives a detail for the main message.', '{"question":"Ujumbe mkuu wa hadithi ni upi?","wrong_answer":"Achieng alinunua nyanya.","correct_answer":"Tunapaswa kusaidia wengine."}'::jsonb, 'The child takes the most vivid detail.', 'A detail and a message as options.', 'What did the story want us to learn?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.UFAHAMU_HADITHI.M4_UFA_ORDER', 'KISW.G4.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.UFAHAMU_HADITHI', 'Puts the events in the wrong order.', '{"question":"Matukio manne yamechanganywa. Yalitokea kwa mpangilio gani?","wrong_answer":"D, C, B, A","correct_answer":"A, B, C, D"}'::jsonb, 'The child goes by the order in the question and not in the story.', 'Four events shown out of order.', 'Find the first event, then the next.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.MSAMIATI.M4_MSA_ENGLISH', 'KISW.G4.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.MSAMIATI', 'Gives the English word as the meaning, or a word from the mother tongue, instead of a Kiswahili explanation.', '{"question":"Katika kifungu, \"sebule\" maana yake ni nini?","wrong_answer":"sitting room","correct_answer":"chumba cha kukaa na kupokea wageni"}'::jsonb, 'The child translates in his head and writes what he thought.', 'The question "Katika kifungu, "sebule" maana yake ni nini?" with "sitting room" among the options.', 'Ask for the meaning in Kiswahili words; use a picture of the room to talk about it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T1_INSHA_YA_WASIFU.AINA_ZA_INSHA.M4_INS_WASIFU_STORY', 'KISW.G4.KUANDI.T1_INSHA_YA_WASIFU.AINA_ZA_INSHA', 'Calls a text that describes a person or thing a masimulizi.', '{"question":"Ni insha ya aina gani? \"Bibi yangu ni mpole. Ana nywele nyeupe na anapenda kusimulia hadithi.\"","wrong_answer":"masimulizi","correct_answer":"wasifu"}'::jsonb, 'The child sees that it is about a person and thinks of a story.', 'A description of a person.', 'Does the text tell what happened in order, or what the person is like?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T1_INSHA_YA_WASIFU.AINA_ZA_INSHA.M4_INS_STORY_WASIFU', 'KISW.G4.KUANDI.T1_INSHA_YA_WASIFU.AINA_ZA_INSHA', 'Calls a text that tells what happened a wasifu.', '{"question":"Ni insha ya aina gani? \"Jumamosi, Achieng alienda sokoni. Mvua ilianza kunyesha, akakimbilia dukani.\"","wrong_answer":"wasifu","correct_answer":"masimulizi"}'::jsonb, 'The child sees a person and thinks it describes her.', 'A story about a person.', 'Is something happening, one thing after another?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T1_INSHA_YA_WASIFU.AINA_ZA_INSHA.M4_INS_MAELEZO_STORY', 'KISW.G4.KUANDI.T1_INSHA_YA_WASIFU.AINA_ZA_INSHA', 'Calls a text that explains how to do something a masimulizi.', '{"question":"Ni insha ya aina gani? \"Ili kupika wali, osha mchele kwanza. Kisha chemsha maji.\"","wrong_answer":"masimulizi","correct_answer":"maelezo"}'::jsonb, 'The child sees steps and reads them as events.', 'Instructions that sound like a story.', 'Is it telling what happened, or how to do it?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T1_INSHA_YA_WASIFU.AINA_ZA_INSHA.M4_INS_PART_ORDER', 'KISW.G4.KUANDI.T1_INSHA_YA_WASIFU.AINA_ZA_INSHA', 'Mixes the parts of an insha (utangulizi, kiini, hitimisho).', '{"question":"Sehemu ya mwisho ya insha huitwa ___.","wrong_answer":"utangulizi","correct_answer":"hitimisho"}'::jsonb, 'The child knows the three names but not their order.', 'The three parts asked in turn.', 'Which part comes first, which in the middle, which last?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T1_INSHA_YA_WASIFU.INSHA_WASIFU.M4_INS_STORY_T1', 'KISW.G4.KUANDI.T1_INSHA_YA_WASIFU.INSHA_WASIFU', 'Tells a story of what happened where the insha should describe the person, place or thing.', '{"question":"Ni sentensi ipi inafaa katika insha ya wasifu kuhusu \"Nyumbani Kwetu\"?","wrong_answer":"Siku moja tulienda sokoni tukapotea.","correct_answer":"Nyumba yetu ina paa jekundu na madirisha manne makubwa."}'::jsonb, 'Stories are the kind of writing the child has done most and he falls back on it.', 'The question "Ni sentensi ipi inafaa katika insha ya wasifu kuhusu "Nyumbani Kwetu"?" with "Siku moja tulienda sokoni tukapotea." among the options.', 'Ask what the reader should know about the topic at the end: what it looks like, what it is for.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T1_INSHA_YA_WASIFU.INSHA_WASIFU.M4_INS_DETAIL_T1', 'KISW.G4.KUANDI.T1_INSHA_YA_WASIFU.INSHA_WASIFU', 'Describes with empty words (kizuri sana, kibaya) and no detail that makes a picture.', '{"question":"Ni sentensi ipi inajenga picha dhahiri kuhusu \"Nyumbani Kwetu\"?","wrong_answer":"Nyumba yetu ni nzuri sana.","correct_answer":"Nyumba yetu ina paa jekundu na madirisha manne makubwa."}'::jsonb, 'The child knows the thing well and assumes the reader sees it too.', 'The question "Ni sentensi ipi inajenga picha dhahiri kuhusu "Nyumbani Kwetu"?" with "Nyumba yetu ni nzuri sana." among the options.', 'Five senses chart: what do you see, hear, smell, touch, taste? Turn one row into a sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T1_INSHA_YA_WASIFU.INSHA_WASIFU.M4_INS_AGREE_T1', 'KISW.G4.KUANDI.T1_INSHA_YA_WASIFU.INSHA_WASIFU', 'Uses a describing word that does not agree with its noun (bendera mzuri, miti mrefu).', '{"question":"Ni sentensi ipi ni sahihi?","wrong_answer":"Nyumba yetu ina vyumba vitatu mikubwa.","correct_answer":"Nyumba yetu ina vyumba vitatu vikubwa."}'::jsonb, 'The child uses one form of the adjective (m-) for every noun, as he hears it for people.', 'The question "Ni sentensi ipi ni sahihi?" with "Nyumba yetu ina vyumba vitatu mikubwa." among the options.', 'Find the noun first, then its ngeli, then the prefix of the adjective.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T1_INSHA_YA_WASIFU.INSHA_WASIFU.M4_INS_OFFTOPIC_T1', 'KISW.G4.KUANDI.T1_INSHA_YA_WASIFU.INSHA_WASIFU', 'Puts in points that are not about the title.', '{"question":"Katika insha ya wasifu yenye anwani \"Nyumbani Kwetu\", ni sentensi ipi haifai?","wrong_answer":"Rafiki yangu ana baiskeli mpya ya rangi ya bluu.","correct_answer":"Nyumba yetu ina paa jekundu na madirisha manne makubwa."}'::jsonb, 'The child adds whatever he remembers so the insha is long enough.', 'The question "Katika insha ya wasifu yenye anwani "Nyumbani Kwetu", ni sentensi ipi haifai?" with "Rafiki yangu ana baiskeli mpya ya rangi ya bluu." among the options.', 'Read each sentence and ask: does it tell the reader about the title? Cross out the ones that do not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T1_NOMINO.NOMINO.M4_NOM_VERB', 'KISW.G4.SARUFI.T1_NOMINO.NOMINO', 'Picks a verb (a word for an action) for a noun.', '{"question":"Mama ananunua ___ sokoni.","wrong_answer":"anapika","correct_answer":"mboga"}'::jsonb, 'The child sees a word that goes with the sentence and does not ask what kind of word it is.', 'A gap that needs a thing, with a verb among the options.', 'Ask: is it the name of something, or something being done?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T1_NOMINO.NOMINO.M4_NOM_ADJ', 'KISW.G4.SARUFI.T1_NOMINO.NOMINO', 'Picks an adjective (a word that describes) for a noun.', '{"question":"Ni neno lipi ni nomino?","wrong_answer":"kubwa","correct_answer":"kitabu"}'::jsonb, 'The child picks the word that tells about the thing, not the thing.', 'A noun among describing words.', 'Can you hold it, see it or name it? Then it may be a noun.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T1_NOMINO.NOMINO.M4_NOM_ADV', 'KISW.G4.SARUFI.T1_NOMINO.NOMINO', 'Picks a word of time or manner (haraka, jana, sana) for a noun.', '{"question":"Ni neno lipi ni nomino?","wrong_answer":"haraka","correct_answer":"mwalimu"}'::jsonb, 'The child picks a short word that fits the sentence.', 'A noun among words of time and manner.', 'Does the word name something?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T1_NOMINO.NOMINO.M4_NOM_PRONOUN', 'KISW.G4.SARUFI.T1_NOMINO.NOMINO', 'Picks a pronoun (yeye, wao, huyu) as the noun in the sentence.', '{"question":"Ni nomino ipi katika sentensi: \"Yeye alimpa mtoto chakula\"?","wrong_answer":"Yeye","correct_answer":"mtoto"}'::jsonb, 'A pronoun stands where a noun stands, so the child takes it for one.', 'The question "Ni nomino ipi katika sentensi: "Yeye alimpa mtoto chakula"?" with "Yeye" among the options.', 'Ask: does the word name someone or something, or does it point to someone already named?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T1_VITENZI.VITENZI.M4_VERB_NOUN', 'KISW.G4.SARUFI.T1_VITENZI.VITENZI', 'Picks a noun for a verb.', '{"question":"Juma ___ mpira uwanjani.","wrong_answer":"uwanja","correct_answer":"anacheza"}'::jsonb, 'The child takes the word nearest the gap that names a thing.', 'A gap that needs an action, with a noun among the options.', 'Ask: what is Juma doing?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T1_VITENZI.VITENZI.M4_VERB_ADJ', 'KISW.G4.SARUFI.T1_VITENZI.VITENZI', 'Picks an adjective for a verb.', '{"question":"Mama ___ chakula jikoni.","wrong_answer":"kitamu","correct_answer":"anapika"}'::jsonb, 'The child picks a word that goes with chakula.', 'A gap that needs an action, with a describing word among the options.', 'Can you do the word? Cooking can be done; "kitamu" cannot.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T1_VITENZI.VITENZI.M4_VERB_OTHER', 'KISW.G4.SARUFI.T1_VITENZI.VITENZI', 'Picks a word of time or manner (sasa, mapema) for a verb.', '{"question":"Wakulima ___ mahindi shambani.","wrong_answer":"mapema","correct_answer":"wanapanda"}'::jsonb, 'The child picks a small word that seems to fit.', 'A gap that needs an action, with a time or manner word.', 'Ask: who does what?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T1_VITENZI.VITENZI.M4_VERB_KU_NOUN', 'KISW.G4.SARUFI.T1_VITENZI.VITENZI', 'Takes the verb-noun with ku- (kusoma ni kuzuri) and the verb in a sentence as different kinds, or calls a verb-noun the verb of the sentence.', '{"question":"Ni kitenzi kipi katika sentensi: \"Kuogelea kunafurahisha\"?","wrong_answer":"Kuogelea","correct_answer":"kunafurahisha"}'::jsonb, 'Every word with ku- looks like a verb to the child.', 'The question "Ni kitenzi kipi katika sentensi: "Kuogelea kunafurahisha"?" with "Kuogelea" among the options.', 'Ask what the sentence says is happening; the ku- word here is the thing being talked about.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T1_VIVUMISHI.VIVUMISHI.M4_ADJ_NOUN', 'KISW.G4.SARUFI.T1_VIVUMISHI.VIVUMISHI', 'Picks a noun for an adjective.', '{"question":"Mtoto ___ anacheza uwanjani.","wrong_answer":"mwalimu","correct_answer":"mdogo"}'::jsonb, 'The child picks a word for a person.', 'A gap that needs a describing word, with a noun among the options.', 'Ask: does the word tell what kind of child?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T1_VIVUMISHI.VIVUMISHI.M4_ADJ_VERB', 'KISW.G4.SARUFI.T1_VIVUMISHI.VIVUMISHI', 'Picks a verb for an adjective.', '{"question":"Nyumba ___ ina bustani.","wrong_answer":"inaonekana","correct_answer":"nzuri"}'::jsonb, 'The child fills the gap with any word that fits the meaning.', 'A gap that needs a describing word, with a verb among the options.', 'Does the word tell how the house is, or what it does?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T1_VIVUMISHI.VIVUMISHI.M4_ADJ_AGREE', 'KISW.G4.SARUFI.T1_VIVUMISHI.VIVUMISHI', 'Uses an adjective that does not agree with its noun (watoto mdogo, kiti mkubwa).', '{"question":"Watoto ___ wanacheza.","wrong_answer":"mdogo","correct_answer":"wadogo"}'::jsonb, 'The child keeps the form of the adjective for one thing.', 'Plural and singular nouns in turn, with the same adjective.', 'Count: one or many? The adjective changes with the noun.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T1_VIVUMISHI.VIVUMISHI.M4_ADJ_ENG_ORDER', 'KISW.G4.SARUFI.T1_VIVUMISHI.VIVUMISHI', 'Puts the describing word before the noun, as in English (mzuri mtoto, kubwa nyumba).', '{"question":"Ni ipi ni sahihi?","wrong_answer":"mzuri mtoto","correct_answer":"mtoto mzuri"}'::jsonb, 'In English the adjective comes first, and the child carries that order over.', 'The question "Ni ipi ni sahihi?" with "mzuri mtoto" among the options.', 'Say noun first, then the word that describes it; build phrases with two cards that must be in order.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSIKI.T2_MAAMKUZI_NA_MAAGANO.MAAMKUZI.M4_MAA_REPLY', 'KISW.G4.KUSIKI.T2_MAAMKUZI_NA_MAAGANO.MAAMKUZI', 'Gives the greeting back as the reply (Hujambo for Sijambo).', '{"question":"Mtu akikusalimia \"Hujambo?\", unajibu \"___.\"","wrong_answer":"Hujambo","correct_answer":"Sijambo"}'::jsonb, 'The child repeats the word he heard.', 'A greeting and its reply as options.', 'Who is asking, and who answers?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSIKI.T2_MAAMKUZI_NA_MAAGANO.MAAMKUZI.M4_MAA_TIME', 'KISW.G4.KUSIKI.T2_MAAMKUZI_NA_MAAGANO.MAAMKUZI', 'Uses a greeting of the wrong time of day (habari za asubuhi at night).', '{"question":"Kabla ya kulala usiku unamwambia mama, \"___.\"","wrong_answer":"Habari za asubuhi","correct_answer":"Usiku mwema"}'::jsonb, 'The child knows the greeting but not when it is used.', 'A morning greeting for an evening situation.', 'What time of day is it?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSIKI.T2_MAAMKUZI_NA_MAAGANO.MAAMKUZI.M4_MAA_ELDER', 'KISW.G4.KUSIKI.T2_MAAMKUZI_NA_MAAGANO.MAAMKUZI', 'Greets an elder with the greeting for a friend (hujambo for shikamoo).', '{"question":"Unamsalimia babu yako kwa kusema \"___.\"","wrong_answer":"Hujambo","correct_answer":"Shikamoo"}'::jsonb, 'The child uses one greeting for everyone.', 'An elder and a friend as the people greeted.', 'Is the person older than you?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSIKI.T2_MAAMKUZI_NA_MAAGANO.MAAMKUZI.M4_MAA_FAREWELL', 'KISW.G4.KUSIKI.T2_MAAMKUZI_NA_MAAGANO.MAAMKUZI', 'Uses a greeting where a farewell is needed (Hujambo! when leaving), or the reverse.', '{"question":"Unaondoka nyumbani kwa shangazi jioni. Unasema nini?","wrong_answer":"Hujambo shangazi!","correct_answer":"Kwaheri shangazi, usiku mwema!"}'::jsonb, 'Greeting and farewell words are learnt together on one chart and the child mixes the columns.', 'The question "Unaondoka nyumbani kwa shangazi jioni. Unasema nini?" with "Hujambo shangazi!" among the options.', 'Act out arriving and leaving at a door; the child says the right word at each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T2_KUSOMA_KWA_KINA.KAMUSI.M4_KAM_FIRST_ONLY', 'KISW.G4.KUSOMA.T2_KUSOMA_KWA_KINA.KAMUSI', 'Looks at the first letter only (words that begin alike).', '{"question":"Kati ya \"samaki\", \"sahani\" na \"sufuria\", neno linalokuja kwanza ni ___.","wrong_answer":"samaki","correct_answer":"sahani"}'::jsonb, 'The child stops when the first letters are the same.', 'Words that begin with the same letter.', 'When the first letters match, look at the second.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T2_KUSOMA_KWA_KINA.KAMUSI.M4_KAM_LENGTH', 'KISW.G4.KUSOMA.T2_KUSOMA_KWA_KINA.KAMUSI', 'Puts the shortest word first.', '{"question":"Kati ya \"ua\", \"ardhi\" na \"wali\", neno linalokuja kwanza ni ___.","wrong_answer":"ua","correct_answer":"ardhi"}'::jsonb, 'The child orders by how short or long the word is.', 'A short word that begins with a late letter.', 'Go by the letters of the alphabet, not by how long the word is.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T2_KUSOMA_KWA_KINA.KAMUSI.M4_KAM_REVERSE', 'KISW.G4.KUSOMA.T2_KUSOMA_KWA_KINA.KAMUSI', 'Goes from z back to a.', '{"question":"Kati ya \"baba\", \"mto\" na \"zeze\", neno linalokuja kwanza ni ___.","wrong_answer":"zeze","correct_answer":"baba"}'::jsonb, 'The child reads the alphabet from the end.', 'First and last words asked in turn.', 'The alphabet begins with a.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T2_KUSOMA_KWA_KINA.KAMUSI.M4_KAM_PURPOSE', 'KISW.G4.KUSOMA.T2_KUSOMA_KWA_KINA.KAMUSI', 'Does not know what a dictionary is for (takes it for a storybook or a book of pictures).', '{"question":"Kamusi hutusaidia kupata ___ ya neno.","wrong_answer":"picha","correct_answer":"maana"}'::jsonb, 'The child has seen a dictionary but not used it.', 'The use of a dictionary asked directly.', 'What do you look for when you meet a word you do not know?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T2_INSHA_YA_MASIMULIZI.INSHA_MASIMULIZI.M4_INS_FACTS_T2', 'KISW.G4.KUANDI.T2_INSHA_YA_MASIMULIZI.INSHA_MASIMULIZI', 'Writes facts or an explanation where a story of events is asked.', '{"question":"Ni sentensi ipi ni mwanzo wa insha ya masimulizi yenye anwani \"Siku Nilipokula na Wageni\"?","wrong_answer":"Watu wengi hula mara tatu kwa siku.","correct_answer":"Jana jioni tulikula chakula pamoja na wageni wetu."}'::jsonb, 'The child knows a lot about the topic and writes what he knows instead of telling what happened.', 'The question "Ni sentensi ipi ni mwanzo wa insha ya masimulizi yenye anwani "Siku Nilipokula na Wageni"?" with "Watu wengi hula mara tatu kwa siku." among the options.', 'Ask: who, where, what happened first, then, in the end? A story answers these; an explanation does not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T2_INSHA_YA_MASIMULIZI.INSHA_MASIMULIZI.M4_INS_TENSE_T2', 'KISW.G4.KUANDI.T2_INSHA_YA_MASIMULIZI.INSHA_MASIMULIZI', 'Tells a past story in the present tense (-na-), or mixes -na- and -li- in one story.', '{"question":"Ni sentensi ipi inafaa katika masimulizi ya jambo lililotokea jana: \"Siku Nilipokula na Wageni\"?","wrong_answer":"Jana jioni tunakula chakula pamoja na wageni wetu.","correct_answer":"Jana jioni tulikula chakula pamoja na wageni wetu."}'::jsonb, 'The child writes as he speaks while remembering, and English stories in class are told in the present too.', 'The question "Ni sentensi ipi inafaa katika masimulizi ya jambo lililotokea jana: "Siku Nilipokula na Wageni"?" with "Jana jioni tunakula chakula pamoja na wageni wetu." among the options.', 'Circle every verb; check its tense marker against the time words (jana, siku moja).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T2_INSHA_YA_MASIMULIZI.INSHA_MASIMULIZI.M4_INS_ORDER_T2', 'KISW.G4.KUANDI.T2_INSHA_YA_MASIMULIZI.INSHA_MASIMULIZI', 'Puts the events in an order that cannot have happened (the end before the start), with no linking words.', '{"question":"Ni mpangilio upi wa matukio unafaa katika insha \"Siku Nilipokula na Wageni\"?","wrong_answer":"tulishukuru, tulikula, tuliketi mezani, tulinawa mikono","correct_answer":"tulinawa mikono, tuliketi mezani, tulikula, tulishukuru"}'::jsonb, 'The child writes events as they come to mind; nobody has asked for a plan first.', 'The question "Ni mpangilio upi wa matukio unafaa katika insha "Siku Nilipokula na Wageni"?" with "tulishukuru, tulikula, tuliketi mezani, tulinawa mikono" among the options.', 'Plan with three boxes (mwanzo, kati, mwisho) and linking words (kwanza, kisha, hatimaye) before writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T2_INSHA_YA_MASIMULIZI.INSHA_MASIMULIZI.M4_INS_END_T2', 'KISW.G4.KUANDI.T2_INSHA_YA_MASIMULIZI.INSHA_MASIMULIZI', 'Ends the insha abruptly ("Mwisho." or "The end") with no closing paragraph (hitimisho).', '{"question":"Ni ipi ni hitimisho bora la insha \"Siku Nilipokula na Wageni\"?","wrong_answer":"Mwisho.","correct_answer":"Tangu siku hiyo, nimejifunza kuwa mwangalifu kila wakati."}'::jsonb, 'Storybooks for young readers end with "Mwisho" and the child copies that.', 'The question "Ni ipi ni hitimisho bora la insha "Siku Nilipokula na Wageni"?" with "Mwisho." among the options.', 'Show three endings; the child picks the one that closes the main idea or the lesson.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T2_VIWAKILISHI.VIWAKILISHI.M4_PRON_NOUN', 'KISW.G4.SARUFI.T2_VIWAKILISHI.VIWAKILISHI', 'Repeats the noun instead of using a pronoun.', '{"question":"Wanjiru ni msichana. ___ anapenda kusoma.","wrong_answer":"Wanjiru","correct_answer":"Yeye"}'::jsonb, 'The child does not see that a pronoun stands in place of the name.', 'A second sentence that needs a pronoun, with the name among the options.', 'Ask: which word saves us saying the name again?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T2_VIWAKILISHI.VIWAKILISHI.M4_PRON_NUMBER', 'KISW.G4.SARUFI.T2_VIWAKILISHI.VIWAKILISHI', 'Uses a pronoun for one where there are many, or for many where there is one (yeye for wao).', '{"question":"Juma na Otieno ni marafiki. ___ wanacheza pamoja.","wrong_answer":"Yeye","correct_answer":"Wao"}'::jsonb, 'The child does not count the people.', 'A pair of people with a one-person pronoun among the options.', 'Count the people. One is "yeye", many are "wao".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T2_VIWAKILISHI.VIWAKILISHI.M4_PRON_PERSON', 'KISW.G4.SARUFI.T2_VIWAKILISHI.VIWAKILISHI', 'Swaps the person (mimi, wewe, yeye, sisi, nyinyi, wao).', '{"question":"Mimi na wewe ni marafiki. ___ tunasoma pamoja.","wrong_answer":"Wao","correct_answer":"Sisi"}'::jsonb, 'The child knows the pronouns but not who is speaking.', 'A sentence about the speaker and the listener.', 'Does it include me, the speaker?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T2_VIWAKILISHI.VIWAKILISHI.M4_PRON_DIST', 'KISW.G4.SARUFI.T2_VIWAKILISHI.VIWAKILISHI', 'Swaps the near and the far one (huyu for yule, hawa for wale).', '{"question":"Angalia, ___ ni mwalimu wetu, ameketi karibu nami.","wrong_answer":"Yule","correct_answer":"Huyu"}'::jsonb, 'The child does not take the distance into account.', 'A person who is close and a person who is far, with both words as options.', 'Is the person near you or far from you?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T2_VIELEZI.VIELEZI.M4_ADV_ADJ', 'KISW.G4.SARUFI.T2_VIELEZI.VIELEZI', 'Uses an adjective for an adverb (anaimba nzuri for anaimba vizuri).', '{"question":"Wanafunzi wanaimba ___ darasani.","wrong_answer":"nzuri","correct_answer":"vizuri"}'::jsonb, 'The child uses the describing word of a noun for the way something is done.', 'A gap that tells how something is done, with the adjective among the options.', 'Does it tell how they sing, or what kind of thing it is?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T2_VIELEZI.VIELEZI.M4_ADV_NOUN', 'KISW.G4.SARUFI.T2_VIELEZI.VIELEZI', 'Picks a noun for an adverb.', '{"question":"Mtoto alikimbia ___ kuelekea nyumbani.","wrong_answer":"barabara","correct_answer":"haraka"}'::jsonb, 'The child picks a word of the place and not the way.', 'A gap that tells how something is done, with a noun among the options.', 'Does the word tell how he ran?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T2_VIELEZI.VIELEZI.M4_ADV_TYPE', 'KISW.G4.SARUFI.T2_VIELEZI.VIELEZI', 'Mixes the three kinds of adverb (time, place, manner).', '{"question":"Kielezi \"jana\" kinaonyesha ___.","wrong_answer":"mahali","correct_answer":"wakati"}'::jsonb, 'The child knows the word is an adverb but not what it tells.', 'Adverbs of time, place and manner asked in turn.', 'Ask: does it tell when, where or how?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T2_VIELEZI.VIELEZI.M4_ADV_PLACE_NOUN', 'KISW.G4.SARUFI.T2_VIELEZI.VIELEZI', 'Takes a place word (nyumbani, shuleni) for a noun, not an adverb of place, in a sentence.', '{"question":"Neno \"shuleni\" katika \"Tunasoma shuleni\" ni nini?","wrong_answer":"nomino","correct_answer":"kielezi cha mahali"}'::jsonb, 'The child sees the noun shule inside the word and stops there.', 'The question "Neno "shuleni" katika "Tunasoma shuleni" ni nini?" with "nomino" among the options.', 'Ask what question the word answers: wapi? lini? vipi? The -ni ending turns the noun into a place word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSIKI.T3_VITENDAWILI.VITENDAWILI.M4_VIT_METHALI', 'KISW.G4.KUSIKI.T3_VITENDAWILI.VITENDAWILI', 'Takes a methali for a riddle.', '{"question":"Ni kitendawili kipi?","wrong_answer":"Mtoto umleavyo ndivyo akuavyo","correct_answer":"Popote niendapo hunifuata"}'::jsonb, 'Both are short sayings.', 'A riddle and a methali.', 'A riddle hides an answer. Can you guess it?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSIKI.T3_VITENDAWILI.VITENDAWILI.M4_VIT_NAHAU', 'KISW.G4.KUSIKI.T3_VITENDAWILI.VITENDAWILI', 'Takes a nahau for a riddle.', '{"question":"Ni kitendawili kipi?","wrong_answer":"kupiga moyo konde","correct_answer":"Nyumba yangu haina mlango"}'::jsonb, 'Both can be a short phrase.', 'A riddle and a nahau.', 'Can you give an answer to it?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSIKI.T3_VITENDAWILI.VITENDAWILI.M4_VIT_PLAIN', 'KISW.G4.KUSIKI.T3_VITENDAWILI.VITENDAWILI', 'Takes an ordinary sentence for a riddle.', '{"question":"Ni kitendawili kipi?","wrong_answer":"Yai ni chakula kizuri","correct_answer":"Nyumba yangu haina mlango"}'::jsonb, 'The child does not see that a riddle hides the thing it describes.', 'A riddle and a plain sentence.', 'Does the text name the thing, or hide it?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSIKI.T3_VITENDAWILI.VITENDAWILI.M4_VIT_FORMULA', 'KISW.G4.KUSIKI.T3_VITENDAWILI.VITENDAWILI', 'Does not know the words used when riddling (Kitendawili! Tega!).', '{"question":"Mtegaji husema \"Kitendawili!\" Mtegua hujibu \"___!\"","wrong_answer":"Karibu","correct_answer":"Tega"}'::jsonb, 'The child has heard a riddle told but not the fixed words.', 'The opening and the giving-up words.', 'What does the guesser say to say he is ready?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSIKI.T3_VITENDAWILI.VITENDAWILI.M4_VIT_WRONG_ANSWER', 'KISW.G4.KUSIKI.T3_VITENDAWILI.VITENDAWILI', 'Gives a thing that shares one detail with the riddle but is not the answer.', '{"question":"\"Popote niendapo hunifuata.\" Jibu ni nini?","wrong_answer":"mbwa","correct_answer":"kivuli"}'::jsonb, 'The child picks the first thing that comes to mind.', 'A riddle with plausible answers.', 'Test each answer against every part of the riddle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T3_KUSOMA_KWA_UFASAHA.UFASAHA_VIPENGELE.M4_UFS_SPEED', 'KISW.G4.KUSOMA.T3_KUSOMA_KWA_UFASAHA.UFASAHA_VIPENGELE', 'Thinks that reading fast is reading well.', '{"question":"Ni nini kinachoonyesha kusoma kwa ufasaha?","wrong_answer":"Kusoma haraka iwezekanavyo","correct_answer":"Kusoma kwa kasi ifaayo"}'::jsonb, 'The child hears that good readers are quick.', 'Fast and fitting as options.', 'Can the listener follow every word?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T3_KUSOMA_KWA_UFASAHA.UFASAHA_VIPENGELE.M4_UFS_LOUD', 'KISW.G4.KUSOMA.T3_KUSOMA_KWA_UFASAHA.UFASAHA_VIPENGELE', 'Thinks that reading loud is reading well.', '{"question":"Sauti ipasavyo wakati wa kusoma ni ipi?","wrong_answer":"Kupiga kelele","correct_answer":"Sauti inayosikika wazi"}'::jsonb, 'The child takes loud for clear.', 'Loud and clear as options.', 'Is a shout the same as a clear voice?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T3_KUSOMA_KWA_UFASAHA.UFASAHA_VIPENGELE.M4_UFS_IGNORE_MARKS', 'KISW.G4.KUSOMA.T3_KUSOMA_KWA_UFASAHA.UFASAHA_VIPENGELE', 'Ignores the koma and the kikomo.', '{"question":"Ukifika kwenye koma, ufanye nini?","wrong_answer":"Niendelee bila kupumzika","correct_answer":"Nipumzike kidogo"}'::jsonb, 'The child reads the words and skips the marks.', 'A mark that asks for a rest.', 'What does the mark tell the reader to do?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T3_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M4_UFS_WORDBYWORD_T3', 'KISW.G4.KUSOMA.T3_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads word by word or syllable by syllable, so the sentence has no meaning when heard.', '{"question":"Ni usomaji upi ni wa ufasaha: \"Mama alinunua sare mpya ya shule sokoni.\"?","wrong_answer":"Mama ... alinunua ... sare ... mpya ... ya ... shule ... sokoni.","correct_answer":"Mama alinunua sare mpya ya shule sokoni."}'::jsonb, 'The child is still decoding each word and has not yet learnt to read a phrase as one piece.', 'The question "Ni usomaji upi ni wa ufasaha: "Mama alinunua sare mpya ya shule sokoni."?" with "Mama ... alinunua ... sare ... mpya ... ya ... shule ... sokoni." among the options.', 'Echo reading: the teacher reads a phrase, the child repeats it as one breath; then phrase-cut the passage with slashes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T3_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M4_UFS_RACE_T3', 'KISW.G4.KUSOMA.T3_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads as fast as possible and thinks the fastest reader is the best.', '{"question":"Ni kasi ipi ifaayo ya kusoma kifungu darasani?","wrong_answer":"haraka iwezekanavyo","correct_answer":"kasi ya kuzungumza, ili kila neno lisikike"}'::jsonb, 'Reading races in class reward speed; the child has not been asked whether listeners understood.', 'The question "Ni kasi ipi ifaayo ya kusoma kifungu darasani?" with "haraka iwezekanavyo" among the options.', 'Time two readings: one very fast, one at speaking pace; listeners answer one question after each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T3_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M4_UFS_FLAT_T3', 'KISW.G4.KUSOMA.T3_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads a question and an exclamation in the same flat voice as a statement.', '{"question":"Sentensi \"Je, umevaa koti lako leo?\" inasomwa vipi?","wrong_answer":"kwa sauti ileile ya sentensi ya kawaida","correct_answer":"sauti hupanda mwishoni kwa sababu ni swali"}'::jsonb, 'The child looks at the words and not at the mark at the end.', 'The question "Sentensi "Je, umevaa koti lako leo?" inasomwa vipi?" with "kwa sauti ileile ya sentensi ya kawaida" among the options.', 'Read the same words three ways (. ? !); the child points at the mark that matches each reading.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T3_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M4_UFS_NOPAUSE_T3', 'KISW.G4.KUSOMA.T3_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads on through the koma and the kikomo without a pause.', '{"question":"Unasoma: \"Lo, viatu vyako vinang''aa sana!\" Unasimama wapi kidogo?","wrong_answer":"hapana mahali, unasoma moja kwa moja","correct_answer":"kwenye koma na kwenye kikomo au alama ya hisi"}'::jsonb, 'The marks are read as decoration; the child has not linked them to breath.', 'The question "Unasoma: "Lo, viatu vyako vinang''aa sana!" Unasimama wapi kidogo?" with "hapana mahali, unasoma moja kwa moja" among the options.', 'Clap once at a koma, twice at a kikomo while reading together.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T3_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M4_UFS_SOUND_T3', 'KISW.G4.KUSOMA.T3_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Says /l/ for /r/ or /r/ for /l/ while reading (rangi read as langi).', '{"question":"Neno \"rangi\" linatamkwa vipi?","wrong_answer":"langi","correct_answer":"rangi"}'::jsonb, 'The first language of the child does not separate these sounds, so the reading carries the home sound.', 'The question "Neno "rangi" linatamkwa vipi?" with "langi" among the options.', 'Make a list of the passage words with the hard sound; practise them before reading the passage.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T3_KUSOMA_KWA_UFASAHA.UFASAHA_VIPENGELE.M4_UFS_NO_GESTURE', 'KISW.G4.KUSOMA.T3_KUSOMA_KWA_UFASAHA.UFASAHA_VIPENGELE', 'Thinks gestures and looking up at the listeners have nothing to do with reading well.', '{"question":"Ni kipi ni kipengele cha kusoma kwa ufasaha?","wrong_answer":"kuangalia kitabu tu bila kuwaangalia wasikilizaji","correct_answer":"kuambatanisha ishara na kuwaangalia wasikilizaji mara kwa mara"}'::jsonb, 'Reading has only been practised silently or with eyes on the page.', 'The question "Ni kipi ni kipengele cha kusoma kwa ufasaha?" with "kuangalia kitabu tu bila kuwaangalia wasikilizaji" among the options.', 'Watch a good reader: list what the body does as well as the voice.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T3_KUANDIKA_KWA_TARAKIL.SEHEMU_TARAKILISHI.M4_TAR_MIX_PARTS', 'KISW.G4.KUANDI.T3_KUANDIKA_KWA_TARAKIL.SEHEMU_TARAKILISHI', 'Mixes the parts of a computer (kibodi, kipanya, skrini).', '{"question":"Tunatumia ___ kupigia herufi na nambari.","wrong_answer":"kipanya","correct_answer":"kibodi"}'::jsonb, 'The child knows the names but not what each is.', 'Parts asked by what they are used for.', 'What do you hold, press or look at?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T3_KUANDIKA_KWA_TARAKIL.SEHEMU_TARAKILISHI.M4_TAR_FUNCTION', 'KISW.G4.KUANDI.T3_KUANDIKA_KWA_TARAKIL.SEHEMU_TARAKILISHI', 'Gives the use of another part.', '{"question":"Skrini hufanya nini?","wrong_answer":"Huchapisha kwenye karatasi","correct_answer":"Huonyesha maandishi na picha"}'::jsonb, 'The child has the right word for the wrong job.', 'The use of the part asked in turn.', 'What do you do with this part?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T3_KUANDIKA_KWA_TARAKIL.UAKIFISHI.M4_UAK_CAPITAL', 'KISW.G4.KUANDI.T3_KUANDIKA_KWA_TARAKIL.UAKIFISHI', 'Starts a sentence or a name with a small letter.', '{"question":"Chagua sentensi sahihi.","wrong_answer":"unaenda wapi?","correct_answer":"Unaenda wapi?"}'::jsonb, 'The child does not see the first letter.', 'The same sentence with a small and a capital letter.', 'What do we write first in a sentence?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T3_KUANDIKA_KWA_TARAKIL.UAKIFISHI.M4_UAK_FULLSTOP', 'KISW.G4.KUANDI.T3_KUANDIKA_KWA_TARAKIL.UAKIFISHI', 'Ends a question with a kikomo (.) instead of a kiulizi (?).', '{"question":"Chagua sentensi sahihi.","wrong_answer":"Unaenda wapi.","correct_answer":"Unaenda wapi?"}'::jsonb, 'The child ends every sentence with a full stop.', 'The same question with different marks.', 'Is the sentence asking?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T3_KUANDIKA_KWA_TARAKIL.UAKIFISHI.M4_UAK_KOMA', 'KISW.G4.KUANDI.T3_KUANDIKA_KWA_TARAKIL.UAKIFISHI', 'Leaves out the koma in a list, or puts it in the wrong place.', '{"question":"Chagua sentensi sahihi.","wrong_answer":"Nilinunua maembe machungwa na ndizi.","correct_answer":"Nilinunua maembe, machungwa na ndizi."}'::jsonb, 'The child does not pause the sentence where the list items end.', 'A list with and without koma.', 'Where would you rest your voice?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T3_KUANDIKA_KWA_TARAKIL.UAKIFISHI.M4_UAK_MARK', 'KISW.G4.KUANDI.T3_KUANDIKA_KWA_TARAKIL.UAKIFISHI', 'Uses the wrong mark for a feeling (alama ya hisi !) or for a question.', '{"question":"Chagua sentensi sahihi.","wrong_answer":"Hongera?","correct_answer":"Hongera!"}'::jsonb, 'The child does not tell a feeling from a question.', 'An exclamation with ! and ?.', 'Is it asking, or showing a feeling?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T3_KUANDIKA_KWA_TARAKIL.UAKIFISHI.M4_UAK_NO_END', 'KISW.G4.KUANDI.T3_KUANDIKA_KWA_TARAKIL.UAKIFISHI', 'Leaves out the mark at the end of the sentence.', '{"question":"Chagua sentensi sahihi.","wrong_answer":"Wanjiru alienda Mombasa jana","correct_answer":"Wanjiru alienda Mombasa jana."}'::jsonb, 'The child stops writing at the last word.', 'The same sentence with and without its closing mark.', 'How does a sentence end?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T3_KUANDIKA_KWA_TARAKIL.KAZI_TARAKILISHI.M4_TAK_OFF_PLUG', 'KISW.G4.KUANDI.T3_KUANDIKA_KWA_TARAKIL.KAZI_TARAKILISHI', 'Switches the computer off by pulling the plug or pressing the power button at once, losing the work.', '{"question":"Umemaliza kazi. Unazimaje tarakilishi?","wrong_answer":"chomoa waya wa umeme","correct_answer":"hifadhi kazi, funga programu, kisha zima kupitia menyu"}'::jsonb, 'At home a television or radio is switched off at the plug.', 'The question "Umemaliza kazi. Unazimaje tarakilishi?" with "chomoa waya wa umeme" among the options.', 'Practise the shut-down steps with step cards, then on a real machine.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T3_KUANDIKA_KWA_TARAKIL.KAZI_TARAKILISHI.M4_TAK_NO_SAVE', 'KISW.G4.KUANDI.T3_KUANDIKA_KWA_TARAKIL.KAZI_TARAKILISHI', 'Closes the document without saving, or saves with no name (Document1) where he cannot find it.', '{"question":"Ni jina lipi bora la faili ya insha yako ya mavazi?","wrong_answer":"Document1","correct_answer":"Insha ya Mavazi - Wanjiru"}'::jsonb, 'The child does not know that the work disappears or that the name is how he finds it again.', 'The question "Ni jina lipi bora la faili ya insha yako ya mavazi?" with "Document1" among the options.', 'Save, close, then reopen the file by its name in front of the class.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T3_KUANDIKA_KWA_TARAKIL.KAZI_TARAKILISHI.M4_TAK_SPACE', 'KISW.G4.KUANDI.T3_KUANDIKA_KWA_TARAKIL.KAZI_TARAKILISHI', 'Types words without spaces, or presses the space bar many times instead of using Enter for a new line.', '{"question":"Ni kitufe kipi huanzisha mstari mpya?","wrong_answer":"kitufe cha nafasi mara nyingi","correct_answer":"kitufe cha Enter"}'::jsonb, 'The child has not met the job of each big key.', 'The question "Ni kitufe kipi huanzisha mstari mpya?" with "kitufe cha nafasi mara nyingi" among the options.', 'Label the space bar, Enter, Shift and Backspace; type one line, then a new one.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T3_KUANDIKA_KWA_TARAKIL.KAZI_TARAKILISHI.M4_TAK_CAPS', 'KISW.G4.KUANDI.T3_KUANDIKA_KWA_TARAKIL.KAZI_TARAKILISHI', 'Leaves caps lock on and types the whole text in capitals, or never makes a capital at the start of a sentence.', '{"question":"Unataka herufi kubwa moja tu mwanzoni mwa sentensi. Unafanya nini?","wrong_answer":"washa Caps Lock na uandike sentensi yote","correct_answer":"shikilia Shift na ubonyeze herufi"}'::jsonb, 'The caps lock light is the only way of making capitals the child has seen.', 'The question "Unataka herufi kubwa moja tu mwanzoni mwa sentensi. Unafanya nini?" with "washa Caps Lock na uandike sentensi yote" among the options.', 'Type one sentence with Shift for the first letter; compare with all capitals.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T3_KUANDIKA_KWA_TARAKIL.SEHEMU_TARAKILISHI.M4_TAR_CPU_SCREEN', 'KISW.G4.KUANDI.T3_KUANDIKA_KWA_TARAKIL.SEHEMU_TARAKILISHI', 'Thinks the screen is the computer and the box (kitengo kikuu) only holds the cables.', '{"question":"Sehemu ipi ya tarakilishi hufanya kazi ya kufikiri na kuhifadhi?","wrong_answer":"skrini","correct_answer":"kitengo kikuu (CPU)"}'::jsonb, 'The screen is where everything is seen, so the child takes it for the computer.', 'The question "Sehemu ipi ya tarakilishi hufanya kazi ya kufikiri na kuhifadhi?" with "skrini" among the options.', 'Switch the screen off while the computer runs; the work is still there.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T3_KUANDIKA_KWA_TARAKIL.SEHEMU_TARAKILISHI.M4_TAR_ENGLISH_NAMES', 'KISW.G4.KUANDI.T3_KUANDIKA_KWA_TARAKIL.SEHEMU_TARAKILISHI', 'Knows the parts only by their English names (mouse, keyboard) and not kipanya and kibodi.', '{"question":"Kipanya ni sehemu ipi?","wrong_answer":"keyboard","correct_answer":"kifaa kidogo cha kusogeza mshale (mouse)"}'::jsonb, 'The lab and the computer itself use English names.', 'The question "Kipanya ni sehemu ipi?" with "keyboard" among the options.', 'Label the parts in Kiswahili and use only those in class.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T3_VIUNGANISHI.VIUNGANISHI.M4_CONJ_SWAP', 'KISW.G4.SARUFI.T3_VIUNGANISHI.VIUNGANISHI', 'Picks a joining word of another meaning (kwa sababu for lakini, ili for au).', '{"question":"Alitaka kuogelea, ___ ziwa lilikuwa na mawimbi makali.","wrong_answer":"kwa sababu","correct_answer":"lakini"}'::jsonb, 'The child picks a joining word without asking how the two parts are related.', 'Two parts that are in contrast, with the reason word among the options.', 'Do the two parts agree, or does the second go against the first?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T3_VIUNGANISHI.VIUNGANISHI.M4_CONJ_NOT', 'KISW.G4.SARUFI.T3_VIUNGANISHI.VIUNGANISHI', 'Picks a noun or a verb for a joining word.', '{"question":"Juma ___ Otieno ni marafiki.","wrong_answer":"rafiki","correct_answer":"na"}'::jsonb, 'The child chooses a word that is already in the sentence.', 'A gap between two names, with a noun among the options.', 'Which word joins the two names?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T3_VIUNGANISHI.VIUNGANISHI.M4_CONJ_NA_ALL', 'KISW.G4.SARUFI.T3_VIUNGANISHI.VIUNGANISHI', 'Uses na for every join, even where the meaning is "but" or "because" (Nilienda na sikumpata).', '{"question":"Jaza: Nilienda kwake ___ sikumpata.","wrong_answer":"na","correct_answer":"lakini"}'::jsonb, 'Na is the first joining word learnt and covers "and" for everything.', 'The question "Jaza: Nilienda kwake ___ sikumpata." with "na" among the options.', 'Ask whether the second part agrees with the first or goes against it; against means lakini.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T3_VIUNGANISHI.VIUNGANISHI.M4_CONJ_REASON_RESULT', 'KISW.G4.SARUFI.T3_VIUNGANISHI.VIUNGANISHI', 'Swaps the reason and the result (kwa hiyo for kwa sababu).', '{"question":"Jaza: Hakuja shuleni ___ alikuwa mgonjwa.","wrong_answer":"kwa hiyo","correct_answer":"kwa sababu"}'::jsonb, 'Both words link a cause and an effect; the child does not check which part is the cause.', 'The question "Jaza: Hakuja shuleni ___ alikuwa mgonjwa." with "kwa hiyo" among the options.', 'Draw an arrow from cause to effect; kwa sababu points back to the cause, kwa hiyo forward to the result.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T3_VIHUSISHI.VIHUSISHI.M4_PREP_NOT', 'KISW.G4.SARUFI.T3_VIHUSISHI.VIHUSISHI', 'Picks a noun, a verb or an adjective as the relating word.', '{"question":"Ni kihusishi kipi katika sentensi: \"Kitabu kiko juu ya meza.\"","wrong_answer":"meza","correct_answer":"juu ya"}'::jsonb, 'The child picks the word that is easiest to see.', 'A sentence with a place word, with the nouns as options.', 'Which words tell where the book is in relation to the table?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T3_VIHUSISHI.VIHUSISHI.M4_PREP_A_CLASS', 'KISW.G4.SARUFI.T3_VIHUSISHI.VIHUSISHI', 'Uses the wrong -a of agreement for the noun (kitabu wa mwalimu, nyumba cha bibi).', '{"question":"Kitabu ___ mwalimu kiko mezani.","wrong_answer":"wa","correct_answer":"cha"}'::jsonb, 'The child keeps one form for every noun.', 'Nouns of different classes before the same word.', 'Which class is the noun in? Kitabu is KI-VI, so cha.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T3_VIHUSISHI.VIHUSISHI.M4_PREP_SWAP', 'KISW.G4.SARUFI.T3_VIHUSISHI.VIHUSISHI', 'Swaps place words that mean the opposite (juu ya for chini ya, ndani ya for nje ya).', '{"question":"Samaki wanaishi ___ ya maji, si nje yake.","wrong_answer":"juu","correct_answer":"ndani"}'::jsonb, 'The child knows the words but not which way each points.', 'A sentence that says where, with the opposite word among the options.', 'Read the clue in the sentence: inside or outside?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T3_VIHUSISHI.VIHUSISHI.M4_PREP_KWA_NA', 'KISW.G4.SARUFI.T3_VIHUSISHI.VIHUSISHI', 'Uses na where the tool is meant (aliandika na kalamu) or kwa where the companion is meant (alienda kwa mama).', '{"question":"Jaza: Aliandika barua ___ kalamu.","wrong_answer":"na","correct_answer":"kwa"}'::jsonb, 'English "with" covers both the tool and the companion.', 'The question "Jaza: Aliandika barua ___ kalamu." with "na" among the options.', 'Ask: is it a tool (kwa) or a person going along (na)?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T3_VIHISISHI.VIHISISHI.M4_INT_SWAP', 'KISW.G4.SARUFI.T3_VIHISISHI.VIHISISHI', 'Picks an exclamation of another feeling (hongera for pole).', '{"question":"Mwenzako ameanguka na kuumia. Utasema ___!","wrong_answer":"Hongera","correct_answer":"Pole"}'::jsonb, 'The child knows the words but does not ask what the feeling is.', 'A sad situation, with a happy word among the options.', 'What does the other person feel? What would you say?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T3_VIHISISHI.VIHISISHI.M4_INT_NOT', 'KISW.G4.SARUFI.T3_VIHISISHI.VIHISISHI', 'Picks a noun or a verb for an exclamation.', '{"question":"Hongera! Juma ameshinda mbio za shule. Ni kihisishi kipi?","wrong_answer":"Juma","correct_answer":"Hongera"}'::jsonb, 'The child does not know the exclamation has the mark ! and shows a feeling.', 'A sentence that begins with an exclamation, with the other words as options.', 'Which word shows a feeling and carries the mark !?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T3_VIHISISHI.VIHISISHI.M4_INT_NO_MARK', 'KISW.G4.SARUFI.T3_VIHISISHI.VIHISISHI', 'Writes an exclamation with a kikomo or no mark, not the alama ya hisi (!).', '{"question":"Ni ipi imeandikwa ipasavyo?","wrong_answer":"Lo. Umependeza.","correct_answer":"Lo! Umependeza."}'::jsonb, 'The child knows the word but not that its feeling is shown with a mark.', 'The question "Ni ipi imeandikwa ipasavyo?" with "Lo. Umependeza." among the options.', 'Read the line with and without feeling; the ! asks for the feeling.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T3_VIHISISHI.VIHISISHI.M4_INT_ENGLISH', 'KISW.G4.SARUFI.T3_VIHISISHI.VIHISISHI', 'Uses an English exclamation (Wow!, Sorry!, Eish!) in a Kiswahili sentence.', '{"question":"Ni kihisishi kipi cha Kiswahili kinaonyesha mshangao?","wrong_answer":"Wow!","correct_answer":"Lo!"}'::jsonb, 'The child hears English and Sheng exclamations every day.', 'The question "Ni kihisishi kipi cha Kiswahili kinaonyesha mshangao?" with "Wow!" among the options.', 'Make a feelings chart in Kiswahili: mshangao (Lo! Ala!), huzuni (Pole! Ole!), furaha (Hongera!).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSIKI.T4_MANENO_YA_UPOLE.UPOLE.M4_UPO_RUDE', 'KISW.G4.KUSIKI.T4_MANENO_YA_UPOLE.UPOLE', 'Asks with a command and no polite word (Nipe maji!).', '{"question":"Chagua sentensi yenye upole.","wrong_answer":"Nipe maji!","correct_answer":"Tafadhali, naomba maji."}'::jsonb, 'The child does not hear the tone of the order.', 'A request and a command side by side.', 'Which one would you like to be asked?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSIKI.T4_MANENO_YA_UPOLE.UPOLE.M4_UPO_SWAP', 'KISW.G4.KUSIKI.T4_MANENO_YA_UPOLE.UPOLE', 'Swaps the polite words (asante for samahani).', '{"question":"Umemgonga mwenzako kwa bahati mbaya. Utasema \"___.\"","wrong_answer":"Asante","correct_answer":"Samahani"}'::jsonb, 'The child knows the words but not what each is for.', 'A situation with a thank-you, an apology and a request among the options.', 'What did you do, and what would you want to say?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSIKI.T4_MANENO_YA_UPOLE.UPOLE.M4_UPO_NOT', 'KISW.G4.KUSIKI.T4_MANENO_YA_UPOLE.UPOLE', 'Takes a plain sentence for a polite one.', '{"question":"Ni sentensi ipi ina neno la upole?","wrong_answer":"Nimekuja.","correct_answer":"Tafadhali, ingia."}'::jsonb, 'The child does not look for the polite word.', 'Sentences with and without a polite word.', 'Which sentence has a word like tafadhali, samahani or asante?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSIKI.T4_MANENO_YA_UPOLE.UPOLE.M4_UPO_TAFADHALI_END', 'KISW.G4.KUSIKI.T4_MANENO_YA_UPOLE.UPOLE', 'Puts the polite word in, but keeps a command form that sounds rude (Lete maji tafadhali sasa hivi!).', '{"question":"Ni ombi lipi lina upole zaidi?","wrong_answer":"Lete maji sasa hivi, tafadhali!","correct_answer":"Tafadhali, naomba unipe maji."}'::jsonb, 'The child thinks adding tafadhali is enough, whatever the rest of the sentence.', 'The question "Ni ombi lipi lina upole zaidi?" with "Lete maji sasa hivi, tafadhali!" among the options.', 'Compare tone: a command with tafadhali and a request with naomba; listen to both.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T4_KUSOMA_KWA_MAPANA.USALAMA_DIJITALI.M4_DIG_SHARE', 'KISW.G4.KUSOMA.T4_KUSOMA_KWA_MAPANA.USALAMA_DIJITALI', 'Gives out a password or a private detail.', '{"question":"Rafiki anakuomba nenosiri la simu yako. Ufanye nini?","wrong_answer":"Nimpe kwa muda mfupi tu","correct_answer":"Nikatae na niweke siri"}'::jsonb, 'The child thinks that sharing with a friend is harmless.', 'A friend or a stranger who asks.', 'Who should know the password?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T4_KUSOMA_KWA_MAPANA.USALAMA_DIJITALI.M4_DIG_LINK', 'KISW.G4.KUSOMA.T4_KUSOMA_KWA_MAPANA.USALAMA_DIJITALI', 'Opens an unknown link or file.', '{"question":"Umetumiwa kiungo usichokijua. Ufanye nini?","wrong_answer":"Nikifungue haraka","correct_answer":"Nimwonyeshe mtu mzima kwanza"}'::jsonb, 'The child is curious.', 'A message with a link from a stranger.', 'Can you tell where the link leads?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T4_KUSOMA_KWA_MAPANA.USALAMA_DIJITALI.M4_DIG_UNSAFE_SITE', 'KISW.G4.KUSOMA.T4_KUSOMA_KWA_MAPANA.USALAMA_DIJITALI', 'Uses any site, or one that asks for private details.', '{"question":"Unatafuta kifungu cha kusoma mtandaoni. Utumie tovuti ipi?","wrong_answer":"Tovuti yoyote inayotokea kwanza","correct_answer":"Tovuti iliyopendekezwa na mwalimu"}'::jsonb, 'The child takes the first result.', 'A site that asks for a phone number or money.', 'Who said the site is safe?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T4_KUSOMA_KWA_MAPANA.KUSOMA_KIDIJITALI.M4_KID_FOLDER_T4', 'KISW.G4.KUSOMA.T4_KUSOMA_KWA_MAPANA.KUSOMA_KIDIJITALI', 'Mixes up a folder and a file: looks for the passage on the screen without opening the folder it is in.', '{"question":"Kifungu \"Dira na mwelekeo\" kimehifadhiwa ndani ya folda \"Kiswahili\". Utakifunguaje?","wrong_answer":"bonyeza \"Dira na mwelekeo\" kwenye skrini ya mwanzo","correct_answer":"fungua folda \"Kiswahili\", kisha bonyeza mara mbili faili \"Dira na mwelekeo\""}'::jsonb, 'The child has only used apps on a phone, where there are no folders.', 'The question "Kifungu "Dira na mwelekeo" kimehifadhiwa ndani ya folda "Kiswahili". Utakifunguaje?" with "bonyeza "Dira na mwelekeo" kwenye skrini ya mwanzo" among the options.', 'Show a real folder (a box file) holding papers; then the same on the screen.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T4_KUSOMA_KWA_MAPANA.KUSOMA_KIDIJITALI.M4_KID_SEARCH_T4', 'KISW.G4.KUSOMA.T4_KUSOMA_KWA_MAPANA.KUSOMA_KIDIJITALI', 'Types a whole long question, with spelling mistakes, into the search box.', '{"question":"Unatafuta habari kuhusu dira. Utaandika nini kwenye kisanduku cha kutafutia?","wrong_answer":"naomba unipe habari zote kuhusu dira tafadhali","correct_answer":"dira mwelekeo watoto"}'::jsonb, 'The child talks to the search box as to a person.', 'The question "Unatafuta habari kuhusu dira. Utaandika nini kwenye kisanduku cha kutafutia?" with "naomba unipe habari zote kuhusu dira tafadhali" among the options.', 'Underline the two or three words that carry the meaning; search with those; compare the results.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T4_KUSOMA_KWA_MAPANA.KUSOMA_KIDIJITALI.M4_KID_POPUP_T4', 'KISW.G4.KUSOMA.T4_KUSOMA_KWA_MAPANA.KUSOMA_KIDIJITALI', 'Clicks a pop-up or an advert that says he has won a prize.', '{"question":"Ukiwa unasoma, ujumbe unatokea: \"Umeshinda simu! Bonyeza hapa.\" Ufanye nini?","wrong_answer":"bonyeza ili kupokea simu","correct_answer":"usibonyeze; funga ujumbe na umwambie mwalimu au mzazi"}'::jsonb, 'Offers of prizes are exciting and the child does not know they are traps.', 'The question "Ukiwa unasoma, ujumbe unatokea: "Umeshinda simu! Bonyeza hapa." Ufanye nini?" with "bonyeza ili kupokea simu" among the options.', 'Show two screenshots, one real page and one trap; the child finds three signs of the trap.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T4_KUSOMA_KWA_MAPANA.KUSOMA_KIDIJITALI.M4_KID_SITE_T4', 'KISW.G4.KUSOMA.T4_KUSOMA_KWA_MAPANA.KUSOMA_KIDIJITALI', 'Uses any site that comes up and gives his name, school or phone number when a site asks.', '{"question":"Tovuti inakuuliza jina lako kamili, shule yako na nambari ya simu ya mzazi kabla ya kusoma hadithi. Ufanye nini?","wrong_answer":"jaza ili usome hadithi","correct_answer":"usijaze; tumia tovuti salama aliyokupa mwalimu"}'::jsonb, 'The child wants the story and does not see personal details as worth protecting.', 'The question "Tovuti inakuuliza jina lako kamili, shule yako na nambari ya simu ya mzazi kabla ya kusoma hadithi. Ufanye nini?" with "jaza ili usome hadithi" among the options.', 'List the details that are private; practise saying no to a form.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T4_KUSOMA_KWA_MAPANA.KUSOMA_KIDIJITALI.M4_KID_ORDER_T4', 'KISW.G4.KUSOMA.T4_KUSOMA_KWA_MAPANA.KUSOMA_KIDIJITALI', 'Puts the steps of finding and reading a passage in the wrong order (reads before searching, or searches before switching on).', '{"question":"Ni hatua ipi huja kwanza?","wrong_answer":"andika maneno ya kutafutia","correct_answer":"washa tarakilishi na ufungue kivinjari"}'::jsonb, 'The child has watched an adult do the steps quickly and remembers the parts, not the order.', 'The question "Ni hatua ipi huja kwanza?" with "andika maneno ya kutafutia" among the options.', 'Step cards: the child orders them, then does them on a real device.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T4_KUSOMA_KWA_MAPANA.USALAMA_DIJITALI.M4_DIG_STRANGER', 'KISW.G4.KUSOMA.T4_KUSOMA_KWA_MAPANA.USALAMA_DIJITALI', 'Chats with or agrees to meet someone met online.', '{"question":"Mtu usiyemjua anakuandikia mtandaoni: \"Tukutane kesho dukani.\" Ufanye nini?","wrong_answer":"kubali na uende","correct_answer":"usimjibu; mwambie mzazi au mwalimu"}'::jsonb, 'The child thinks a friendly message comes from a friend.', 'The question "Mtu usiyemjua anakuandikia mtandaoni: "Tukutane kesho dukani." Ufanye nini?" with "kubali na uende" among the options.', 'Talk through a safe adult to tell; practise blocking and reporting on a demo screen.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T4_BARUA_YA_KIRAFIKI.BARUA.M4_BAR_ORDER', 'KISW.G4.KUANDI.T4_BARUA_YA_KIRAFIKI.BARUA', 'Puts the parts of a letter in the wrong order.', '{"question":"Barua ya kirafiki huanza kwa anwani ya mwandishi, kisha tarehe, kisha ___.","wrong_answer":"hitimisho","correct_answer":"salamu"}'::jsonb, 'The child knows the parts but not their order.', 'The parts of a letter asked in turn.', 'What comes after the date, and what before the end?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T4_BARUA_YA_KIRAFIKI.BARUA.M4_BAR_GREETING', 'KISW.G4.KUANDI.T4_BARUA_YA_KIRAFIKI.BARUA', 'Writes the wrong greeting or closing for a friend (Wako mtiifu for Rafiki yako).', '{"question":"Hitimisho la barua ya kirafiki ni \"___ \".","wrong_answer":"Wako mtiifu","correct_answer":"Rafiki yako"}'::jsonb, 'The child mixes a friendly letter with an official one.', 'A friendly closing and an official one.', 'Who is the letter to: a friend or an officer?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T4_BARUA_YA_KIRAFIKI.BARUA.M4_BAR_PLACE', 'KISW.G4.KUANDI.T4_BARUA_YA_KIRAFIKI.BARUA', 'Writes the address of the writer in the wrong place.', '{"question":"Anwani ya mwandishi huandikwa upande wa ___ juu.","wrong_answer":"kushoto","correct_answer":"kulia"}'::jsonb, 'The child writes it where the greeting goes.', 'Left and right as options.', 'Which corner is the address of the writer?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T4_BARUA_YA_KIRAFIKI.KUANDIKA_BARUA.M4_INS_FORMAL_T4', 'KISW.G4.KUANDI.T4_BARUA_YA_KIRAFIKI.KUANDIKA_BARUA', 'Writes to a friend in the stiff words of an official letter (Mheshimiwa, Kuhusu:, Wako mtiifu).', '{"question":"Ni salamu ipi inafaa katika barua kwa rafiki?","wrong_answer":"Mheshimiwa Bwana,","correct_answer":"Mpendwa rafiki yangu Amina,"}'::jsonb, 'The child has seen official letters at school and thinks every letter is written that way.', 'The question "Ni salamu ipi inafaa katika barua kwa rafiki?" with "Mheshimiwa Bwana," among the options.', 'Put a friendly and an official letter side by side; the child highlights the words that differ.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T4_BARUA_YA_KIRAFIKI.KUANDIKA_BARUA.M4_INS_NOASK_T4', 'KISW.G4.KUANDI.T4_BARUA_YA_KIRAFIKI.KUANDIKA_BARUA', 'Starts with the news straight after the greeting, with no asking after the friend (maulizo ya hali).', '{"question":"Baada ya salamu, ni sentensi ipi inafuata katika barua ya kirafiki?","wrong_answer":"Nataka kukueleza kuhusu safari yetu.","correct_answer":"Hujambo? Natumai u buheri wa afya."}'::jsonb, 'The child goes to what he wants to say, as in a text message.', 'The question "Baada ya salamu, ni sentensi ipi inafuata katika barua ya kirafiki?" with "Nataka kukueleza kuhusu safari yetu." among the options.', 'Order the parts on cards: anwani, tarehe, salamu, maulizo ya hali, ujumbe, hitimisho, jina.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T4_BARUA_YA_KIRAFIKI.KUANDIKA_BARUA.M4_INS_DATE_T4', 'KISW.G4.KUANDI.T4_BARUA_YA_KIRAFIKI.KUANDIKA_BARUA', 'Leaves out the date or writes it in the middle of the letter.', '{"question":"Tarehe huandikwa wapi katika barua ya kirafiki?","wrong_answer":"mwishoni, baada ya jina","correct_answer":"chini ya anwani ya mwandishi, upande wa kulia juu"}'::jsonb, 'The date is not part of what the child wants to say, so he forgets it.', 'The question "Tarehe huandikwa wapi katika barua ya kirafiki?" with "mwishoni, baada ya jina" among the options.', 'Label a model letter; the child places a date card on a blank layout.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T4_BARUA_YA_KIRAFIKI.KUANDIKA_BARUA.M4_INS_SIGN_T4', 'KISW.G4.KUANDI.T4_BARUA_YA_KIRAFIKI.KUANDIKA_BARUA', 'Ends with "Wako mtiifu" and a full name and title, as in an official letter.', '{"question":"Ni hitimisho lipi linafaa katika barua kwa rafiki?","wrong_answer":"Wako mtiifu, Bw. Juma Hamisi","correct_answer":"Ni mimi rafiki yako, Juma"}'::jsonb, 'Again the official model is the only one the child has copied.', 'The question "Ni hitimisho lipi linafaa katika barua kwa rafiki?" with "Wako mtiifu, Bw. Juma Hamisi" among the options.', 'Collect three friendly closings and keep them in the exercise book.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T4_BARUA_YA_KIRAFIKI.BARUA.M4_BAR_NO_CLOSING', 'KISW.G4.KUANDI.T4_BARUA_YA_KIRAFIKI.BARUA', 'Stops after the news, with no closing line and no name.', '{"question":"Barua ya kirafiki inamalizika vipi?","wrong_answer":"kwa habari ya mwisho tu","correct_answer":"kwa hitimisho kama \"Ni mimi rafiki yako,\" na jina"}'::jsonb, 'The child stops when there is no more to tell, as in talking.', 'The question "Barua ya kirafiki inamalizika vipi?" with "kwa habari ya mwisho tu" among the options.', 'Show where the closing goes on a model letter.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T4_NGELI_YA_A_WA.A_WA.M4_AWA_PL', 'KISW.G4.SARUFI.T4_NGELI_YA_A_WA.A_WA', 'Uses wa- for one person or a- for many people.', '{"question":"Watoto wawili ___naimba.","wrong_answer":"a","correct_answer":"wa"}'::jsonb, 'The child does not count, or goes by the word before.', 'One and many in turn.', 'Count: one or many?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T4_NGELI_YA_A_WA.A_WA.M4_AWA_ANIMAL', 'KISW.G4.SARUFI.T4_NGELI_YA_A_WA.A_WA', 'Gives animals the prefix of things (ndege inaruka) instead of A-WA (ndege wanaruka).', '{"question":"Ndege watatu ___naruka juu.","wrong_answer":"zi","correct_answer":"wa"}'::jsonb, 'The child thinks only people are in A-WA.', 'Animals, birds and insects.', 'Is it alive and moving? People and animals take a- and wa-.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T4_NGELI_YA_A_WA.A_WA.M4_AWA_NOT', 'KISW.G4.SARUFI.T4_NGELI_YA_A_WA.A_WA', 'Puts a thing into A-WA (kitabu anasomwa).', '{"question":"Ni nomino ipi ni ya ngeli ya A-WA?","wrong_answer":"kitabu","correct_answer":"mwalimu"}'::jsonb, 'The child picks a noun that begins with m- or a vowel and does not ask if it is a person or an animal.', 'A person among things.', 'Is it a person or an animal?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T4_NGELI_YA_A_WA.A_WA.M4_AWA_PLNOUN', 'KISW.G4.SARUFI.T4_NGELI_YA_A_WA.A_WA', 'Makes a wrong plural noun for a person (vitoto, mitoto for watoto).', '{"question":"Mtoto mmoja, ___ wawili.","wrong_answer":"vitoto","correct_answer":"watoto"}'::jsonb, 'The child puts on a prefix from another class.', 'Singular and plural nouns of people.', 'Which prefix do people take for many?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSIKI.T5_METHALI.METHALI.M4_MET_LITERAL', 'KISW.G4.KUSIKI.T5_METHALI.METHALI', 'Takes the methali word for word.', '{"question":"Methali \"Samaki mkunje angali mbichi\" ina maana gani?","wrong_answer":"Samaki hukunjwa akiwa mbichi","correct_answer":"Mtoto afundishwe angali mdogo"}'::jsonb, 'The child reads the words and not the meaning.', 'A literal meaning as an option.', 'What lesson is the saying giving us?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSIKI.T5_METHALI.METHALI.M4_MET_OTHER', 'KISW.G4.KUSIKI.T5_METHALI.METHALI', 'Gives the meaning of another methali.', '{"question":"Methali \"Mtoto umleavyo ndivyo akuavyo\" ina maana gani?","wrong_answer":"Mtoto afundishwe angali mdogo","correct_answer":"Tabia ya mtoto hutokana na malezi yake"}'::jsonb, 'The child knows the topic but mixes the sayings.', 'Meanings of two methali on the same topic.', 'Which part of the saying does the meaning explain?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSIKI.T5_METHALI.METHALI.M4_MET_NOT', 'KISW.G4.KUSIKI.T5_METHALI.METHALI', 'Takes an ordinary sentence or another saying for a methali.', '{"question":"Ni methali ipi?","wrong_answer":"Mtoto alicheza uwanjani","correct_answer":"Heshima si utumwa"}'::jsonb, 'The child does not tell a methali from a plain sentence.', 'A methali among plain sentences.', 'Does it give a lesson in few words?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSIKI.T5_METHALI.METHALI.M4_MET_WORDS', 'KISW.G4.KUSIKI.T5_METHALI.METHALI', 'Changes a word of the methali, or joins the beginning of one to the end of another.', '{"question":"Samaki mkunje ___ mbichi.","wrong_answer":"akiwa","correct_answer":"angali"}'::jsonb, 'The child remembers the sense but not the exact words.', 'A gap in a methali with plausible words.', 'Say the methali from the beginning.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.SHAIRI.M4_SHA_UBETI_MIX', 'KISW.G4.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.SHAIRI', 'Swaps ubeti (a group of lines) and mshororo (one line).', '{"question":"Mstari mmoja wa shairi huitwa ___.","wrong_answer":"ubeti","correct_answer":"mshororo"}'::jsonb, 'The child knows both words but not which is which.', 'Both words as options.', 'One line, or a group of lines?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.SHAIRI.M4_SHA_COUNT', 'KISW.G4.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.SHAIRI', 'Counts the lines of the whole poem for the lines of one ubeti (or the reverse).', '{"question":"Ubeti wa pili wa shairi hili una mishororo mingapi?","wrong_answer":"12","correct_answer":"4"}'::jsonb, 'The child counts all the lines.', 'A question about one ubeti with the total as an option.', 'Count only the lines of that ubeti.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.SHAIRI.M4_SHA_PARAGRAPH', 'KISW.G4.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.SHAIRI', 'Takes a paragraph for a poem, or a poem for a paragraph.', '{"question":"Ni maandishi yapi ni shairi?","wrong_answer":"Aya moja ndefu inayoendelea hadi mwisho wa ukurasa","correct_answer":"Mistari mifupi iliyopangwa kwa beti"}'::jsonb, 'The child does not look at the shape on the page.', 'A poem and a paragraph described by their shape.', 'How are the lines laid out?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.SHAIRI.M4_SHA_READ_PROSE', 'KISW.G4.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.SHAIRI', 'Reads a poem straight on like a story, with no pause at the end of each line.', '{"question":"Unasoma shairi. Unasimama wapi kidogo?","wrong_answer":"mwisho wa shairi tu","correct_answer":"mwisho wa kila mshororo"}'::jsonb, 'The child reads every text the same way.', 'The question "Unasoma shairi. Unasimama wapi kidogo?" with "mwisho wa shairi tu" among the options.', 'Clap the end of each mshororo while reading together.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T5_INSHA_YA_MAELEZO.INSHA_MAELEZO.M4_INS_STORY_T5', 'KISW.G4.KUANDI.T5_INSHA_YA_MAELEZO.INSHA_MAELEZO', 'Tells a story of what happened where the insha should explain or describe.', '{"question":"Ni sentensi ipi inafaa katika insha ya maelezo kuhusu \"Jinsi ya Kumsaidia Rafiki Mwenye Huzuni\"?","wrong_answer":"Siku moja tulienda sokoni tukapotea.","correct_answer":"Kwanza, msikilize kwa makini bila kumcheka."}'::jsonb, 'Stories are the kind of writing the child has done most and he falls back on it.', 'The question "Ni sentensi ipi inafaa katika insha ya maelezo kuhusu "Jinsi ya Kumsaidia Rafiki Mwenye Huzuni"?" with "Siku moja tulienda sokoni tukapotea." among the options.', 'Ask what the reader should know about the topic at the end: what it is, how it works or is done.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T5_INSHA_YA_MAELEZO.INSHA_MAELEZO.M4_INS_DETAIL_T5', 'KISW.G4.KUANDI.T5_INSHA_YA_MAELEZO.INSHA_MAELEZO', 'Describes with empty words (kizuri sana, kibaya) and no detail that makes a picture.', '{"question":"Ni sentensi ipi inajenga picha dhahiri kuhusu \"Jinsi ya Kumsaidia Rafiki Mwenye Huzuni\"?","wrong_answer":"Rafiki ni mtu mzuri.","correct_answer":"Kwanza, msikilize kwa makini bila kumcheka."}'::jsonb, 'The child knows the thing well and assumes the reader sees it too.', 'The question "Ni sentensi ipi inajenga picha dhahiri kuhusu "Jinsi ya Kumsaidia Rafiki Mwenye Huzuni"?" with "Rafiki ni mtu mzuri." among the options.', 'Five senses chart: what do you see, hear, smell, touch, taste? Turn one row into a sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T5_INSHA_YA_MAELEZO.INSHA_MAELEZO.M4_INS_STEPS_T5', 'KISW.G4.KUANDI.T5_INSHA_YA_MAELEZO.INSHA_MAELEZO', 'Gives the steps of how to do something in a mixed-up order.', '{"question":"Ni mpangilio upi unafaa katika maelezo ya \"Jinsi ya Kumsaidia Rafiki Mwenye Huzuni\"?","wrong_answer":"mwambie mtu mzima, mpe ushauri, mfariji, msikilize","correct_answer":"msikilize, mfariji, mpe ushauri, mwambie mtu mzima"}'::jsonb, 'The child remembers the steps as a set, not as a sequence.', 'The question "Ni mpangilio upi unafaa katika maelezo ya "Jinsi ya Kumsaidia Rafiki Mwenye Huzuni"?" with "mwambie mtu mzima, mpe ushauri, mfariji, msikilize" among the options.', 'Act out the steps; number them; write them with kwanza, kisha, mwishowe.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T5_INSHA_YA_MAELEZO.INSHA_MAELEZO.M4_INS_OFFTOPIC_T5', 'KISW.G4.KUANDI.T5_INSHA_YA_MAELEZO.INSHA_MAELEZO', 'Puts in points that are not about the title.', '{"question":"Katika insha ya maelezo yenye anwani \"Jinsi ya Kumsaidia Rafiki Mwenye Huzuni\", ni sentensi ipi haifai?","wrong_answer":"Rafiki yangu ana baiskeli mpya ya rangi ya bluu.","correct_answer":"Kwanza, msikilize kwa makini bila kumcheka."}'::jsonb, 'The child adds whatever he remembers so the insha is long enough.', 'The question "Katika insha ya maelezo yenye anwani "Jinsi ya Kumsaidia Rafiki Mwenye Huzuni", ni sentensi ipi haifai?" with "Rafiki yangu ana baiskeli mpya ya rangi ya bluu." among the options.', 'Read each sentence and ask: does it tell the reader about the title? Cross out the ones that do not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T5_NGELI_YA_U_I.U_I.M4_UI_SG_I', 'KISW.G4.SARUFI.T5_NGELI_YA_U_I.U_I', 'Uses i- with one noun of U-I.', '{"question":"Mti mmoja ___meanguka.","wrong_answer":"i","correct_answer":"u"}'::jsonb, 'The child has fixed i- as the prefix of U-I.', 'One and many in turn.', 'Count: one or many?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T5_NGELI_YA_U_I.U_I.M4_UI_PL_U', 'KISW.G4.SARUFI.T5_NGELI_YA_U_I.U_I', 'Uses u- with many nouns of U-I.', '{"question":"Miti miwili ___meanguka.","wrong_answer":"u","correct_answer":"i"}'::jsonb, 'The child does not look at the number.', 'Plural nouns that begin with mi-.', 'Mi- tells you it is many.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T5_NGELI_YA_U_I.U_I.M4_UI_PEOPLE', 'KISW.G4.SARUFI.T5_NGELI_YA_U_I.U_I', 'Gives a noun of U-I the prefix of people (mti anaanguka).', '{"question":"Mlango mmoja ___mefunguka.","wrong_answer":"a","correct_answer":"u"}'::jsonb, 'The child sees m- and thinks of mtoto and mwalimu.', 'U-I nouns that begin with m- like people nouns.', 'Is it a person? A tree and a door are things.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T5_NGELI_YA_U_I.U_I.M4_UI_NOT', 'KISW.G4.SARUFI.T5_NGELI_YA_U_I.U_I', 'Puts a noun of another class in U-I.', '{"question":"Ni nomino ipi ni ya ngeli ya U-I?","wrong_answer":"mtoto","correct_answer":"mti"}'::jsonb, 'The child sees m- and takes any noun that begins with it.', 'Nouns that begin with m- from different classes.', 'Is it a person or an animal? Then it is A-WA, not U-I.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T5_NGELI_YA_U_I.U_I.M4_UI_PLNOUN', 'KISW.G4.SARUFI.T5_NGELI_YA_U_I.U_I', 'Makes the plural noun with a prefix of another class (mamti, wamlango for miti, milango).', '{"question":"Mti mmoja, ___ miwili.","wrong_answer":"mamti","correct_answer":"miti"}'::jsonb, 'The child puts on a prefix from another class.', 'Nouns of U-I in the plural.', 'm- becomes mi- for things of this class.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSIKI.T6_SHAIRI.SHAIRI_MSAMIATI.M4_SMS_LOOKALIKE', 'KISW.G4.KUSIKI.T6_SHAIRI.SHAIRI_MSAMIATI', 'Picks a word that looks or sounds like the word.', '{"question":"Neno \"taifa\" lina maana gani?","wrong_answer":"nafaka","correct_answer":"nchi na watu wake"}'::jsonb, 'The child goes by the sound.', 'A look-alike word as an option.', 'Say what each word means.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSIKI.T6_SHAIRI.SHAIRI_MSAMIATI.M4_SMS_NEARBY', 'KISW.G4.KUSIKI.T6_SHAIRI.SHAIRI_MSAMIATI', 'Picks a word of the same family of ideas.', '{"question":"Neno \"bendera\" lina maana gani?","wrong_answer":"wimbo wa nchi","correct_answer":"kitambaa chenye rangi kinachoonyesha nchi"}'::jsonb, 'The child picks an idea close to the nation.', 'Another symbol of the nation as an option.', 'What can you see, touch and hoist?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSIKI.T6_SHAIRI.SHAIRI_MSAMIATI.M4_SMS_OPPOSITE', 'KISW.G4.KUSIKI.T6_SHAIRI.SHAIRI_MSAMIATI', 'Picks the opposite.', '{"question":"Neno \"amani\" lina maana gani?","wrong_answer":"vita","correct_answer":"utulivu bila vita"}'::jsonb, 'The child knows the topic but not which way it points.', 'The opposite meaning as an option.', 'Does the word mean the thing is there, or not?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSIKI.T6_SHAIRI.SHAIRI_MSAMIATI.M4_SMS_MESSAGE', 'KISW.G4.KUSIKI.T6_SHAIRI.SHAIRI_MSAMIATI', 'Gives a line of the poem as its message, or says the message is "the flag" (the topic).', '{"question":"Ujumbe wa shairi kuhusu bendera ya taifa ni upi?","wrong_answer":"bendera","correct_answer":"tuipende na kuiheshimu bendera ya nchi yetu"}'::jsonb, 'The topic is the clearest thing in the poem; the child has not been asked what the poet wants.', 'The question "Ujumbe wa shairi kuhusu bendera ya taifa ni upi?" with "bendera" among the options.', 'Ask: what does the poet want us to feel or do about the flag?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T6_KUSOMA_KWA_KINA.MAKALA.M4_MAK_OUTSIDE', 'KISW.G4.KUSOMA.T6_KUSOMA_KWA_KINA.MAKALA', 'Answers from what the child knows, not from the article.', '{"question":"Kwa mujibu wa makala, maji yachemshwe kwa muda gani?","wrong_answer":"dakika tano","correct_answer":"dakika kumi"}'::jsonb, 'The child gives the figure he has heard.', 'A likely figure that the article does not give.', 'Point to the sentence in the article.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T6_KUSOMA_KWA_KINA.MAKALA.M4_MAK_DETAIL_AS_MAIN', 'KISW.G4.KUSOMA.T6_KUSOMA_KWA_KINA.MAKALA', 'Gives a detail for the main message of the article.', '{"question":"Ujumbe mkuu wa makala ni upi?","wrong_answer":"Maji huchemshwa kwa moto.","correct_answer":"Tunapaswa kunywa maji safi na salama."}'::jsonb, 'The child takes one sentence.', 'A detail and a message as options.', 'What is the whole article for?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T6_KUSOMA_KWA_KINA.MAKALA.M4_MAK_DETAIL_MIX', 'KISW.G4.KUSOMA.T6_KUSOMA_KWA_KINA.MAKALA', 'Picks another detail of the article.', '{"question":"Makala inasema maji yawekwe wapi baada ya kuchemshwa?","wrong_answer":"jikoni","correct_answer":"kwenye chombo kilichofunikwa"}'::jsonb, 'The child picks a detail from the right place, not the one asked.', 'Several details from one paragraph.', 'Read the question word again.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T6_KUSOMA_KWA_KINA.MAKALA.M4_MAK_TITLE', 'KISW.G4.KUSOMA.T6_KUSOMA_KWA_KINA.MAKALA', 'Gives the title of the article as its message.', '{"question":"Makala \"Bendera Yetu\" yana ujumbe upi?","wrong_answer":"Bendera Yetu","correct_answer":"tuiheshimu bendera kwa sababu inawakilisha nchi yetu"}'::jsonb, 'The title is the only sentence about the whole article the child is sure of.', 'The question "Makala "Bendera Yetu" yana ujumbe upi?" with "Bendera Yetu" among the options.', 'Ask what the writer wants the reader to know or do after reading.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T6_INSHA_YA_WASIFU.INSHA_WASIFU.M4_INS_STORY_T6', 'KISW.G4.KUANDI.T6_INSHA_YA_WASIFU.INSHA_WASIFU', 'Tells a story of what happened where the insha should describe the person, place or thing.', '{"question":"Ni sentensi ipi inafaa katika insha ya wasifu kuhusu \"Bendera ya Taifa Letu\"?","wrong_answer":"Siku moja tulienda sokoni tukapotea.","correct_answer":"Bendera yetu ina rangi nne: nyeusi, nyekundu, kijani na nyeupe."}'::jsonb, 'Stories are the kind of writing the child has done most and he falls back on it.', 'The question "Ni sentensi ipi inafaa katika insha ya wasifu kuhusu "Bendera ya Taifa Letu"?" with "Siku moja tulienda sokoni tukapotea." among the options.', 'Ask what the reader should know about the topic at the end: what it looks like, what it is for.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T6_INSHA_YA_WASIFU.INSHA_WASIFU.M4_INS_DETAIL_T6', 'KISW.G4.KUANDI.T6_INSHA_YA_WASIFU.INSHA_WASIFU', 'Describes with empty words (kizuri sana, kibaya) and no detail that makes a picture.', '{"question":"Ni sentensi ipi inajenga picha dhahiri kuhusu \"Bendera ya Taifa Letu\"?","wrong_answer":"Bendera yetu ni nzuri.","correct_answer":"Bendera yetu ina rangi nne: nyeusi, nyekundu, kijani na nyeupe."}'::jsonb, 'The child knows the thing well and assumes the reader sees it too.', 'The question "Ni sentensi ipi inajenga picha dhahiri kuhusu "Bendera ya Taifa Letu"?" with "Bendera yetu ni nzuri." among the options.', 'Five senses chart: what do you see, hear, smell, touch, taste? Turn one row into a sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T6_INSHA_YA_WASIFU.INSHA_WASIFU.M4_INS_AGREE_T6', 'KISW.G4.KUANDI.T6_INSHA_YA_WASIFU.INSHA_WASIFU', 'Uses a describing word that does not agree with its noun (bendera mzuri, miti mrefu).', '{"question":"Ni sentensi ipi ni sahihi?","wrong_answer":"Bendera yetu ni mzuri sana.","correct_answer":"Bendera yetu ni nzuri sana."}'::jsonb, 'The child uses one form of the adjective (m-) for every noun, as he hears it for people.', 'The question "Ni sentensi ipi ni sahihi?" with "Bendera yetu ni mzuri sana." among the options.', 'Find the noun first, then its ngeli, then the prefix of the adjective.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T6_INSHA_YA_WASIFU.INSHA_WASIFU.M4_INS_OFFTOPIC_T6', 'KISW.G4.KUANDI.T6_INSHA_YA_WASIFU.INSHA_WASIFU', 'Puts in points that are not about the title.', '{"question":"Katika insha ya wasifu yenye anwani \"Bendera ya Taifa Letu\", ni sentensi ipi haifai?","wrong_answer":"Rafiki yangu ana baiskeli mpya ya rangi ya bluu.","correct_answer":"Bendera yetu ina rangi nne: nyeusi, nyekundu, kijani na nyeupe."}'::jsonb, 'The child adds whatever he remembers so the insha is long enough.', 'The question "Katika insha ya wasifu yenye anwani "Bendera ya Taifa Letu", ni sentensi ipi haifai?" with "Rafiki yangu ana baiskeli mpya ya rangi ya bluu." among the options.', 'Read each sentence and ask: does it tell the reader about the title? Cross out the ones that do not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T6_NGELI_YA_LI_YA.LI_YA.M4_LIYA_SG_YA', 'KISW.G4.SARUFI.T6_NGELI_YA_LI_YA.LI_YA', 'Uses ya- with one noun of LI-YA.', '{"question":"Jiwe moja ___meanguka.","wrong_answer":"ya","correct_answer":"li"}'::jsonb, 'The child has fixed ya- as the prefix of LI-YA.', 'One and many in turn.', 'Count: one or many?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T6_NGELI_YA_LI_YA.LI_YA.M4_LIYA_PL_LI', 'KISW.G4.SARUFI.T6_NGELI_YA_LI_YA.LI_YA', 'Uses li- with many nouns of LI-YA.', '{"question":"Mawe mawili ___meanguka.","wrong_answer":"li","correct_answer":"ya"}'::jsonb, 'The child does not see that ma- tells it is many.', 'Plural nouns that begin with ma-.', 'Ma- tells you it is many.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T6_NGELI_YA_LI_YA.LI_YA.M4_LIYA_PLNOUN', 'KISW.G4.SARUFI.T6_NGELI_YA_LI_YA.LI_YA', 'Makes the plural with the wrong form (majiwe, majicho for mawe, macho).', '{"question":"Jicho moja, ___ mawili.","wrong_answer":"majicho","correct_answer":"macho"}'::jsonb, 'The child adds ma- and keeps ji-.', 'Nouns that begin with ji-.', 'ji- becomes ma-: jiwe-mawe, jicho-macho.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T6_NGELI_YA_LI_YA.LI_YA.M4_LIYA_NOT', 'KISW.G4.SARUFI.T6_NGELI_YA_LI_YA.LI_YA', 'Puts a noun of another class in LI-YA.', '{"question":"Ni nomino ipi ni ya ngeli ya LI-YA?","wrong_answer":"kiti","correct_answer":"jiwe"}'::jsonb, 'The child goes by the first letters only.', 'Nouns from other classes with a look-alike beginning.', 'Does it form its plural with ma-?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T6_NGELI_YA_LI_YA.LI_YA.M4_LIYA_OTHER', 'KISW.G4.SARUFI.T6_NGELI_YA_LI_YA.LI_YA', 'Gives a noun of LI-YA the prefix of another class (kimeanguka for limeanguka).', '{"question":"Jiwe moja ___meanguka.","wrong_answer":"ki","correct_answer":"li"}'::jsonb, 'The child does not tell which class the noun belongs to.', 'Several prefixes as options.', 'Which class has the plural with ma-? Its prefixes are li- and ya-.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSIKI.T7_NAHAU.NAHAU.M4_NAH_LITERAL', 'KISW.G4.KUSIKI.T7_NAHAU.NAHAU', 'Takes the nahau word for word.', '{"question":"Nahau \"kupiga moyo konde\" ina maana gani?","wrong_answer":"kupiga moyo kwa fimbo","correct_answer":"kuwa jasiri na kuvumilia"}'::jsonb, 'The child reads the words and not the meaning.', 'A literal meaning as an option.', 'Can the words mean what they say?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSIKI.T7_NAHAU.NAHAU.M4_NAH_OTHER', 'KISW.G4.KUSIKI.T7_NAHAU.NAHAU', 'Gives the meaning of another nahau.', '{"question":"Nahau \"kula kiapo\" ina maana gani?","wrong_answer":"kuvumilia shida","correct_answer":"kuapa kusema ukweli"}'::jsonb, 'The child knows the topic but mixes the phrases.', 'Meanings of two nahau on the same topic.', 'Which words of the phrase does the meaning explain?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSIKI.T7_NAHAU.NAHAU.M4_NAH_NOT', 'KISW.G4.KUSIKI.T7_NAHAU.NAHAU', 'Takes a methali or an ordinary phrase for a nahau.', '{"question":"Ni nahau ipi?","wrong_answer":"Haba na haba hujaza kibaba","correct_answer":"kukata tamaa"}'::jsonb, 'The child does not tell a nahau from a methali.', 'A nahau among methali and phrases.', 'Is it a short phrase that is not a whole saying with a lesson?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSIKI.T7_NAHAU.NAHAU.M4_NAH_WORDS', 'KISW.G4.KUSIKI.T7_NAHAU.NAHAU', 'Changes a word of the nahau (kupiga moyo kubwa for kupiga moyo konde).', '{"question":"Alipiga moyo ___ akaendelea kusoma.","wrong_answer":"kubwa","correct_answer":"konde"}'::jsonb, 'The child remembers the sense but not the exact words.', 'A gap in a nahau with plausible words.', 'Which word goes with the others in this phrase?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T7_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M4_MAP_COVER_T7', 'KISW.G4.KUSOMA.T7_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Chooses a book by its cover picture or its thickness only.', '{"question":"Unataka kusoma kuhusu matunda na mimea. Utachaguaje kitabu?","wrong_answer":"kwa picha nzuri ya jalada","correct_answer":"kwa kusoma anwani, maelezo ya nyuma na ukurasa wa kwanza"}'::jsonb, 'Nobody has shown the child the title, the blurb and the first page as clues.', 'The question "Unataka kusoma kuhusu matunda na mimea. Utachaguaje kitabu?" with "kwa picha nzuri ya jalada" among the options.', 'Hold up two books; read the title and the back of each aloud; the child chooses and says which clue decided it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T7_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M4_MAP_LEVEL_T7', 'KISW.G4.KUSOMA.T7_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Chooses a text far above his reading level and gives up after a page.', '{"question":"Ukisoma ukurasa wa kwanza wa \"Mti wa Mwembe wa Bibi\" na hujui maneno mengi sana, ufanye nini?","wrong_answer":"endelea tu hata kama huelewi","correct_answer":"chagua matini nyingine iliyo ya kiwango chako"}'::jsonb, 'The child thinks a harder book is a better book, or chooses the book a friend chose.', 'The question "Ukisoma ukurasa wa kwanza wa "Mti wa Mwembe wa Bibi" na hujui maneno mengi sana, ufanye nini?" with "endelea tu hata kama huelewi" among the options.', 'The five-finger check: on one page, a finger for each unknown word; five fingers means the book is too hard for now.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T7_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M4_MAP_TITLEMSG_T7', 'KISW.G4.KUSOMA.T7_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Gives the title as the message of the text.', '{"question":"Ujumbe wa matini \"Mti wa Mwembe wa Bibi\" ni upi?","wrong_answer":"Mti wa Mwembe wa Bibi","correct_answer":"Tukipanda na kutunza miti, itatufaa sisi na watoto wetu."}'::jsonb, 'The title is the only sentence about the whole text that the child is sure of.', 'The question "Ujumbe wa matini "Mti wa Mwembe wa Bibi" ni upi?" with "Mti wa Mwembe wa Bibi" among the options.', 'Ask what the writer wants the reader to learn or do; the title only names the topic.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T7_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M4_MAP_DETAIL_T7', 'KISW.G4.KUSOMA.T7_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Gives one detail of the text as its message.', '{"question":"Ni ipi ni ujumbe wa matini kuhusu matunda na mimea?","wrong_answer":"Bibi alipanda mwembe miaka mingi iliyopita.","correct_answer":"Tukipanda na kutunza miti, itatufaa sisi na watoto wetu."}'::jsonb, 'The detail was striking and is remembered; the child has not asked what the whole text is about.', 'The question "Ni ipi ni ujumbe wa matini kuhusu matunda na mimea?" with "Bibi alipanda mwembe miaka mingi iliyopita." among the options.', 'Two boxes: "ujumbe" (one) and "maelezo" (many); the child sorts sentences from the text.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T7_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M4_MAP_KIND_T7', 'KISW.G4.KUSOMA.T7_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Does not tell one kind of text from another (takes a newspaper report for a story, or a poem for a story).', '{"question":"Matini yenye beti na mishororo ni ya aina gani?","wrong_answer":"hadithi","correct_answer":"shairi"}'::jsonb, 'The child has met most texts as "kitabu" and has not been shown the signs of each kind.', 'The question "Matini yenye beti na mishororo ni ya aina gani?" with "hadithi" among the options.', 'Lay out a story, a poem, a newspaper page and a dictionary; the child names one sign of each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T7_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M4_MAP_WORD_T7', 'KISW.G4.KUSOMA.T7_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Guesses a new word from how it looks, not from the sentence it is in (kivuli).', '{"question":"Katika matini: \"Watoto walikaa chini ya kivuli cha mwembe wakati wa jua kali.\" Neno \"kivuli\" lina maana gani?","wrong_answer":"kivuko cha mto","correct_answer":"mahali pasipo na jua chini ya mti"}'::jsonb, 'The child matches the word to a word it looks like instead of reading the sentence around it.', 'The question "Katika matini: "Watoto walikaa chini ya kivuli cha mwembe wakati wa jua kali." Neno "kivuli" lina maana gani?" with "kivuko cha mto" among the options.', 'Cover the word; the child reads the sentence and says what word would fit; then compares.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T7_INSHA_YA_MAELEZO.INSHA_MAELEZO.M4_INS_STORY_T7', 'KISW.G4.KUANDI.T7_INSHA_YA_MAELEZO.INSHA_MAELEZO', 'Tells a story of what happened where the insha should explain or describe.', '{"question":"Ni sentensi ipi inafaa katika insha ya maelezo kuhusu \"Jinsi ya Kupanda Mti\"?","wrong_answer":"Siku moja tulienda sokoni tukapotea.","correct_answer":"Kwanza, chimba shimo lenye kina cha futi mbili."}'::jsonb, 'Stories are the kind of writing the child has done most and he falls back on it.', 'The question "Ni sentensi ipi inafaa katika insha ya maelezo kuhusu "Jinsi ya Kupanda Mti"?" with "Siku moja tulienda sokoni tukapotea." among the options.', 'Ask what the reader should know about the topic at the end: what it is, how it works or is done.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T7_INSHA_YA_MAELEZO.INSHA_MAELEZO.M4_INS_DETAIL_T7', 'KISW.G4.KUANDI.T7_INSHA_YA_MAELEZO.INSHA_MAELEZO', 'Describes with empty words (kizuri sana, kibaya) and no detail that makes a picture.', '{"question":"Ni sentensi ipi inajenga picha dhahiri kuhusu \"Jinsi ya Kupanda Mti\"?","wrong_answer":"Miti ni mizuri.","correct_answer":"Kwanza, chimba shimo lenye kina cha futi mbili."}'::jsonb, 'The child knows the thing well and assumes the reader sees it too.', 'The question "Ni sentensi ipi inajenga picha dhahiri kuhusu "Jinsi ya Kupanda Mti"?" with "Miti ni mizuri." among the options.', 'Five senses chart: what do you see, hear, smell, touch, taste? Turn one row into a sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T7_INSHA_YA_MAELEZO.INSHA_MAELEZO.M4_INS_STEPS_T7', 'KISW.G4.KUANDI.T7_INSHA_YA_MAELEZO.INSHA_MAELEZO', 'Gives the steps of how to do something in a mixed-up order.', '{"question":"Ni mpangilio upi unafaa katika maelezo ya \"Jinsi ya Kupanda Mti\"?","wrong_answer":"mwagilia maji, funika kwa udongo, weka mche, chimba shimo","correct_answer":"chimba shimo, weka mche, funika kwa udongo, mwagilia maji"}'::jsonb, 'The child remembers the steps as a set, not as a sequence.', 'The question "Ni mpangilio upi unafaa katika maelezo ya "Jinsi ya Kupanda Mti"?" with "mwagilia maji, funika kwa udongo, weka mche, chimba shimo" among the options.', 'Act out the steps; number them; write them with kwanza, kisha, mwishowe.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T7_INSHA_YA_MAELEZO.INSHA_MAELEZO.M4_INS_OFFTOPIC_T7', 'KISW.G4.KUANDI.T7_INSHA_YA_MAELEZO.INSHA_MAELEZO', 'Puts in points that are not about the title.', '{"question":"Katika insha ya maelezo yenye anwani \"Jinsi ya Kupanda Mti\", ni sentensi ipi haifai?","wrong_answer":"Rafiki yangu ana baiskeli mpya ya rangi ya bluu.","correct_answer":"Kwanza, chimba shimo lenye kina cha futi mbili."}'::jsonb, 'The child adds whatever he remembers so the insha is long enough.', 'The question "Katika insha ya maelezo yenye anwani "Jinsi ya Kupanda Mti", ni sentensi ipi haifai?" with "Rafiki yangu ana baiskeli mpya ya rangi ya bluu." among the options.', 'Read each sentence and ask: does it tell the reader about the title? Cross out the ones that do not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T7_NGELI_YA_KI_VI.KI_VI.M4_KIVI_SG_VI', 'KISW.G4.SARUFI.T7_NGELI_YA_KI_VI.KI_VI', 'Uses vi- with one noun of KI-VI.', '{"question":"Kiti kimoja ___meanguka.","wrong_answer":"vi","correct_answer":"ki"}'::jsonb, 'The child has fixed vi- as the prefix of KI-VI.', 'One and many in turn.', 'Count: one or many?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T7_NGELI_YA_KI_VI.KI_VI.M4_KIVI_PL_KI', 'KISW.G4.SARUFI.T7_NGELI_YA_KI_VI.KI_VI', 'Uses ki- with many nouns of KI-VI.', '{"question":"Viti viwili ___meanguka.","wrong_answer":"ki","correct_answer":"vi"}'::jsonb, 'The child does not see that the noun is plural.', 'Plural nouns that begin with vi-.', 'Vi- tells you it is many.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T7_NGELI_YA_KI_VI.KI_VI.M4_KIVI_PLNOUN', 'KISW.G4.SARUFI.T7_NGELI_YA_KI_VI.KI_VI', 'Makes the plural noun by adding a prefix and keeping ki- (vikitabu, vikiatu).', '{"question":"Kitabu kimoja, ___ viwili.","wrong_answer":"vikitabu","correct_answer":"vitabu"}'::jsonb, 'The child adds vi- in front and does not drop ki-.', 'Nouns of KI-VI in the plural.', 'ki- is replaced by vi-, not added to.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T7_NGELI_YA_KI_VI.KI_VI.M4_KIVI_NOT', 'KISW.G4.SARUFI.T7_NGELI_YA_KI_VI.KI_VI', 'Puts a noun of another class in KI-VI.', '{"question":"Ni nomino ipi ni ya ngeli ya KI-VI?","wrong_answer":"jiwe","correct_answer":"kikombe"}'::jsonb, 'The child sees a k in the word and thinks of ki-.', 'Nouns of other classes with a k in them.', 'Does the noun begin with ki-, and is its plural vi-?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T7_NGELI_YA_KI_VI.KI_VI.M4_KIVI_OTHER', 'KISW.G4.SARUFI.T7_NGELI_YA_KI_VI.KI_VI', 'Gives a noun of KI-VI the prefix of another class (limeanguka for kimeanguka).', '{"question":"Kiti kimoja ___meanguka.","wrong_answer":"li","correct_answer":"ki"}'::jsonb, 'The child does not tell which class the noun belongs to.', 'Several prefixes as options.', 'The noun begins with ki- or vi-. Its prefixes are ki- and vi-.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T7_NGELI_YA_LI_LI.LI_LI.M4_LILI_YA', 'KISW.G4.SARUFI.T7_NGELI_YA_LI_LI.LI_LI', 'Uses ya- with jua or giza because of the ma- plural of LI-YA.', '{"question":"Jua ___metoka asubuhi.","wrong_answer":"ya","correct_answer":"li"}'::jsonb, 'The child carries the LI-YA rule over to nouns that do not change.', 'The nouns jua and giza in turn.', 'The noun does not change. What does the sentence tell you?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T7_NGELI_YA_LI_LI.LI_LI.M4_LILI_OTHER', 'KISW.G4.SARUFI.T7_NGELI_YA_LI_LI.LI_LI', 'Gives jua or giza the prefix of another class (u- or i-).', '{"question":"Giza ___meingia haraka.","wrong_answer":"u","correct_answer":"li"}'::jsonb, 'The child hears jua or giza as a thing of the U-I class.', 'Jua and giza with several prefixes.', 'Which class does the design put jua and giza in?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T7_NGELI_YA_LI_LI.LI_LI.M4_LILI_NOT', 'KISW.G4.SARUFI.T7_NGELI_YA_LI_LI.LI_LI', 'Puts a noun of another class in LI-LI.', '{"question":"Ni nomino ipi ni ya ngeli ya LI-LI?","wrong_answer":"mti","correct_answer":"jua"}'::jsonb, 'The child has few examples of LI-LI to compare.', 'Jua or giza among nouns of other classes.', 'Which of them is in the class the design names?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T7_NGELI_YA_LI_LI.LI_LI.M4_LILI_PLURAL', 'KISW.G4.SARUFI.T7_NGELI_YA_LI_LI.LI_LI', 'Makes a plural for a noun of LI-LI (majua, magiza).', '{"question":"Wingi wa \"jua\" katika \"Jua limewaka\" ni upi?","wrong_answer":"majua","correct_answer":"jua (halibadiliki)"}'::jsonb, 'Most li- nouns the child knows (jiwe/mawe) have a ma- plural.', 'The question "Wingi wa "jua" katika "Jua limewaka" ni upi?" with "majua" among the options.', 'Show that there is only one sun: the noun and its prefix stay li- in both.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSIKI.T8_VISAWE.VISAWE.M4_VIS_OPPOSITE', 'KISW.G4.KUSIKI.T8_VISAWE.VISAWE', 'Picks the opposite.', '{"question":"Kisawe cha \"furaha\" ni ___.","wrong_answer":"huzuni","correct_answer":"raha"}'::jsonb, 'The child knows the topic but not which way it points.', 'The opposite as an option.', 'Same meaning, or opposite?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSIKI.T8_VISAWE.VISAWE.M4_VIS_LOOKALIKE', 'KISW.G4.KUSIKI.T8_VISAWE.VISAWE', 'Picks a word that looks or sounds like the word.', '{"question":"Kisawe cha \"haraka\" ni ___.","wrong_answer":"harufu","correct_answer":"upesi"}'::jsonb, 'The child goes by the first letters.', 'A look-alike word as an option.', 'Say what each word means.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSIKI.T8_VISAWE.VISAWE.M4_VIS_RELATED', 'KISW.G4.KUSIKI.T8_VISAWE.VISAWE', 'Picks a related word that is not the same in meaning.', '{"question":"Kisawe cha \"tajiri\" ni ___.","wrong_answer":"mfanyabiashara","correct_answer":"mkwasi"}'::jsonb, 'The child picks a word that goes with the idea.', 'A related word as an option.', 'Can you put it in place of the word, with the same meaning?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSIKI.T8_VISAWE.VISAWE.M4_VIS_WRONG_KIND', 'KISW.G4.KUSIKI.T8_VISAWE.VISAWE', 'Gives a synonym of another kind of word (a verb for a noun: nyumba - kuishi).', '{"question":"Kisawe cha \"nyumba\" ni kipi?","wrong_answer":"kuishi","correct_answer":"makazi"}'::jsonb, 'The child links the words by an idea (a house is where you live), not by meaning.', 'The question "Kisawe cha "nyumba" ni kipi?" with "kuishi" among the options.', 'Check the synonym can stand in the same sentence in place of the word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T8_KUSOMA_KWA_UFAHAMU.IGIZO.M4_IGI_STORY', 'KISW.G4.KUSOMA.T8_KUSOMA_KWA_UFAHAMU.IGIZO', 'Takes a line of a story for a line of a play (or the reverse).', '{"question":"Ni kipi kati ya hivi kinatoka kwenye mchezo wa kuigiza?","wrong_answer":"Juma aliingia dukani na kusalimia.","correct_answer":"Juma: Hujambo, mzee?"}'::jsonb, 'The child does not see the name and the colon.', 'A play line and a story line side by side.', 'Does the line begin with a name and a colon?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T8_KUSOMA_KWA_UFAHAMU.IGIZO.M4_IGI_DIRECTION', 'KISW.G4.KUSOMA.T8_KUSOMA_KWA_UFAHAMU.IGIZO', 'Takes the words in brackets for words that are said.', '{"question":"Ni maelekezo ya jukwaani yapi?","wrong_answer":"Hujambo, mzee?","correct_answer":"(anaingia dukani)"}'::jsonb, 'The child reads everything on the page as speech.', 'A stage direction among spoken lines.', 'What does the actor do, and what does he say?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T8_KUSOMA_KWA_UFAHAMU.IGIZO.M4_IGI_WRONG_SPEAKER', 'KISW.G4.KUSOMA.T8_KUSOMA_KWA_UFAHAMU.IGIZO', 'Names the wrong speaker of a line.', '{"question":"Nani alisema, \"Nipe kilo mbili za unga\"?","wrong_answer":"Mzee Juma","correct_answer":"Atieno"}'::jsonb, 'The child goes by the name closest to the line.', 'A line next to the name of another speaker.', 'The name before the colon is the speaker.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T8_KUSOMA_KWA_UFAHAMU.IGIZO.M4_IGI_OUTSIDE', 'KISW.G4.KUSOMA.T8_KUSOMA_KWA_UFAHAMU.IGIZO', 'Answers from what the child knows, not from the play.', '{"question":"Atieno alinunua nini dukani?","wrong_answer":"sukari","correct_answer":"unga"}'::jsonb, 'The child gives a likely answer and does not look in the play.', 'A likely answer that the play does not give.', 'Point to the line in the play that says it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T8_INSHA_YA_MASIMULIZI.INSHA_MASIMULIZI.M4_INS_FACTS_T8', 'KISW.G4.KUANDI.T8_INSHA_YA_MASIMULIZI.INSHA_MASIMULIZI', 'Writes facts or an explanation where a story of events is asked.', '{"question":"Ni sentensi ipi ni mwanzo wa insha ya masimulizi yenye anwani \"Safari ya Mbuga ya Wanyama\"?","wrong_answer":"Twiga ni mnyama mrefu kuliko wanyama wote.","correct_answer":"Tuliona twiga wakila majani ya mti mrefu."}'::jsonb, 'The child knows a lot about the topic and writes what he knows instead of telling what happened.', 'The question "Ni sentensi ipi ni mwanzo wa insha ya masimulizi yenye anwani "Safari ya Mbuga ya Wanyama"?" with "Twiga ni mnyama mrefu kuliko wanyama wote." among the options.', 'Ask: who, where, what happened first, then, in the end? A story answers these; an explanation does not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T8_INSHA_YA_MASIMULIZI.INSHA_MASIMULIZI.M4_INS_TENSE_T8', 'KISW.G4.KUANDI.T8_INSHA_YA_MASIMULIZI.INSHA_MASIMULIZI', 'Tells a past story in the present tense (-na-), or mixes -na- and -li- in one story.', '{"question":"Ni sentensi ipi inafaa katika masimulizi ya jambo lililotokea jana: \"Safari ya Mbuga ya Wanyama\"?","wrong_answer":"Tunaona twiga wakila majani ya mti mrefu.","correct_answer":"Tuliona twiga wakila majani ya mti mrefu."}'::jsonb, 'The child writes as he speaks while remembering, and English stories in class are told in the present too.', 'The question "Ni sentensi ipi inafaa katika masimulizi ya jambo lililotokea jana: "Safari ya Mbuga ya Wanyama"?" with "Tunaona twiga wakila majani ya mti mrefu." among the options.', 'Circle every verb; check its tense marker against the time words (jana, siku moja).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T8_INSHA_YA_MASIMULIZI.INSHA_MASIMULIZI.M4_INS_ORDER_T8', 'KISW.G4.KUANDI.T8_INSHA_YA_MASIMULIZI.INSHA_MASIMULIZI', 'Puts the events in an order that cannot have happened (the end before the start), with no linking words.', '{"question":"Ni mpangilio upi wa matukio unafaa katika insha \"Safari ya Mbuga ya Wanyama\"?","wrong_answer":"tulirudi jioni, tuliona wanyama, tulifika mbugani, tuliondoka shuleni","correct_answer":"tuliondoka shuleni, tulifika mbugani, tuliona wanyama, tulirudi jioni"}'::jsonb, 'The child writes events as they come to mind; nobody has asked for a plan first.', 'The question "Ni mpangilio upi wa matukio unafaa katika insha "Safari ya Mbuga ya Wanyama"?" with "tulirudi jioni, tuliona wanyama, tulifika mbugani, tuliondoka shuleni" among the options.', 'Plan with three boxes (mwanzo, kati, mwisho) and linking words (kwanza, kisha, hatimaye) before writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T8_INSHA_YA_MASIMULIZI.INSHA_MASIMULIZI.M4_INS_END_T8', 'KISW.G4.KUANDI.T8_INSHA_YA_MASIMULIZI.INSHA_MASIMULIZI', 'Ends the insha abruptly ("Mwisho." or "The end") with no closing paragraph (hitimisho).', '{"question":"Ni ipi ni hitimisho bora la insha \"Safari ya Mbuga ya Wanyama\"?","wrong_answer":"Mwisho.","correct_answer":"Tangu siku hiyo, nimejifunza kuwa mwangalifu kila wakati."}'::jsonb, 'Storybooks for young readers end with "Mwisho" and the child copies that.', 'The question "Ni ipi ni hitimisho bora la insha "Safari ya Mbuga ya Wanyama"?" with "Mwisho." among the options.', 'Show three endings; the child picks the one that closes the main idea or the lesson.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T8_MNYAMBULIKO_WA_VITEN.MNYAMBULIKO.M4_MNY_NO_FOR', 'KISW.G4.SARUFI.T8_MNYAMBULIKO_WA_VITEN.MNYAMBULIKO', 'Leaves the verb in its base form where someone is helped (anaandika for anamwandikia).', '{"question":"Mwalimu ___ wanafunzi barua.","wrong_answer":"anaandika","correct_answer":"anawaandikia"}'::jsonb, 'The child does not see that the verb has to show for whom.', 'A sentence with a person who benefits.', 'Is it done for someone? Then the verb ends in -ia or -ea.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T8_MNYAMBULIKO_WA_VITEN.MNYAMBULIKO.M4_MNY_NO_BY', 'KISW.G4.SARUFI.T8_MNYAMBULIKO_WA_VITEN.MNYAMBULIKO', 'Leaves the verb active where the thing is done to (barua imeandika na mwalimu).', '{"question":"Barua ___ na mwalimu.","wrong_answer":"imeandika","correct_answer":"imeandikwa"}'::jsonb, 'The child does not see that the thing, not the person, is the subject.', 'A sentence that begins with the thing that was done.', 'Does the thing do it, or is it done to the thing? Then -wa.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T8_MNYAMBULIKO_WA_VITEN.MNYAMBULIKO.M4_MNY_MIX', 'KISW.G4.SARUFI.T8_MNYAMBULIKO_WA_VITEN.MNYAMBULIKO', 'Mixes -ia (for someone) and -wa (done to the thing).', '{"question":"Hadithi ___ na watoto wote.","wrong_answer":"inasomea","correct_answer":"inasomwa"}'::jsonb, 'The endings look alike and the child does not ask what the verb says.', 'Sentences that need -wa or -ia in turn.', 'Ask: for someone, or done to the thing?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T8_MNYAMBULIKO_WA_VITEN.MNYAMBULIKO.M4_MNY_WA_AGENT', 'KISW.G4.SARUFI.T8_MNYAMBULIKO_WA_VITEN.MNYAMBULIKO', 'Uses na wrongly or leaves out "na" before the doer in the passive (Barua imeandikwa mwalimu).', '{"question":"Jaza: Barua imeandikwa ___ mwalimu.","wrong_answer":"kwa","correct_answer":"na"}'::jsonb, 'In English the doer follows "by", which the child links to kwa.', 'The question "Jaza: Barua imeandikwa ___ mwalimu." with "kwa" among the options.', 'The doer of a -wa verb is introduced with na: imeandikwa na mwalimu.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSIKI.T9_MAZUNGUMZO_YA_KIMUKT.MAZUNGUMZO.M4_MAZ_FORMAL', 'KISW.G4.KUSIKI.T9_MAZUNGUMZO_YA_KIMUKT.MAZUNGUMZO', 'Takes a formal setting for an informal one.', '{"question":"Ni mazungumzo yapi si rasmi?","wrong_answer":"hotuba ya mwalimu mkuu kwenye gwaride","correct_answer":"mazungumzo na rafiki uwanjani"}'::jsonb, 'The child does not ask who is talking to whom.', 'A speech or an interview among settings with a friend.', 'Who is speaking to whom, and where?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSIKI.T9_MAZUNGUMZO_YA_KIMUKT.MAZUNGUMZO.M4_MAZ_REGISTER', 'KISW.G4.KUSIKI.T9_MAZUNGUMZO_YA_KIMUKT.MAZUNGUMZO', 'Uses words of the wrong kind of setting (a speech greeting to a friend at play).', '{"question":"Unamsalimia rafiki yako uwanjani. Utasema ___.","wrong_answer":"Mabibi na mabwana, hamjambo?","correct_answer":"Mambo vipi?"}'::jsonb, 'The child has one way of speaking for every place.', 'A formal greeting for a friend.', 'Would you say it to a friend at play?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSIKI.T9_MAZUNGUMZO_YA_KIMUKT.MAZUNGUMZO.M4_MAZ_SHENG_HOME', 'KISW.G4.KUSIKI.T9_MAZUNGUMZO_YA_KIMUKT.MAZUNGUMZO', 'Uses Sheng or street words to an elder at home (Mambo vipi, mzee?).', '{"question":"Unamsalimu babu yako nyumbani. Unasema?","wrong_answer":"Mambo vipi, mzee?","correct_answer":"Shikamoo babu!"}'::jsonb, 'The informal talk of friends is the informal talk the child knows; he does not see that home with elders needs respect even when it is not official.', 'The question "Unamsalimu babu yako nyumbani. Unasema?" with "Mambo vipi, mzee?" among the options.', 'Sort sentences into three settings: with friends, with family elders, in official places.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSIKI.T9_MAZUNGUMZO_YA_KIMUKT.MAZUNGUMZO.M4_MAZ_TURN', 'KISW.G4.KUSIKI.T9_MAZUNGUMZO_YA_KIMUKT.MAZUNGUMZO', 'Talks over others and does not wait for a turn in an informal chat.', '{"question":"Wenzako wanazungumza kuhusu mchezo. Unataka kusema jambo. Ufanye nini?","wrong_answer":"zungumza kwa sauti juu yao","correct_answer":"subiri mwenzako amalize, kisha useme"}'::jsonb, 'The child thinks informal means no rules.', 'The question "Wenzako wanazungumza kuhusu mchezo. Unataka kusema jambo. Ufanye nini?" with "zungumza kwa sauti juu yao" among the options.', 'Pass a talking object in a small group; only the holder speaks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T9_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M4_MAP_COVER_T9', 'KISW.G4.KUSOMA.T9_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Chooses a book by its cover picture or its thickness only.', '{"question":"Unataka kusoma kuhusu afya bora. Utachaguaje kitabu?","wrong_answer":"kwa picha nzuri ya jalada","correct_answer":"kwa kusoma anwani, maelezo ya nyuma na ukurasa wa kwanza"}'::jsonb, 'Nobody has shown the child the title, the blurb and the first page as clues.', 'The question "Unataka kusoma kuhusu afya bora. Utachaguaje kitabu?" with "kwa picha nzuri ya jalada" among the options.', 'Hold up two books; read the title and the back of each aloud; the child chooses and says which clue decided it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T9_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M4_MAP_LEVEL_T9', 'KISW.G4.KUSOMA.T9_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Chooses a text far above his reading level and gives up after a page.', '{"question":"Ukisoma ukurasa wa kwanza wa \"Siri ya Afya ya Baraka\" na hujui maneno mengi sana, ufanye nini?","wrong_answer":"endelea tu hata kama huelewi","correct_answer":"chagua matini nyingine iliyo ya kiwango chako"}'::jsonb, 'The child thinks a harder book is a better book, or chooses the book a friend chose.', 'The question "Ukisoma ukurasa wa kwanza wa "Siri ya Afya ya Baraka" na hujui maneno mengi sana, ufanye nini?" with "endelea tu hata kama huelewi" among the options.', 'The five-finger check: on one page, a finger for each unknown word; five fingers means the book is too hard for now.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T9_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M4_MAP_TITLEMSG_T9', 'KISW.G4.KUSOMA.T9_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Gives the title as the message of the text.', '{"question":"Ujumbe wa matini \"Siri ya Afya ya Baraka\" ni upi?","wrong_answer":"Siri ya Afya ya Baraka","correct_answer":"Usafi, chakula bora na mazoezi hutupa afya njema."}'::jsonb, 'The title is the only sentence about the whole text that the child is sure of.', 'The question "Ujumbe wa matini "Siri ya Afya ya Baraka" ni upi?" with "Siri ya Afya ya Baraka" among the options.', 'Ask what the writer wants the reader to learn or do; the title only names the topic.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T9_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M4_MAP_DETAIL_T9', 'KISW.G4.KUSOMA.T9_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Gives one detail of the text as its message.', '{"question":"Ni ipi ni ujumbe wa matini kuhusu afya bora?","wrong_answer":"Baraka alikunywa maji glasi nane.","correct_answer":"Usafi, chakula bora na mazoezi hutupa afya njema."}'::jsonb, 'The detail was striking and is remembered; the child has not asked what the whole text is about.', 'The question "Ni ipi ni ujumbe wa matini kuhusu afya bora?" with "Baraka alikunywa maji glasi nane." among the options.', 'Two boxes: "ujumbe" (one) and "maelezo" (many); the child sorts sentences from the text.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T9_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M4_MAP_KIND_T9', 'KISW.G4.KUSOMA.T9_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Does not tell one kind of text from another (takes a newspaper report for a story, or a poem for a story).', '{"question":"Matini yenye beti na mishororo ni ya aina gani?","wrong_answer":"hadithi","correct_answer":"shairi"}'::jsonb, 'The child has met most texts as "kitabu" and has not been shown the signs of each kind.', 'The question "Matini yenye beti na mishororo ni ya aina gani?" with "hadithi" among the options.', 'Lay out a story, a poem, a newspaper page and a dictionary; the child names one sign of each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T9_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M4_MAP_WORD_T9', 'KISW.G4.KUSOMA.T9_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Guesses a new word from how it looks, not from the sentence it is in (lishe).', '{"question":"Katika matini: \"Mama alisema lishe bora ina mboga, matunda na nafaka.\" Neno \"lishe\" lina maana gani?","wrong_answer":"kulisha mifugo","correct_answer":"chakula anachokula mtu"}'::jsonb, 'The child matches the word to a word it looks like instead of reading the sentence around it.', 'The question "Katika matini: "Mama alisema lishe bora ina mboga, matunda na nafaka." Neno "lishe" lina maana gani?" with "kulisha mifugo" among the options.', 'Cover the word; the child reads the sentence and says what word would fit; then compares.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T9_INSHA_YA_MAELEZO.INSHA_MAELEZO.M4_INS_STORY_T9', 'KISW.G4.KUANDI.T9_INSHA_YA_MAELEZO.INSHA_MAELEZO', 'Tells a story of what happened where the insha should explain or describe.', '{"question":"Ni sentensi ipi inafaa katika insha ya maelezo kuhusu \"Jinsi ya Kunawa Mikono\"?","wrong_answer":"Siku moja tulienda sokoni tukapotea.","correct_answer":"Kwanza, lowesha mikono kwa maji safi yanayotiririka."}'::jsonb, 'Stories are the kind of writing the child has done most and he falls back on it.', 'The question "Ni sentensi ipi inafaa katika insha ya maelezo kuhusu "Jinsi ya Kunawa Mikono"?" with "Siku moja tulienda sokoni tukapotea." among the options.', 'Ask what the reader should know about the topic at the end: what it is, how it works or is done.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T9_INSHA_YA_MAELEZO.INSHA_MAELEZO.M4_INS_DETAIL_T9', 'KISW.G4.KUANDI.T9_INSHA_YA_MAELEZO.INSHA_MAELEZO', 'Describes with empty words (kizuri sana, kibaya) and no detail that makes a picture.', '{"question":"Ni sentensi ipi inajenga picha dhahiri kuhusu \"Jinsi ya Kunawa Mikono\"?","wrong_answer":"Usafi ni muhimu.","correct_answer":"Kwanza, lowesha mikono kwa maji safi yanayotiririka."}'::jsonb, 'The child knows the thing well and assumes the reader sees it too.', 'The question "Ni sentensi ipi inajenga picha dhahiri kuhusu "Jinsi ya Kunawa Mikono"?" with "Usafi ni muhimu." among the options.', 'Five senses chart: what do you see, hear, smell, touch, taste? Turn one row into a sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T9_INSHA_YA_MAELEZO.INSHA_MAELEZO.M4_INS_STEPS_T9', 'KISW.G4.KUANDI.T9_INSHA_YA_MAELEZO.INSHA_MAELEZO', 'Gives the steps of how to do something in a mixed-up order.', '{"question":"Ni mpangilio upi unafaa katika maelezo ya \"Jinsi ya Kunawa Mikono\"?","wrong_answer":"suuza na kukausha, sugua kwa sekunde ishirini, paka sabuni, lowesha mikono","correct_answer":"lowesha mikono, paka sabuni, sugua kwa sekunde ishirini, suuza na kukausha"}'::jsonb, 'The child remembers the steps as a set, not as a sequence.', 'The question "Ni mpangilio upi unafaa katika maelezo ya "Jinsi ya Kunawa Mikono"?" with "suuza na kukausha, sugua kwa sekunde ishirini, paka sabuni, lowesha mikono" among the options.', 'Act out the steps; number them; write them with kwanza, kisha, mwishowe.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T9_INSHA_YA_MAELEZO.INSHA_MAELEZO.M4_INS_OFFTOPIC_T9', 'KISW.G4.KUANDI.T9_INSHA_YA_MAELEZO.INSHA_MAELEZO', 'Puts in points that are not about the title.', '{"question":"Katika insha ya maelezo yenye anwani \"Jinsi ya Kunawa Mikono\", ni sentensi ipi haifai?","wrong_answer":"Rafiki yangu ana baiskeli mpya ya rangi ya bluu.","correct_answer":"Kwanza, lowesha mikono kwa maji safi yanayotiririka."}'::jsonb, 'The child adds whatever he remembers so the insha is long enough.', 'The question "Katika insha ya maelezo yenye anwani "Jinsi ya Kunawa Mikono", ni sentensi ipi haifai?" with "Rafiki yangu ana baiskeli mpya ya rangi ya bluu." among the options.', 'Read each sentence and ask: does it tell the reader about the title? Cross out the ones that do not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T9_VINYUME_VYA_NOMINO.VINYUME_NOMINO.M4_VNOM_RELATED', 'KISW.G4.SARUFI.T9_VINYUME_VYA_NOMINO.VINYUME_NOMINO', 'Picks a related word, not the opposite (usiku-jioni, rafiki-ndugu).', '{"question":"Kinyume cha \"usiku\" ni ___.","wrong_answer":"jioni","correct_answer":"mchana"}'::jsonb, 'The child picks a word of the same family of ideas.', 'A related word as an option.', 'Is it the opposite, or only near it?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T9_VINYUME_VYA_NOMINO.VINYUME_NOMINO.M4_VNOM_SAME', 'KISW.G4.SARUFI.T9_VINYUME_VYA_NOMINO.VINYUME_NOMINO', 'Picks a word of the same meaning (furaha-raha).', '{"question":"Kinyume cha \"furaha\" ni ___.","wrong_answer":"raha","correct_answer":"huzuni"}'::jsonb, 'The child mixes the opposite with the synonym.', 'A synonym as an option.', 'Same meaning or opposite?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T9_VINYUME_VYA_NOMINO.VINYUME_NOMINO.M4_VNOM_ONE_SIDE', 'KISW.G4.SARUFI.T9_VINYUME_VYA_NOMINO.VINYUME_NOMINO', 'Gives the other word of a pair in the wrong place (mgeni-rafiki for mgeni-mwenyeji).', '{"question":"Kinyume cha \"mgeni\" ni ___.","wrong_answer":"rafiki","correct_answer":"mwenyeji"}'::jsonb, 'The child takes a word that goes with the idea.', 'A word that goes with the noun but is not its opposite.', 'Who is the visitor and who receives him?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T9_VINYUME_VYA_NOMINO.VINYUME_NOMINO.M4_VNOM_NEGATE', 'KISW.G4.SARUFI.T9_VINYUME_VYA_NOMINO.VINYUME_NOMINO', 'Makes the opposite by adding si or "si-" to the noun (si-rafiki, si urefu).', '{"question":"Kinyume cha \"rafiki\" ni kipi?","wrong_answer":"sirafiki","correct_answer":"adui"}'::jsonb, 'Making verbs negative with si- is known; the child uses it for nouns too.', 'The question "Kinyume cha "rafiki" ni kipi?" with "sirafiki" among the options.', 'A noun''s opposite is another noun; list pairs: rafiki/adui, mchana/usiku, mwanzo/mwisho.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSIKI.T10_TASHBIHI.TASHBIHI.M4_TASH_WRONG_ANIMAL', 'KISW.G4.KUSIKI.T10_TASHBIHI.TASHBIHI', 'Gives the wrong animal or thing in the simile (mrefu kama sungura).', '{"question":"Mtu mrefu sana ni mrefu kama ___.","wrong_answer":"sungura","correct_answer":"twiga"}'::jsonb, 'The child knows the idea but not the usual comparison.', 'A simile with plausible animals as options.', 'Which animal do we say is tall?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSIKI.T10_TASHBIHI.TASHBIHI.M4_TASH_NO_KAMA', 'KISW.G4.KUSIKI.T10_TASHBIHI.TASHBIHI', 'Leaves out kama, and says "Yeye ni twiga" as a simile.', '{"question":"Ni tashbihi ipi?","wrong_answer":"Yeye ni twiga","correct_answer":"Yeye ni mrefu kama twiga"}'::jsonb, 'The child mixes a simile with a metaphor.', 'A simile and a metaphor as options.', 'A simile has the word kama.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSIKI.T10_TASHBIHI.TASHBIHI.M4_TASH_LITERAL', 'KISW.G4.KUSIKI.T10_TASHBIHI.TASHBIHI', 'Takes the simile word for word (the person is really a giraffe).', '{"question":"\"Baba ni mrefu kama twiga\" maana yake nini?","wrong_answer":"Baba ni twiga","correct_answer":"Baba ni mrefu sana"}'::jsonb, 'The child does not read the comparison as a way to describe.', 'A meaning question for a simile.', 'What is the animal used to show?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSIKI.T10_TASHBIHI.TASHBIHI.M4_TASH_QUALITY', 'KISW.G4.KUSIKI.T10_TASHBIHI.TASHBIHI', 'Joins the right animal to the wrong quality (mfupi kama twiga).', '{"question":"Kamilisha tashbihi: mrefu kama ___","wrong_answer":"nyoka","correct_answer":"twiga"}'::jsonb, 'The child knows the animals of similes but not which quality each stands for.', 'The question "Kamilisha tashbihi: mrefu kama ___" with "nyoka" among the options.', 'Make a chart: twiga - urefu, nyoka - wembamba?, tembo - unene; test each simile against the chart.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T10_KUSOMA_KIDIJITALI.KUSOMA_KIDIJITALI.M4_KID_FOLDER_T10', 'KISW.G4.KUSOMA.T10_KUSOMA_KIDIJITALI.KUSOMA_KIDIJITALI', 'Mixes up a folder and a file: looks for the passage on the screen without opening the folder it is in.', '{"question":"Kifungu \"Usalama wetu\" kimehifadhiwa ndani ya folda \"Kiswahili\". Utakifunguaje?","wrong_answer":"bonyeza \"Usalama wetu\" kwenye skrini ya mwanzo","correct_answer":"fungua folda \"Kiswahili\", kisha bonyeza mara mbili faili \"Usalama wetu\""}'::jsonb, 'The child has only used apps on a phone, where there are no folders.', 'The question "Kifungu "Usalama wetu" kimehifadhiwa ndani ya folda "Kiswahili". Utakifunguaje?" with "bonyeza "Usalama wetu" kwenye skrini ya mwanzo" among the options.', 'Show a real folder (a box file) holding papers; then the same on the screen.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T10_KUSOMA_KIDIJITALI.KUSOMA_KIDIJITALI.M4_KID_SEARCH_T10', 'KISW.G4.KUSOMA.T10_KUSOMA_KIDIJITALI.KUSOMA_KIDIJITALI', 'Types a whole long question, with spelling mistakes, into the search box.', '{"question":"Unatafuta habari kuhusu kukabiliana na uhalifu. Utaandika nini kwenye kisanduku cha kutafutia?","wrong_answer":"naomba unipe habari zote kuhusu kukabiliana na uhalifu tafadhali","correct_answer":"usalama watoto uhalifu"}'::jsonb, 'The child talks to the search box as to a person.', 'The question "Unatafuta habari kuhusu kukabiliana na uhalifu. Utaandika nini kwenye kisanduku cha kutafutia?" with "naomba unipe habari zote kuhusu kukabiliana na uhalifu tafadhali" among the options.', 'Underline the two or three words that carry the meaning; search with those; compare the results.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T10_KUSOMA_KIDIJITALI.KUSOMA_KIDIJITALI.M4_KID_POPUP_T10', 'KISW.G4.KUSOMA.T10_KUSOMA_KIDIJITALI.KUSOMA_KIDIJITALI', 'Clicks a pop-up or an advert that says he has won a prize.', '{"question":"Ukiwa unasoma, ujumbe unatokea: \"Umeshinda simu! Bonyeza hapa.\" Ufanye nini?","wrong_answer":"bonyeza ili kupokea simu","correct_answer":"usibonyeze; funga ujumbe na umwambie mwalimu au mzazi"}'::jsonb, 'Offers of prizes are exciting and the child does not know they are traps.', 'The question "Ukiwa unasoma, ujumbe unatokea: "Umeshinda simu! Bonyeza hapa." Ufanye nini?" with "bonyeza ili kupokea simu" among the options.', 'Show two screenshots, one real page and one trap; the child finds three signs of the trap.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T10_KUSOMA_KIDIJITALI.KUSOMA_KIDIJITALI.M4_KID_SITE_T10', 'KISW.G4.KUSOMA.T10_KUSOMA_KIDIJITALI.KUSOMA_KIDIJITALI', 'Uses any site that comes up and gives his name, school or phone number when a site asks.', '{"question":"Tovuti inakuuliza jina lako kamili, shule yako na nambari ya simu ya mzazi kabla ya kusoma hadithi. Ufanye nini?","wrong_answer":"jaza ili usome hadithi","correct_answer":"usijaze; tumia tovuti salama aliyokupa mwalimu"}'::jsonb, 'The child wants the story and does not see personal details as worth protecting.', 'The question "Tovuti inakuuliza jina lako kamili, shule yako na nambari ya simu ya mzazi kabla ya kusoma hadithi. Ufanye nini?" with "jaza ili usome hadithi" among the options.', 'List the details that are private; practise saying no to a form.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T10_KUSOMA_KIDIJITALI.KUSOMA_KIDIJITALI.M4_KID_ORDER_T10', 'KISW.G4.KUSOMA.T10_KUSOMA_KIDIJITALI.KUSOMA_KIDIJITALI', 'Puts the steps of finding and reading a passage in the wrong order (reads before searching, or searches before switching on).', '{"question":"Ni hatua ipi huja kwanza?","wrong_answer":"andika maneno ya kutafutia","correct_answer":"washa tarakilishi na ufungue kivinjari"}'::jsonb, 'The child has watched an adult do the steps quickly and remembers the parts, not the order.', 'The question "Ni hatua ipi huja kwanza?" with "andika maneno ya kutafutia" among the options.', 'Step cards: the child orders them, then does them on a real device.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T10_INSHA_YA_MASIMULIZI.INSHA_MASIMULIZI.M4_INS_FACTS_T10', 'KISW.G4.KUANDI.T10_INSHA_YA_MASIMULIZI.INSHA_MASIMULIZI', 'Writes facts or an explanation where a story of events is asked.', '{"question":"Ni sentensi ipi ni mwanzo wa insha ya masimulizi yenye anwani \"Mwizi Aliyekamatwa Sokoni\"?","wrong_answer":"Wizi ni kosa kubwa katika jamii.","correct_answer":"Mwizi alinyakua mkoba wa mama mmoja akakimbia."}'::jsonb, 'The child knows a lot about the topic and writes what he knows instead of telling what happened.', 'The question "Ni sentensi ipi ni mwanzo wa insha ya masimulizi yenye anwani "Mwizi Aliyekamatwa Sokoni"?" with "Wizi ni kosa kubwa katika jamii." among the options.', 'Ask: who, where, what happened first, then, in the end? A story answers these; an explanation does not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T10_INSHA_YA_MASIMULIZI.INSHA_MASIMULIZI.M4_INS_TENSE_T10', 'KISW.G4.KUANDI.T10_INSHA_YA_MASIMULIZI.INSHA_MASIMULIZI', 'Tells a past story in the present tense (-na-), or mixes -na- and -li- in one story.', '{"question":"Ni sentensi ipi inafaa katika masimulizi ya jambo lililotokea jana: \"Mwizi Aliyekamatwa Sokoni\"?","wrong_answer":"Mwizi ananyakua mkoba wa mama mmoja anakimbia.","correct_answer":"Mwizi alinyakua mkoba wa mama mmoja akakimbia."}'::jsonb, 'The child writes as he speaks while remembering, and English stories in class are told in the present too.', 'The question "Ni sentensi ipi inafaa katika masimulizi ya jambo lililotokea jana: "Mwizi Aliyekamatwa Sokoni"?" with "Mwizi ananyakua mkoba wa mama mmoja anakimbia." among the options.', 'Circle every verb; check its tense marker against the time words (jana, siku moja).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T10_INSHA_YA_MASIMULIZI.INSHA_MASIMULIZI.M4_INS_ORDER_T10', 'KISW.G4.KUANDI.T10_INSHA_YA_MASIMULIZI.INSHA_MASIMULIZI', 'Puts the events in an order that cannot have happened (the end before the start), with no linking words.', '{"question":"Ni mpangilio upi wa matukio unafaa katika insha \"Mwizi Aliyekamatwa Sokoni\"?","wrong_answer":"mama alirudishiwa mkoba, polisi walimkamata, watu walipiga kelele, mwizi alinyakua mkoba","correct_answer":"mwizi alinyakua mkoba, watu walipiga kelele, polisi walimkamata, mama alirudishiwa mkoba"}'::jsonb, 'The child writes events as they come to mind; nobody has asked for a plan first.', 'The question "Ni mpangilio upi wa matukio unafaa katika insha "Mwizi Aliyekamatwa Sokoni"?" with "mama alirudishiwa mkoba, polisi walimkamata, watu walipiga kelele, mwizi alinyakua mkoba" among the options.', 'Plan with three boxes (mwanzo, kati, mwisho) and linking words (kwanza, kisha, hatimaye) before writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T10_INSHA_YA_MASIMULIZI.INSHA_MASIMULIZI.M4_INS_END_T10', 'KISW.G4.KUANDI.T10_INSHA_YA_MASIMULIZI.INSHA_MASIMULIZI', 'Ends the insha abruptly ("Mwisho." or "The end") with no closing paragraph (hitimisho).', '{"question":"Ni ipi ni hitimisho bora la insha \"Mwizi Aliyekamatwa Sokoni\"?","wrong_answer":"Mwisho.","correct_answer":"Tangu siku hiyo, nimejifunza kuwa mwangalifu kila wakati."}'::jsonb, 'Storybooks for young readers end with "Mwisho" and the child copies that.', 'The question "Ni ipi ni hitimisho bora la insha "Mwizi Aliyekamatwa Sokoni"?" with "Mwisho." among the options.', 'Show three endings; the child picks the one that closes the main idea or the lesson.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T10_NYAKATI_NA_HALI.NYAKATI.M4_NYA_NA_ALL', 'KISW.G4.SARUFI.T10_NYAKATI_NA_HALI.NYAKATI', 'Uses -na- for every time, whatever the time word.', '{"question":"Jana, Juma a___soma kitabu.","wrong_answer":"na","correct_answer":"li"}'::jsonb, 'The child has fixed -na- as the way to make a verb.', 'Time words (jana, kesho) next to -na-.', 'Read the time word first: jana, now, or kesho?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T10_NYAKATI_NA_HALI.NYAKATI.M4_NYA_SWAP', 'KISW.G4.SARUFI.T10_NYAKATI_NA_HALI.NYAKATI', 'Swaps -li- and -ta- (kesho alisoma).', '{"question":"Kesho, Wanjiru a___soma kitabu.","wrong_answer":"li","correct_answer":"ta"}'::jsonb, 'The child knows the markers but not which time each is for.', 'Past and future time words in turn.', 'Has it happened, or will it happen?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T10_NYAKATI_NA_HALI.NYAKATI.M4_NYA_PERSON', 'KISW.G4.SARUFI.T10_NYAKATI_NA_HALI.NYAKATI', 'Keeps the tense right and changes the person prefix (wanasoma for tunasoma).', '{"question":"Chagua kitenzi: Jana sisi ___ kwa basi.","wrong_answer":"walisafiri","correct_answer":"tulisafiri"}'::jsonb, 'The child looks at the tense and not at the person.', 'The same verb with different persons.', 'Who is it? Sisi is tu-.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T10_NYAKATI_NA_HALI.NYAKATI.M4_NYA_TIME_WORD', 'KISW.G4.SARUFI.T10_NYAKATI_NA_HALI.NYAKATI', 'Ignores the time word in the sentence (jana, kesho, sasa) and keeps the tense of the sentence before.', '{"question":"Jaza: Kesho Juma ___ (enda) Nairobi.","wrong_answer":"alienda","correct_answer":"atakwenda"}'::jsonb, 'The child copies the tense of the last verb he wrote.', 'The question "Jaza: Kesho Juma ___ (enda) Nairobi." with "alienda" among the options.', 'Underline the time word first; it decides the marker: jana -li-, sasa -na-, kesho -ta-.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSIKI.T11_MASIMULIZI.MASIMULIZI.M4_MSM_DETAIL_T11', 'KISW.G4.KUSIKI.T11_MASIMULIZI.MASIMULIZI', 'Gives a detail of the narration as its message.', '{"question":"Ulisikiliza masimulizi kuhusu mama aliyeuza mboga sokoni na kuweka akiba. Ujumbe wake ni upi?","wrong_answer":"Mama aliuza sukumawiki sokoni.","correct_answer":"Tukiweka akiba kidogo kidogo, tunaweza kutimiza mahitaji yetu."}'::jsonb, 'The detail was vivid; the child has not asked what the whole narration teaches.', 'The question "Ulisikiliza masimulizi kuhusu mama aliyeuza mboga sokoni na kuweka akiba. Ujumbe wake ni upi?" with "Mama aliuza sukumawiki sokoni." among the options.', 'After listening, ask: what did the speaker want us to learn? Then: what is one thing that happened?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSIKI.T11_MASIMULIZI.MASIMULIZI.M4_MSM_ORDER_T11', 'KISW.G4.KUSIKI.T11_MASIMULIZI.MASIMULIZI', 'Retells the events in a mixed order, starting with the most exciting part.', '{"question":"Unaposimulia, unaanza na nini?","wrong_answer":"sehemu ya kusisimua zaidi","correct_answer":"mwanzo: nani, wapi, lini"}'::jsonb, 'The child jumps to the part that impressed him most.', 'The question "Unaposimulia, unaanza na nini?" with "sehemu ya kusisimua zaidi" among the options.', 'Retell with three fingers: mwanzo, kati, mwisho.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSIKI.T11_MASIMULIZI.MASIMULIZI.M4_MSM_GESTURE_T11', 'KISW.G4.KUSIKI.T11_MASIMULIZI.MASIMULIZI', 'Uses gestures or a face that do not match the words (smiles while telling a sad part, stands still for an action).', '{"question":"Unasimulia: \"Tulifurahi sana tulipopata faida!\" Ishara ipi inafaa?","wrong_answer":"kukunja uso na kuinamisha kichwa","correct_answer":"kutabasamu na kuinua mikono"}'::jsonb, 'The child is nervous and does not link the body to the words.', 'The question "Unasimulia: "Tulifurahi sana tulipopata faida!" Ishara ipi inafaa?" with "kukunja uso na kuinamisha kichwa" among the options.', 'Mirror game in pairs: one says a line, the other shows the feeling; swap.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSIKI.T11_MASIMULIZI.MASIMULIZI.M4_MSM_MIX_T11', 'KISW.G4.KUSIKI.T11_MASIMULIZI.MASIMULIZI', 'Mixes English or Sheng into the telling (Then tukaenda..., ilikuwa poa sana).', '{"question":"Ni sentensi ipi inafaa unaposimulia darasani?","wrong_answer":"Then tukaenda home, ilikuwa poa sana.","correct_answer":"Kisha tukaenda nyumbani; ilikuwa siku nzuri sana."}'::jsonb, 'The child narrates as he talks with friends.', 'The question "Ni sentensi ipi inafaa unaposimulia darasani?" with "Then tukaenda home, ilikuwa poa sana." among the options.', 'Record a telling; play it back; the child finds the non-Kiswahili words and replaces them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSIKI.T11_MASIMULIZI.MASIMULIZI.M4_MSM_OFFTOPIC_T11', 'KISW.G4.KUSIKI.T11_MASIMULIZI.MASIMULIZI', 'Tells a story that is not on the topic given (mapato (income)).', '{"question":"Mada ni mapato (income). Ni masimulizi yapi yanafaa?","wrong_answer":"Siku nilipotazama mechi ya mpira","correct_answer":"Siku mama aliyeuza mboga sokoni na kuweka akiba"}'::jsonb, 'The child tells the story he knows best, whatever the topic.', 'The question "Mada ni mapato (income). Ni masimulizi yapi yanafaa?" with "Siku nilipotazama mechi ya mpira" among the options.', 'Write the topic on the board; before telling, the child says in one sentence how his story fits it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T11_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M4_UFS_WORDBYWORD_T11', 'KISW.G4.KUSOMA.T11_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads word by word or syllable by syllable, so the sentence has no meaning when heard.', '{"question":"Ni usomaji upi ni wa ufasaha: \"Baba aliuza mahindi na kuweka pesa benki.\"?","wrong_answer":"Baba ... aliuza ... mahindi ... na ... kuweka ... pesa ... benki.","correct_answer":"Baba aliuza mahindi na kuweka pesa benki."}'::jsonb, 'The child is still decoding each word and has not yet learnt to read a phrase as one piece.', 'The question "Ni usomaji upi ni wa ufasaha: "Baba aliuza mahindi na kuweka pesa benki."?" with "Baba ... aliuza ... mahindi ... na ... kuweka ... pesa ... benki." among the options.', 'Echo reading: the teacher reads a phrase, the child repeats it as one breath; then phrase-cut the passage with slashes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T11_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M4_UFS_RACE_T11', 'KISW.G4.KUSOMA.T11_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads as fast as possible and thinks the fastest reader is the best.', '{"question":"Ni kasi ipi ifaayo ya kusoma kifungu darasani?","wrong_answer":"haraka iwezekanavyo","correct_answer":"kasi ya kuzungumza, ili kila neno lisikike"}'::jsonb, 'Reading races in class reward speed; the child has not been asked whether listeners understood.', 'The question "Ni kasi ipi ifaayo ya kusoma kifungu darasani?" with "haraka iwezekanavyo" among the options.', 'Time two readings: one very fast, one at speaking pace; listeners answer one question after each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T11_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M4_UFS_FLAT_T11', 'KISW.G4.KUSOMA.T11_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads a question and an exclamation in the same flat voice as a statement.', '{"question":"Sentensi \"Je, umeweka akiba yako wapi?\" inasomwa vipi?","wrong_answer":"kwa sauti ileile ya sentensi ya kawaida","correct_answer":"sauti hupanda mwishoni kwa sababu ni swali"}'::jsonb, 'The child looks at the words and not at the mark at the end.', 'The question "Sentensi "Je, umeweka akiba yako wapi?" inasomwa vipi?" with "kwa sauti ileile ya sentensi ya kawaida" among the options.', 'Read the same words three ways (. ? !); the child points at the mark that matches each reading.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T11_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M4_UFS_NOPAUSE_T11', 'KISW.G4.KUSOMA.T11_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads on through the koma and the kikomo without a pause.', '{"question":"Unasoma: \"Hongera, umepata faida kubwa!\" Unasimama wapi kidogo?","wrong_answer":"hapana mahali, unasoma moja kwa moja","correct_answer":"kwenye koma na kwenye kikomo au alama ya hisi"}'::jsonb, 'The marks are read as decoration; the child has not linked them to breath.', 'The question "Unasoma: "Hongera, umepata faida kubwa!" Unasimama wapi kidogo?" with "hapana mahali, unasoma moja kwa moja" among the options.', 'Clap once at a koma, twice at a kikomo while reading together.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUSOMA.T11_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M4_UFS_SOUND_T11', 'KISW.G4.KUSOMA.T11_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Says /l/ for /r/ or /r/ for /l/ while reading (biashara read as biashala).', '{"question":"Neno \"biashara\" linatamkwa vipi?","wrong_answer":"biashala","correct_answer":"biashara"}'::jsonb, 'The first language of the child does not separate these sounds, so the reading carries the home sound.', 'The question "Neno "biashara" linatamkwa vipi?" with "biashala" among the options.', 'Make a list of the passage words with the hard sound; practise them before reading the passage.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T11_BARUA_YA_KIRAFIKI.KUANDIKA_BARUA.M4_INS_FORMAL_T11', 'KISW.G4.KUANDI.T11_BARUA_YA_KIRAFIKI.KUANDIKA_BARUA', 'Writes to a friend in the stiff words of an official letter (Mheshimiwa, Kuhusu:, Wako mtiifu).', '{"question":"Ni salamu ipi inafaa katika barua kwa rafiki?","wrong_answer":"Mheshimiwa Bwana,","correct_answer":"Mpendwa rafiki yangu Amina,"}'::jsonb, 'The child has seen official letters at school and thinks every letter is written that way.', 'The question "Ni salamu ipi inafaa katika barua kwa rafiki?" with "Mheshimiwa Bwana," among the options.', 'Put a friendly and an official letter side by side; the child highlights the words that differ.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T11_BARUA_YA_KIRAFIKI.KUANDIKA_BARUA.M4_INS_NOASK_T11', 'KISW.G4.KUANDI.T11_BARUA_YA_KIRAFIKI.KUANDIKA_BARUA', 'Starts with the news straight after the greeting, with no asking after the friend (maulizo ya hali).', '{"question":"Baada ya salamu, ni sentensi ipi inafuata katika barua ya kirafiki?","wrong_answer":"Nataka kukueleza kuhusu safari yetu.","correct_answer":"Hujambo? Natumai u buheri wa afya."}'::jsonb, 'The child goes to what he wants to say, as in a text message.', 'The question "Baada ya salamu, ni sentensi ipi inafuata katika barua ya kirafiki?" with "Nataka kukueleza kuhusu safari yetu." among the options.', 'Order the parts on cards: anwani, tarehe, salamu, maulizo ya hali, ujumbe, hitimisho, jina.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T11_BARUA_YA_KIRAFIKI.KUANDIKA_BARUA.M4_INS_DATE_T11', 'KISW.G4.KUANDI.T11_BARUA_YA_KIRAFIKI.KUANDIKA_BARUA', 'Leaves out the date or writes it in the middle of the letter.', '{"question":"Tarehe huandikwa wapi katika barua ya kirafiki?","wrong_answer":"mwishoni, baada ya jina","correct_answer":"chini ya anwani ya mwandishi, upande wa kulia juu"}'::jsonb, 'The date is not part of what the child wants to say, so he forgets it.', 'The question "Tarehe huandikwa wapi katika barua ya kirafiki?" with "mwishoni, baada ya jina" among the options.', 'Label a model letter; the child places a date card on a blank layout.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.KUANDI.T11_BARUA_YA_KIRAFIKI.KUANDIKA_BARUA.M4_INS_SIGN_T11', 'KISW.G4.KUANDI.T11_BARUA_YA_KIRAFIKI.KUANDIKA_BARUA', 'Ends with "Wako mtiifu" and a full name and title, as in an official letter.', '{"question":"Ni hitimisho lipi linafaa katika barua kwa rafiki?","wrong_answer":"Wako mtiifu, Bw. Juma Hamisi","correct_answer":"Ni mimi rafiki yako, Juma"}'::jsonb, 'Again the official model is the only one the child has copied.', 'The question "Ni hitimisho lipi linafaa katika barua kwa rafiki?" with "Wako mtiifu, Bw. Juma Hamisi" among the options.', 'Collect three friendly closings and keep them in the exercise book.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T11_UKANUSHAJI.UKANUSHAJI.M4_NEG_HA_ONLY', 'KISW.G4.SARUFI.T11_UKANUSHAJI.UKANUSHAJI', 'Only adds ha- or si- and keeps the tense marker (hanasoma, sinasoma).', '{"question":"Kanusha: \"Mimi ninasoma.\"","wrong_answer":"Mimi sinasoma","correct_answer":"Mimi sisomi"}'::jsonb, 'The child does not know that the marker changes in the negative.', 'A negative made by only adding ha- or si-.', 'In the present negative, -na- goes and the verb ends in -i.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T11_UKANUSHAJI.UKANUSHAJI.M4_NEG_KEEP_LI', 'KISW.G4.SARUFI.T11_UKANUSHAJI.UKANUSHAJI', 'Keeps -li- or -ta- after ha- (halipika, hatapika for hakupika).', '{"question":"Kanusha: \"Wanjiru alipika.\"","wrong_answer":"Wanjiru halipika","correct_answer":"Wanjiru hakupika"}'::jsonb, 'The child puts ha- in front and leaves the rest.', 'A past verb with ha- put in front.', '-li- becomes -ku- in the past negative.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T11_UKANUSHAJI.UKANUSHAJI.M4_NEG_TENSE', 'KISW.G4.SARUFI.T11_UKANUSHAJI.UKANUSHAJI', 'Gives the negative of another time (hasomi for hakusoma).', '{"question":"Kanusha: \"Wanafunzi wanaimba.\"","wrong_answer":"Wanafunzi hawakuimba","correct_answer":"Wanafunzi hawaimbi"}'::jsonb, 'The child negates the verb but does not keep the time.', 'Negatives of the three times side by side.', 'Which time was the first sentence in?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T11_UKANUSHAJI.UKANUSHAJI.M4_NEG_NOT_NEG', 'KISW.G4.SARUFI.T11_UKANUSHAJI.UKANUSHAJI', 'Takes a positive verb for a negative one.', '{"question":"Ni neno lipi limekanushwa?","wrong_answer":"anasoma","correct_answer":"hasomi"}'::jsonb, 'The child does not look for the ha-, si-, hu- or ku-.', 'A negative and a positive verb together.', 'Which verb says that it did not, does not or will not happen?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T11_UKUBWA_WA_NOMINO.UKUBWA.M4_UKU_KI', 'KISW.G4.SARUFI.T11_UKUBWA_WA_NOMINO.UKUBWA', 'Gives the small form (ki-) for the big form (kijiti for jiti).', '{"question":"Mti mkubwa sana huitwa ___.","wrong_answer":"kijiti","correct_answer":"jiti"}'::jsonb, 'The child mixes ji- (big) and ki- (small).', 'Both forms as options.', 'Big is ji-. Small is ki-.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T11_UKUBWA_WA_NOMINO.UKUBWA.M4_UKU_SAME', 'KISW.G4.SARUFI.T11_UKUBWA_WA_NOMINO.UKUBWA', 'Keeps the noun as it is (mti mkubwa for jiti).', '{"question":"Mji mkubwa sana huitwa ___.","wrong_answer":"mji","correct_answer":"jiji"}'::jsonb, 'The child uses the adjective mkubwa and does not change the noun.', 'The plain noun as an option.', 'Big form: the noun itself changes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T11_UKUBWA_WA_NOMINO.UKUBWA.M4_UKU_PL', 'KISW.G4.SARUFI.T11_UKUBWA_WA_NOMINO.UKUBWA', 'Gives one noun where there are many (jiti for majiti).', '{"question":"Miti mikubwa sana huitwa ___.","wrong_answer":"jiti","correct_answer":"majiti"}'::jsonb, 'The child does not change the form for many.', 'Singular and plural big forms in turn.', 'Count: one or many? Many takes ma-.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T11_UKUBWA_WA_NOMINO.UKUBWA.M4_UKU_AGREE', 'KISW.G4.SARUFI.T11_UKUBWA_WA_NOMINO.UKUBWA', 'Gives the big form but keeps the agreement of the ordinary noun (jitu anakuja for jitu linakuja).', '{"question":"Jaza: Jitu ___ kuja.","wrong_answer":"anakuja","correct_answer":"linakuja"}'::jsonb, 'The child changes the noun but not the verb.', 'The question "Jaza: Jitu ___ kuja." with "anakuja" among the options.', 'The big form moves to LI-YA: jitu li-, majitu ya-.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T11_UDOGO_WA_NOMINO.UDOGO.M4_UDO_JI', 'KISW.G4.SARUFI.T11_UDOGO_WA_NOMINO.UDOGO', 'Gives the big form (ji-) for the small form (jiji for kijiji).', '{"question":"Mji mdogo sana huitwa ___.","wrong_answer":"jiji","correct_answer":"kijiji"}'::jsonb, 'The child mixes ji- (big) and ki- (small).', 'Both forms as options.', 'Small is ki-. Big is ji-.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T11_UDOGO_WA_NOMINO.UDOGO.M4_UDO_SAME', 'KISW.G4.SARUFI.T11_UDOGO_WA_NOMINO.UDOGO', 'Keeps the noun as it is (mto mdogo for kijito).', '{"question":"Mto mdogo sana huitwa ___.","wrong_answer":"mto","correct_answer":"kijito"}'::jsonb, 'The child uses the adjective mdogo and does not change the noun.', 'The plain noun as an option.', 'Small form: the noun itself changes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T11_UDOGO_WA_NOMINO.UDOGO.M4_UDO_PL', 'KISW.G4.SARUFI.T11_UDOGO_WA_NOMINO.UDOGO', 'Gives one noun where there are many (kijiti for vijiti).', '{"question":"Miti midogo sana huitwa ___.","wrong_answer":"kijiti","correct_answer":"vijiti"}'::jsonb, 'The child does not change the form for many.', 'Singular and plural small forms in turn.', 'Count: one or many? Many takes vi-.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G4.SARUFI.T11_UDOGO_WA_NOMINO.UDOGO.M4_UDO_AGREE', 'KISW.G4.SARUFI.T11_UDOGO_WA_NOMINO.UDOGO', 'Gives the small form but keeps the agreement of the ordinary noun (kijito umejaa for kijito kimejaa).', '{"question":"Jaza: Kijito ___ jaa maji.","wrong_answer":"umejaa","correct_answer":"kimejaa"}'::jsonb, 'The child changes the noun but not the verb.', 'The question "Jaza: Kijito ___ jaa maji." with "umejaa" among the options.', 'The small form moves to KI-VI: kijito ki-, vijito vi-.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
